CREATE OR REPLACE FUNCTION openpc.guard_participant_lifecycle_history()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
BEGIN
 RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-HISTORY-IMMUTABLE';
END $$;
DROP TRIGGER IF EXISTS participant_lifecycle_history ON control.participant_lifecycle_transition;
CREATE TRIGGER participant_lifecycle_history BEFORE UPDATE OR DELETE ON control.participant_lifecycle_transition
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_participant_lifecycle_history();

CREATE OR REPLACE FUNCTION openpc.require_participant_lifecycle_history()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE mode text:=current_setting('openpc.context_mode');
 owner uuid:=nullif(current_setting('openpc.participant_id'),'')::uuid;
 privacy uuid:=nullif(current_setting('openpc.privacy_domain_id'),'')::uuid;
 op uuid:=current_setting('openpc.operation_id')::uuid;
 action text:=current_setting('openpc.action_intent_id'); valid boolean;
BEGIN
 PERFORM openpc.set_request_context('PARTICIPANT',NEW.participant_id,NEW.privacy_domain_id,op,action,true);
 SELECT EXISTS(SELECT 1 FROM control.participant p JOIN control.outbox_event event ON event.participant_id=p.participant_id
   AND event.event_id=NEW.operation_id AND event.event_type='openpc.identity.participant.epoch.advanced.v1'
   WHERE p.participant_id=NEW.participant_id AND p.authority_epoch=NEW.new_epoch AND p.row_version=NEW.revision
    AND p.root_privacy_domain_id=NEW.privacy_domain_id
    AND (p.archived_at IS NOT NULL)=(NEW.mutation='ARCHIVE')) INTO valid;
 IF NOT coalesce(valid,false) THEN RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-LIFECYCLE-EFFECT'; END IF;
 PERFORM openpc.set_request_context('PARTICIPANT',NEW.source_participant_id,NEW.source_privacy_domain_id,op,action,true);
 SELECT EXISTS(SELECT 1 FROM control.mutation_candidate candidate JOIN control.mutation_evidence evidence
   ON evidence.participant_id=candidate.participant_id AND evidence.operation_id=candidate.consumed_operation_id
    AND evidence.candidate_digest=candidate.candidate_digest AND evidence.catalog_operation_id=candidate.catalog_operation_id
   JOIN control.idempotency_record receipt ON receipt.participant_id=candidate.participant_id
    AND receipt.operation_id=NEW.operation_id AND receipt.terminal_state='COMMITTED'
   WHERE candidate.participant_id=NEW.source_participant_id AND candidate.privacy_domain_id=NEW.source_privacy_domain_id
    AND candidate.state='CONSUMED' AND candidate.consumed_operation_id=NEW.operation_id
    AND candidate.catalog_operation_id='ID-OP-PARTICIPANT-'||NEW.mutation AND candidate.resource_id=NEW.participant_id
    AND candidate.candidate_document->>'privacyDomainId'=NEW.privacy_domain_id::text
    AND candidate.candidate_document->>'expectedEpoch'=NEW.prior_epoch::text
    AND candidate.expected_revision=NEW.revision-1 AND receipt.result_payload#>>'{result,epoch}'=NEW.new_epoch::text)
 INTO valid;
 PERFORM openpc.set_request_context(mode,owner,privacy,op,action,privacy IS NOT NULL);
 IF NOT coalesce(valid,false) THEN RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-LIFECYCLE-PROVENANCE'; END IF;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS participant_lifecycle_history_provenance ON control.participant_lifecycle_transition;
CREATE CONSTRAINT TRIGGER participant_lifecycle_history_provenance AFTER INSERT ON control.participant_lifecycle_transition
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_participant_lifecycle_history();

CREATE OR REPLACE FUNCTION openpc.require_participant_lifecycle_transition()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE transition control.participant_lifecycle_transition%ROWTYPE;
 mode text; owner uuid; privacy uuid; op uuid; action text;
 valid boolean;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-HISTORY-RETAINED'; END IF;
 IF NEW.archived_at IS NOT DISTINCT FROM OLD.archived_at THEN RETURN NULL; END IF;
 mode:=current_setting('openpc.context_mode');
 owner:=nullif(current_setting('openpc.participant_id'),'')::uuid;
 privacy:=nullif(current_setting('openpc.privacy_domain_id'),'')::uuid;
 op:=current_setting('openpc.operation_id')::uuid;
 action:=current_setting('openpc.action_intent_id');
 IF NOT ((OLD.state='ACTIVE' AND NEW.state='SUSPENDED' AND OLD.archived_at IS NULL AND NEW.archived_at IS NOT NULL)
      OR (OLD.state='SUSPENDED' AND NEW.state='ACTIVE' AND OLD.archived_at IS NOT NULL AND NEW.archived_at IS NULL))
    OR NEW.authority_epoch<>OLD.authority_epoch+1 OR NEW.row_version<>OLD.row_version+1 THEN
  RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-LIFECYCLE-TRANSITION';
 END IF;
 PERFORM openpc.set_request_context('PLATFORM',NEW.participant_id,null,op,action,false);
 SELECT * INTO transition FROM control.participant_lifecycle_transition
  WHERE participant_id=NEW.participant_id AND new_epoch=NEW.authority_epoch AND prior_epoch=OLD.authority_epoch
   AND revision=NEW.row_version AND mutation=CASE WHEN NEW.archived_at IS NULL THEN 'RESTORE' ELSE 'ARCHIVE' END;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-LIFECYCLE-HISTORY'; END IF;
 PERFORM openpc.set_request_context('PARTICIPANT',transition.source_participant_id,transition.source_privacy_domain_id,op,action,true);
 SELECT EXISTS(
  SELECT 1 FROM control.mutation_candidate candidate
  JOIN control.mutation_evidence evidence ON evidence.participant_id=candidate.participant_id
   AND evidence.operation_id=candidate.consumed_operation_id AND evidence.candidate_digest=candidate.candidate_digest
   AND evidence.catalog_operation_id=candidate.catalog_operation_id AND evidence.principal_id<>evidence.checker_principal_id
  JOIN control.idempotency_record receipt ON receipt.participant_id=candidate.participant_id
   AND receipt.operation_id=candidate.consumed_operation_id AND receipt.terminal_state='COMMITTED'
  WHERE candidate.participant_id=transition.source_participant_id AND candidate.privacy_domain_id=transition.source_privacy_domain_id
   AND candidate.consumed_operation_id=transition.operation_id AND candidate.state='CONSUMED'
   AND candidate.catalog_operation_id='ID-OP-PARTICIPANT-'||transition.mutation
   AND candidate.resource_id=NEW.participant_id AND candidate.candidate_document->>'participantId'=NEW.participant_id::text
   AND candidate.candidate_document->>'expectedEpoch'=OLD.authority_epoch::text
   AND candidate.expected_revision=OLD.row_version
   AND receipt.result_payload#>>'{result,epoch}'=NEW.authority_epoch::text
 ) INTO valid;
 PERFORM openpc.set_request_context(mode,owner,privacy,op,action,privacy IS NOT NULL);
 IF NOT coalesce(valid,false) THEN RAISE EXCEPTION 'PC-AUTH-0002-PARTICIPANT-LIFECYCLE-PROVENANCE'; END IF;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS participant_lifecycle_transition ON control.participant;
CREATE CONSTRAINT TRIGGER participant_lifecycle_transition AFTER UPDATE OR DELETE ON control.participant
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_participant_lifecycle_transition();


-- Root custody is a transaction fence, not permission to update the root.
-- Keep application UPDATE rights absent; the owner retains the lock under RLS.
CREATE OR REPLACE FUNCTION openpc.lock_platform_scope_context(p_root_id uuid)
RETURNS SETOF control.platform_context
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
BEGIN
 PERFORM openpc.assert_request_context(false);
 RETURN QUERY SELECT p.* FROM control.platform_context p
 WHERE p.platform_context_id=p_root_id AND p.state='ACTIVE'
 AND EXISTS(SELECT 1 FROM control.authority_envelope e
   WHERE e.platform_context_id=p.platform_context_id
     AND e.participant_id=openpc.current_participant_id())
 FOR SHARE OF p;
END $$;
REVOKE ALL ON FUNCTION openpc.lock_platform_scope_context(uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.guard_platform_context()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-CONTEXT'; END IF;
 IF NEW.platform_context_id<>OLD.platform_context_id OR NEW.owner_participant_id<>OLD.owner_participant_id
   OR NEW.created_at<>OLD.created_at OR OLD.state='RETIRED'
   OR NEW.authority_epoch<>OLD.authority_epoch+1 OR NEW.row_version<>OLD.row_version+1
   OR NEW.updated_at<=OLD.updated_at THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-CONTEXT';
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS platform_context_monotonic ON control.platform_context;
CREATE TRIGGER platform_context_monotonic BEFORE UPDATE OR DELETE ON control.platform_context
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_platform_context();

CREATE OR REPLACE FUNCTION openpc.guard_envelope_platform_binding()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control AS $$
BEGIN
 IF NEW.platform_context_id IS DISTINCT FROM OLD.platform_context_id
   OR NEW.platform_authority_epoch IS DISTINCT FROM OLD.platform_authority_epoch THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-CONTEXT';
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS authority_envelope_platform_immutable ON control.authority_envelope;
CREATE TRIGGER authority_envelope_platform_immutable BEFORE UPDATE ON control.authority_envelope
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_envelope_platform_binding();

DROP POLICY IF EXISTS envelope_platform_custody_read ON control.authority_envelope;
CREATE POLICY envelope_platform_custody_read ON control.authority_envelope FOR SELECT TO openpc_control_owner
 USING(openpc.matches_participant(participant_id));
DROP POLICY IF EXISTS platform_context_custody_lock ON control.platform_context;
CREATE POLICY platform_context_custody_lock ON control.platform_context FOR UPDATE TO openpc_control_owner
 USING(exists(select 1 from control.authority_envelope envelope
   where envelope.platform_context_id=platform_context.platform_context_id
     and openpc.matches_participant(envelope.participant_id))) WITH CHECK(false);

-- This returns custody, not permission. Callers must first verify and retain
-- their selected current envelope/grant path under the Participant fence.
CREATE OR REPLACE FUNCTION openpc.lock_authority_envelope_platform_context(p_envelope_id uuid)
RETURNS TABLE(platform_context_id uuid,platform_authority_epoch text,delegation_epoch text)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,control AS $$
BEGIN
 PERFORM openpc.assert_request_context(false);
 RETURN QUERY SELECT platform.platform_context_id,platform.authority_epoch::text,envelope.delegation_epoch::text
 FROM control.authority_envelope envelope JOIN control.platform_context platform
   ON platform.platform_context_id=envelope.platform_context_id
 WHERE envelope.participant_id=openpc.current_participant_id()
   AND envelope.authority_envelope_id=p_envelope_id AND envelope.state='ACTIVE'
   AND envelope.valid_from<=clock_timestamp() AND (envelope.valid_until IS NULL OR envelope.valid_until>clock_timestamp())
   AND platform.state='ACTIVE' AND platform.authority_epoch=envelope.platform_authority_epoch
 FOR SHARE OF platform;
END $$;


CREATE OR REPLACE FUNCTION openpc.identity_envelope_scope_valid(p_bytes bytea)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE scope jsonb; module jsonb; items jsonb; item jsonb; previous bytea; current_bytes bytea;
 dimension integer; module_id integer; value text;
BEGIN
 scope:=openpc.business_cbor(p_bytes);
 IF jsonb_typeof(scope) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(scope) key) IS DISTINCT FROM ARRAY['1','2','3','4','5','6','7'] THEN RETURN false; END IF;
 FOR dimension IN 3..7 LOOP
  IF jsonb_typeof(scope->dimension::text)<>'number' OR (scope->>dimension::text)!~'^(0|[1-9][0-9]{0,19})$' THEN RETURN false; END IF;
 END LOOP;
 IF (scope->>'3')::numeric>18446744073709551615 OR (scope->>'4')::numeric>18446744073709551615
   OR (scope->>'4')::numeric<=(scope->>'3')::numeric OR mod((scope->>'3')::numeric,1000)<>0
   OR mod((scope->>'4')::numeric,1000)<>0 OR (scope->>'5')::numeric NOT IN(0,1)
   OR (scope->>'6')::numeric NOT IN(0,1) OR (scope->>'7')::numeric>32 THEN RETURN false; END IF;
 FOR module_id IN 1..2 LOOP
  module:=scope->module_id::text;
  IF jsonb_typeof(module) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(module) key) IS DISTINCT FROM ARRAY['1','2','3','4','5','6','7'] THEN RETURN false; END IF;
  FOR dimension IN 1..7 LOOP
   items:=module->dimension::text; previous:=NULL;
   IF jsonb_typeof(items)<>'array' OR jsonb_array_length(items)>256 THEN RETURN false; END IF;
   FOR item IN SELECT v FROM jsonb_array_elements(items) v LOOP
    IF dimension IN(1,2) THEN
     IF jsonb_typeof(item)<>'object' OR jsonb_typeof(item->'bytes') IS DISTINCT FROM 'string' OR item<>jsonb_build_object('bytes',item->>'bytes')
       OR (item->>'bytes')!~'^[0-9a-f]{12}[1-8][0-9a-f]{3}[89ab][0-9a-f]{15}$' THEN RETURN false; END IF;
     current_bytes:=decode(item->>'bytes','hex');
    ELSE
     IF jsonb_typeof(item)<>'string' THEN RETURN false; END IF;
     value:=item#>>'{}'; current_bytes:=convert_to(value,'UTF8');
     IF octet_length(current_bytes) NOT BETWEEN 1 AND 160 OR value!~'^[A-Za-z0-9][A-Za-z0-9:._/-]*$' THEN RETURN false; END IF;
     IF dimension=6 AND value NOT IN('BREAK_GLASS','HIGH','LOW','STANDARD') THEN RETURN false; END IF;
     IF dimension=7 AND module_id=1 AND value!~'^ACT-[A-Z][A-Z0-9_]*-V[1-9][0-9]*$' THEN RETURN false; END IF;
     IF dimension=7 AND module_id=2 AND value NOT IN('CALL_RESULT_DISCLOSURE','GAS_ESTIMATE_DISCLOSURE','ACCESS_LIST_DISCLOSURE',
       'UNSIGNED_TRANSACTION_PREPARATION','SIGNED_TRANSACTION_SUBMISSION','OPERATION_STATUS_DISCLOSURE','MULTI_CALL_SIMULATION_DISCLOSURE') THEN RETURN false; END IF;
    END IF;
    IF previous IS NOT NULL AND current_bytes<=previous THEN RETURN false; END IF;
    previous:=current_bytes;
   END LOOP;
  END LOOP;
 END LOOP;
 RETURN true;
END $$;

CREATE OR REPLACE FUNCTION openpc.guard_platform_envelope_scope()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE expected jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PC-AUTH-0005-IMMUTABLE-PLATFORM-SCOPE'; END IF;
 IF current_user<>'openpc_control_owner' OR NOT pg_has_role(session_user,'openpc_control_owner','MEMBER')
   OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolcanlogin AND NOT rolsuper AND NOT rolbypassrls)
   OR NEW.installed_by<>session_user THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INSTALLATION-AUTHORITY'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT openpc.matches_participant(NEW.owner_participant_id) OR NOT openpc.matches_privacy(NEW.installation_privacy_domain_id)
   OR NEW.platform_authority_epoch<>1 OR NEW.admission_version<>1 OR NOT openpc.identity_envelope_scope_valid(NEW.scope_cbor)
   THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-BINDING'; END IF;
 -- Configuration's installation owner creates this source before this adapter;
 -- the Identity migration may be installed before that cross-lane table exists.
 PERFORM 1 FROM control.participant WHERE participant_id=NEW.owner_participant_id AND state='ACTIVE' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INSTALLATION-PARTICIPANT'; END IF;
 PERFORM 1 FROM control.privacy_domain WHERE participant_id=NEW.owner_participant_id
  AND privacy_domain_id=NEW.installation_privacy_domain_id AND state='ACTIVE' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INSTALLATION-PRIVACY'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('operations-generation:'||NEW.environment_id,0))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INSTALLATION-BUSY'; END IF;
 PERFORM 1 FROM control.operations_installation i
  WHERE i.participant_id=NEW.owner_participant_id AND i.privacy_domain_id=NEW.installation_privacy_domain_id
    AND i.environment_id=NEW.environment_id AND i.state='ACTIVE' AND i.installation_digest=NEW.installation_digest
    AND openpc.operations_source_authentication_valid(i.installation)
    AND NOT EXISTS(SELECT 1 FROM control.operations_generation_commit c WHERE c.environment_id=i.environment_id)
  FOR SHARE OF i;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INSTALLATION-PROVENANCE'; END IF;
 PERFORM 1 FROM control.platform_context p WHERE p.platform_context_id=NEW.platform_context_id
   AND p.owner_participant_id=NEW.owner_participant_id AND p.authority_epoch=NEW.platform_authority_epoch AND p.state='ACTIVE'
   AND p.row_version=1 AND p.xmin=(mod(pg_current_xact_id()::text::numeric,4294967296))::text::xid FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-INITIAL-ROOT'; END IF;
 expected:=jsonb_build_array('pc.identity.platform-envelope-scope.v1',24034,1,
  openpc.business_bytes(decode('6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5','hex')),
  openpc.business_uuid(NEW.platform_context_id),openpc.business_uuid(NEW.owner_participant_id),
  openpc.business_uuid(NEW.installation_privacy_domain_id),NEW.platform_authority_epoch,NEW.environment_id,
  openpc.business_bytes(decode(substring(NEW.installation_digest FROM 8),'hex')),openpc.business_bytes(NEW.scope_cbor));
 IF openpc.business_cbor(NEW.admission_preimage) IS DISTINCT FROM expected OR NEW.admission_digest<>sha256(NEW.admission_preimage)
   THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-DIGEST'; END IF;
 NEW.installed_at:=clock_timestamp();
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS platform_envelope_scope_guard ON control.platform_envelope_scope;
CREATE TRIGGER platform_envelope_scope_guard BEFORE INSERT OR UPDATE OR DELETE ON control.platform_envelope_scope
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_platform_envelope_scope();


CREATE OR REPLACE FUNCTION openpc.platform_scope_document_value(scope jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE dimensions jsonb; slice jsonb; slices jsonb:='{}'; dimension_values jsonb;
 module_id integer; dimension integer; label text; key text;
BEGIN
 FOR module_id IN 1..2 LOOP
  dimensions:=scope->module_id::text; slice:='{}';
  FOR dimension IN 1..7 LOOP
   key:=(ARRAY['participantIds','privacyDomainIds','resourceIds','dataClasses','targetProfileIds','riskClasses',
    CASE WHEN module_id=1 THEN 'actionIntentIds' ELSE 'capabilityIds' END])[dimension];
   IF dimension IN(1,2) THEN
    SELECT coalesce(jsonb_agg(to_jsonb((substr(v->>'bytes',1,8)||'-'||substr(v->>'bytes',9,4)||'-'||
      substr(v->>'bytes',13,4)||'-'||substr(v->>'bytes',17,4)||'-'||substr(v->>'bytes',21,12))::uuid::text)
      ORDER BY ordinal),'[]'::jsonb) INTO dimension_values
     FROM jsonb_array_elements(dimensions->dimension::text) WITH ORDINALITY a(v,ordinal);
   ELSE dimension_values:=dimensions->dimension::text; END IF;
   slice:=slice||jsonb_build_object(key,dimension_values);
  END LOOP;
  label:=CASE WHEN module_id=1 THEN 'administration' ELSE 'runtime' END;
  slices:=slices||jsonb_build_object(label,slice);
 END LOOP;
 RETURN slices||jsonb_build_object('validFromNs',scope->>'3','validUntilNs',scope->>'4',
  'makerCheckerRequired',(scope->>'5')='1','stepUpRequired',(scope->>'6')='1','onwardDelegationDepth',(scope->>'7')::integer);
END $$;
REVOKE ALL ON FUNCTION openpc.platform_scope_document_value(jsonb) FROM PUBLIC;
CREATE OR REPLACE FUNCTION openpc.platform_scope_document(p_bytes bytea)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
BEGIN
 IF NOT openpc.identity_envelope_scope_valid(p_bytes) THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE'; END IF;
 RETURN openpc.platform_scope_document_value(openpc.business_cbor(p_bytes));
END $$;
REVOKE ALL ON FUNCTION openpc.platform_scope_document(bytea) FROM PUBLIC;

-- Complete conservative cohort within the installed finite runtime scope. An
-- unresolved original effect or in-flight activation blocks preparation.
CREATE OR REPLACE FUNCTION openpc.read_platform_scope_affected_targets(root_id uuid)
RETURNS TABLE(target jsonb) LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
DECLARE pid uuid; privacy uuid; root control.platform_context; missing integer;
BEGIN
 PERFORM openpc.assert_request_context(true);
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 IF root_id IS NULL OR openpc.current_action_intent_id() NOT IN('ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 SELECT * INTO STRICT root FROM control.platform_context p
  WHERE p.platform_context_id=root_id AND p.owner_participant_id=pid AND p.state='ACTIVE' FOR SHARE;
 PERFORM 1 FROM control.platform_envelope_scope s WHERE s.platform_context_id=root_id
  AND s.owner_participant_id=pid AND s.installation_privacy_domain_id=privacy;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 IF EXISTS(SELECT 1 FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
   AND w.work_kind='RUNTIME_ACTIVATION' AND w.state IN('PENDING','LEASED','RECONCILING'))
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-WORK-PENDING'; END IF;
 SELECT count(*) INTO missing FROM control.runtime_target t
  WHERE t.participant_id=pid AND t.privacy_domain_id=privacy AND t.active_generation_digest IS NOT NULL
   AND NOT EXISTS(SELECT 1 FROM control.runtime_activation_observation o JOIN control.configuration_work w
    ON w.participant_id=o.participant_id AND w.privacy_domain_id=o.privacy_domain_id
      AND w.configuration_work_id=o.configuration_work_id AND w.execution_attempt_id=o.execution_attempt_id
      AND w.operation_id=o.operation_id AND w.runtime_target_id=o.runtime_target_id
      AND w.runtime_configuration_generation_id=o.runtime_configuration_generation_id
      AND w.generation_digest=o.generation_digest AND w.xds_version_digest=o.xds_version_digest
      AND w.state='COMPLETED' AND w.result_receipt_digest=o.activation_receipt_digest
    WHERE o.participant_id=pid AND o.privacy_domain_id=privacy AND o.runtime_target_id=t.runtime_target_id
      AND o.capsule_digest=t.active_generation_digest);
 IF missing<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-ORIGINAL-AMBIGUITY'; END IF;
 RETURN QUERY SELECT jsonb_build_object('participantId',pid::text,'privacyDomainId',privacy::text,
    'targetId',t.runtime_target_id::text,'expectedRevision',t.revision::text,
    'capsuleDigest',o.capsule_digest,'originalWorkId',o.configuration_work_id::text,
    'originalAttemptId',o.execution_attempt_id::text,'activationReceiptDigest',o.activation_receipt_digest)
  FROM control.runtime_target t JOIN control.runtime_activation_observation o
    ON o.participant_id=t.participant_id AND o.privacy_domain_id=t.privacy_domain_id
      AND o.runtime_target_id=t.runtime_target_id AND o.capsule_digest=t.active_generation_digest
  WHERE t.participant_id=pid AND t.privacy_domain_id=privacy AND t.active_generation_digest IS NOT NULL
  ORDER BY t.runtime_target_id;
END $$;
REVOKE ALL ON FUNCTION openpc.read_platform_scope_affected_targets(uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.guard_platform_scope_replacement()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE root control.platform_context; initial control.platform_envelope_scope; base jsonb; expected jsonb; predecessor bytea; predecessor_scope bytea; current_scope jsonb; next_scope jsonb; dimension integer; readiness jsonb;
BEGIN
 IF TG_OP='DELETE' OR current_user<>'openpc_control_owner' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-OWNER'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
  OR openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO STRICT root FROM control.platform_context p WHERE p.platform_context_id=NEW.platform_context_id FOR UPDATE;
  SELECT * INTO STRICT initial FROM control.platform_envelope_scope s WHERE s.platform_context_id=root.platform_context_id;
  SELECT s.admission_digest,s.scope_cbor INTO STRICT predecessor,predecessor_scope FROM (
    SELECT platform_context_id,platform_authority_epoch,admission_digest,scope_cbor FROM control.platform_envelope_scope
    UNION ALL
    SELECT s.platform_context_id,s.platform_authority_epoch,s.admission_digest,s.scope_cbor
      FROM control.platform_envelope_scope_successor s JOIN control.platform_scope_replacement r
        ON r.replacement_id=s.replacement_id AND r.state='COMMITTED'
   ) s WHERE s.platform_context_id=root.platform_context_id AND s.platform_authority_epoch=root.authority_epoch;
  IF coalesce((root.owner_participant_id<>NEW.participant_id OR initial.installation_privacy_domain_id<>NEW.privacy_domain_id
    OR root.state<>'ACTIVE' OR root.authority_epoch<>NEW.predecessor_epoch OR root.row_version<>NEW.expected_root_revision
    OR NEW.state<>'WITHDRAWING' OR NEW.row_version<>1 OR NEW.prepare_operation_id<>openpc.current_operation_id()
    OR NEW.candidate->>'replacementId'<>NEW.replacement_id::text
    OR NEW.candidate->>'platformContextId'<>NEW.platform_context_id::text
    OR NEW.candidate->>'predecessorEpoch'<>NEW.predecessor_epoch::text
    OR NEW.candidate->>'expectedRootRevision'<>NEW.expected_root_revision::text
    OR NEW.candidate->>'predecessorDigest'<>'sha256:'||encode(NEW.predecessor_digest,'hex')
    OR NEW.candidate->'successorScope' IS DISTINCT FROM openpc.platform_scope_document(NEW.successor_scope_cbor)
    OR NEW.predecessor_digest IS DISTINCT FROM predecessor),true)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PREDECESSOR'; END IF;
  current_scope:=openpc.business_cbor(predecessor_scope); next_scope:=openpc.business_cbor(NEW.successor_scope_cbor);
  IF NOT coalesce(openpc.identity_envelope_scope_valid(NEW.successor_scope_cbor),false)
    OR coalesce(((next_scope->>'3')::numeric<(current_scope->>'3')::numeric
      OR (next_scope->>'4')::numeric>(current_scope->>'4')::numeric
      OR (next_scope->>'3')::numeric>extract(epoch from clock_timestamp())*1000000000
      OR (next_scope->>'4')::numeric<=extract(epoch from clock_timestamp())*1000000000
      OR next_scope->>'7'<>'0' OR next_scope=current_scope),true)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-BOUNDS'; END IF;
  FOR dimension IN 1..7 LOOP
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(next_scope->'2'->dimension::text) value
      WHERE NOT (current_scope->'2'->dimension::text @> jsonb_build_array(value)))
   THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RUNTIME-WIDENING'; END IF;
  END LOOP;
  IF (SELECT coalesce(jsonb_agg(entry ORDER BY entry->>'targetId'),'[]') FROM jsonb_array_elements(NEW.candidate->'affectedTargets') entry)
    IS DISTINCT FROM (SELECT coalesce(jsonb_agg(target ORDER BY target->>'targetId'),'[]')
      FROM openpc.read_platform_scope_affected_targets(NEW.platform_context_id))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-COHORT'; END IF;
  base:=jsonb_build_array('pc.identity.platform-envelope-scope.v1',24034,1,
    openpc.business_bytes(decode('6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5','hex')),
    openpc.business_uuid(root.platform_context_id),openpc.business_uuid(root.owner_participant_id),
    openpc.business_uuid(initial.installation_privacy_domain_id),NEW.predecessor_epoch+1,initial.environment_id,
    openpc.business_bytes(decode(substring(initial.installation_digest FROM 8),'hex')),
    openpc.business_bytes(NEW.successor_scope_cbor));
  expected:=openpc.business_cbor(NEW.successor_preimage);
  IF jsonb_typeof(expected) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PREIMAGE';
  END IF;
  IF coalesce((jsonb_array_length(expected)<>7
    OR expected->>0<>'pc.identity.platform-envelope-scope.successor.v1' OR expected->>1<>'1'
    OR expected->2 IS DISTINCT FROM openpc.business_uuid(NEW.replacement_id)
    OR expected->3 IS DISTINCT FROM openpc.business_uuid(NEW.prepare_operation_id)
    OR expected->>4<>NEW.predecessor_epoch::text
    OR expected->5 IS DISTINCT FROM openpc.business_bytes(NEW.predecessor_digest)
    OR openpc.business_cbor(decode(expected#>>'{6,bytes}','hex')) IS DISTINCT FROM base),true)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PREIMAGE'; END IF;
 ELSIF NEW.state='SUPERSEDED' THEN
  -- Candidate visibility is bound to an inserted replacement by RLS. Validate
  -- its complete consumed provenance at the deferred boundary below, after
  -- both rows exist, without granting pre-insert candidate visibility.
  IF OLD.state<>'WITHDRAWING' OR OLD.row_version<>1 OR NEW.row_version<>2
    OR NEW.superseded_by IS NULL OR NEW.superseded_by=OLD.replacement_id
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(OLD.candidate->'administrators') a
      WHERE greatest((a#>>'{usable,validUntilNs}')::numeric,(a#>>'{grantable,validUntilNs}')::numeric)
        >extract(epoch from clock_timestamp())*1000000000)
    OR (to_jsonb(NEW)-'state'-'row_version'-'superseded_by') IS DISTINCT FROM
       (to_jsonb(OLD)-'state'-'row_version'-'superseded_by')
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-SUPERSESSION'; END IF;
 ELSE
  readiness:=openpc.read_platform_scope_replacement_readiness(OLD.replacement_id);
  IF readiness->>'unacknowledgedTargets'<>'0' OR readiness->>'unpreparedAdministrators'<>'0'
    OR NEW.readiness_digest IS DISTINCT FROM decode(substring(readiness->>'readinessDigest' from 8),'hex')
    OR (readiness->>'sourceExpiresAtNs')::numeric<=(readiness->>'nowNs')::numeric
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-READINESS'; END IF;
  IF coalesce((OLD.state<>'WITHDRAWING' OR NEW.state<>'COMMITTED' OR NEW.row_version<>OLD.row_version+1
    OR NEW.commit_operation_id<>openpc.current_operation_id()
    OR (to_jsonb(NEW)-'state'-'row_version'-'commit_operation_id'-'commit_candidate_id'-'commit_approval_id'-'readiness_digest'-'committed_at')
      IS DISTINCT FROM (to_jsonb(OLD)-'state'-'row_version'-'commit_operation_id'-'commit_candidate_id'-'commit_approval_id'-'readiness_digest'-'committed_at')),true)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-HISTORY'; END IF;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION openpc.guard_platform_scope_replacement() FROM PUBLIC;
DROP TRIGGER IF EXISTS platform_scope_replacement_guard ON control.platform_scope_replacement;
CREATE TRIGGER platform_scope_replacement_guard BEFORE INSERT OR UPDATE OR DELETE ON control.platform_scope_replacement
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_platform_scope_replacement();

CREATE OR REPLACE FUNCTION openpc.require_platform_scope_replacement_provenance()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE r control.platform_scope_replacement; phase text; operation uuid; candidate uuid; approval uuid; valid boolean;
BEGIN
 SELECT * INTO STRICT r FROM control.platform_scope_replacement WHERE replacement_id=NEW.replacement_id;
 IF TG_OP='UPDATE' AND NEW.state='SUPERSEDED' THEN
  -- Deferred: both rows and the successor's ordinary PREPARE provenance must
  -- commit together. The old intent, approvals and target evidence stay intact.
  IF NOT EXISTS(SELECT 1 FROM control.platform_scope_replacement successor
    WHERE successor.replacement_id=r.superseded_by AND successor.participant_id=r.participant_id
      AND successor.privacy_domain_id=r.privacy_domain_id AND successor.platform_context_id=r.platform_context_id
      AND successor.predecessor_epoch=r.predecessor_epoch AND successor.expected_root_revision=r.expected_root_revision
      AND successor.predecessor_digest=r.predecessor_digest
      AND successor.prepare_operation_id=openpc.current_operation_id()
      AND successor.candidate->'supersedes'=jsonb_build_object('replacementId',r.replacement_id::text,
        'expectedRevision','1','successorDigest','sha256:'||encode(r.successor_digest,'hex')))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-SUPERSESSION-PROVENANCE'; END IF;
  RETURN NULL;
 END IF;
 phase:=CASE WHEN TG_OP='INSERT' THEN 'PREPARE' ELSE 'COMMIT' END;
 operation:=CASE WHEN phase='PREPARE' THEN r.prepare_operation_id ELSE r.commit_operation_id END;
 candidate:=CASE WHEN phase='PREPARE' THEN r.prepare_candidate_id ELSE r.commit_candidate_id END;
 approval:=CASE WHEN phase='PREPARE' THEN r.prepare_approval_id ELSE r.commit_approval_id END;
 SELECT EXISTS(SELECT 1 FROM control.mutation_candidate c
  JOIN control.approval_request a ON a.participant_id=c.participant_id AND a.privacy_domain_id=c.privacy_domain_id
    AND a.approval_request_id=approval AND a.subject_type='CONFIGURATION_CANDIDATE'
    AND a.subject_id=c.mutation_candidate_id AND a.subject_digest=c.candidate_digest
    AND a.subject_version=c.expected_revision AND a.state='APPROVED'
  JOIN control.mutation_evidence e ON e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id
    AND e.operation_id=operation AND e.catalog_operation_id=c.catalog_operation_id
    AND e.aggregate_type='platform-scope-replacement' AND e.aggregate_id=r.replacement_id
    AND e.candidate_digest=c.candidate_digest AND e.approval_request_id=approval
    AND e.principal_id=c.maker_principal_id AND e.checker_principal_id<>e.principal_id
    AND e.mfa_challenge_id IS NOT NULL AND e.webauthn_assertion_binding_digest IS NOT NULL
  JOIN control.idempotency_record receipt ON receipt.participant_id=c.participant_id AND receipt.privacy_domain_id=c.privacy_domain_id
    AND receipt.operation_id=operation AND receipt.terminal_state='COMMITTED'
    AND receipt.result_payload->>'replacementId'=r.replacement_id::text
    AND receipt.result_payload->>'successorDigest'='sha256:'||encode(r.successor_digest,'hex')
  WHERE c.participant_id=r.participant_id AND c.privacy_domain_id=r.privacy_domain_id
    AND c.mutation_candidate_id=candidate AND c.consumed_operation_id=operation AND c.state='CONSUMED'
    AND c.catalog_operation_id='ID-OP-PLATFORM-SCOPE-'||phase AND c.action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
    AND c.resource_id=r.replacement_id AND c.expected_revision=CASE WHEN phase='PREPARE' THEN 0 ELSE 1 END
    AND ((phase='PREPARE' AND c.candidate_document=r.candidate AND c.candidate_digest=r.candidate_digest)
      OR (phase='COMMIT' AND c.candidate_document->>'readinessDigest'='sha256:'||encode(r.readiness_digest,'hex')
        AND c.candidate_document->>'successorDigest'='sha256:'||encode(r.successor_digest,'hex')
        AND c.candidate_document->>'predecessorEpoch'=r.predecessor_epoch::text
        AND c.candidate_document->>'expectedRootRevision'=r.expected_root_revision::text))) INTO valid;
 IF NOT coalesce(valid,false) THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PROVENANCE'; END IF;
 IF phase='PREPARE' AND (
  (SELECT count(*) FROM control.platform_scope_target_withdrawal q WHERE q.replacement_id=r.replacement_id
    AND q.participant_id=r.participant_id AND q.privacy_domain_id=r.privacy_domain_id)<>jsonb_array_length(r.candidate->'affectedTargets')
  OR EXISTS(SELECT 1 FROM control.platform_scope_target_withdrawal q WHERE q.replacement_id=r.replacement_id
    AND NOT (r.candidate->'affectedTargets' @> jsonb_build_array(q.source))))
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-COHORT'; END IF;
 IF phase='COMMIT' AND NOT EXISTS(SELECT 1 FROM control.platform_context p
    JOIN control.platform_envelope_scope_successor s ON s.platform_context_id=p.platform_context_id
      AND s.platform_authority_epoch=p.authority_epoch AND s.replacement_id=r.replacement_id
    WHERE p.platform_context_id=r.platform_context_id AND p.owner_participant_id=r.participant_id AND p.state='ACTIVE'
      AND p.authority_epoch=r.predecessor_epoch+1 AND p.row_version=r.expected_root_revision+1)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-EFFECT'; END IF;
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION openpc.require_platform_scope_replacement_provenance() FROM PUBLIC;
DROP TRIGGER IF EXISTS platform_scope_replacement_provenance ON control.platform_scope_replacement;
CREATE CONSTRAINT TRIGGER platform_scope_replacement_provenance AFTER INSERT OR UPDATE ON control.platform_scope_replacement
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_platform_scope_replacement_provenance();

CREATE OR REPLACE FUNCTION openpc.guard_platform_scope_successor()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
BEGIN
 IF TG_OP<>'INSERT' OR current_user<>'openpc_control_owner'
  OR NOT EXISTS(SELECT 1 FROM control.platform_scope_replacement r
    JOIN control.platform_envelope_scope initial ON initial.platform_context_id=r.platform_context_id
    WHERE r.replacement_id=NEW.replacement_id AND r.state='COMMITTED' AND r.row_version=2
      AND r.commit_operation_id=openpc.current_operation_id()
      AND r.platform_context_id=NEW.platform_context_id AND NEW.platform_authority_epoch=r.predecessor_epoch+1
      AND NEW.preparation_operation_id=r.prepare_operation_id AND NEW.predecessor_epoch=r.predecessor_epoch
      AND NEW.predecessor_digest=r.predecessor_digest
      AND r.participant_id=NEW.owner_participant_id AND r.privacy_domain_id=NEW.installation_privacy_domain_id
      AND NEW.scope_cbor=r.successor_scope_cbor AND NEW.admission_preimage=r.successor_preimage
      AND NEW.admission_digest=r.successor_digest AND NEW.environment_id=initial.environment_id
      AND NEW.installation_digest=initial.installation_digest)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-IMMUTABLE-PLATFORM-SUCCESSOR'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION openpc.guard_platform_scope_successor() FROM PUBLIC;
DROP TRIGGER IF EXISTS platform_scope_successor_guard ON control.platform_envelope_scope_successor;
CREATE TRIGGER platform_scope_successor_guard BEFORE INSERT OR UPDATE OR DELETE ON control.platform_envelope_scope_successor
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_platform_scope_successor();

CREATE OR REPLACE FUNCTION openpc.prepare_platform_scope_replacement(document jsonb,scope bytea,preimage bytea,candidate_id uuid,approval_id uuid)
RETURNS TABLE(replacement jsonb) LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
DECLARE inserted control.platform_scope_replacement; pending control.platform_scope_replacement; target_source jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('platform-scope-replacement:'||(document->>'platformContextId'),0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM 1 FROM control.runtime_target t WHERE t.participant_id=openpc.current_participant_id()
   AND t.privacy_domain_id=openpc.current_privacy_domain_id() ORDER BY t.runtime_target_id FOR SHARE;
 -- Serialize the old/new pending boundary with commits, before changing either.
 PERFORM 1 FROM control.platform_context WHERE platform_context_id=(document->>'platformContextId')::uuid
  AND owner_participant_id=openpc.current_participant_id() FOR UPDATE;
 SELECT * INTO pending FROM control.platform_scope_replacement r
  WHERE r.platform_context_id=(document->>'platformContextId')::uuid AND r.state='WITHDRAWING' FOR UPDATE;
 IF pending.replacement_id IS NULL THEN
  IF document ? 'supersedes' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-SUPERSESSION'; END IF;
 ELSE
  IF document->'supersedes' IS DISTINCT FROM jsonb_build_object('replacementId',pending.replacement_id::text,
      'expectedRevision',pending.row_version::text,'successorDigest','sha256:'||encode(pending.successor_digest,'hex'))
    OR pending.participant_id<>openpc.current_participant_id() OR pending.privacy_domain_id<>openpc.current_privacy_domain_id()
    OR pending.predecessor_epoch::text IS DISTINCT FROM document->>'predecessorEpoch'
    OR pending.expected_root_revision::text IS DISTINCT FROM document->>'expectedRootRevision'
    OR 'sha256:'||encode(pending.predecessor_digest,'hex') IS DISTINCT FROM document->>'predecessorDigest'
    OR pending.replacement_id=(document->>'replacementId')::uuid
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-SUPERSESSION'; END IF;
  UPDATE control.platform_scope_replacement SET state='SUPERSEDED',row_version=2,
    superseded_by=(document->>'replacementId')::uuid WHERE replacement_id=pending.replacement_id;
 END IF;
 INSERT INTO control.platform_scope_replacement(replacement_id,platform_context_id,participant_id,privacy_domain_id,
  predecessor_epoch,expected_root_revision,predecessor_digest,candidate,candidate_digest,
  successor_scope_cbor,successor_preimage,successor_digest,prepare_operation_id,prepare_candidate_id,prepare_approval_id)
 VALUES((document->>'replacementId')::uuid,(document->>'platformContextId')::uuid,openpc.current_participant_id(),openpc.current_privacy_domain_id(),
  (document->>'predecessorEpoch')::numeric,(document->>'expectedRootRevision')::numeric,
  decode(substring(document->>'predecessorDigest' from 8),'hex'),document,
  sha256(convert_to(openpc.signing_canonical_json(document),'UTF8')),scope,preimage,sha256(preimage),openpc.current_operation_id(),candidate_id,approval_id)
 RETURNING * INTO STRICT inserted;
 FOR target_source IN SELECT v FROM jsonb_array_elements(document->'affectedTargets') v LOOP
  INSERT INTO control.platform_scope_target_withdrawal(replacement_id,participant_id,privacy_domain_id,runtime_target_id,source)
  VALUES(inserted.replacement_id,inserted.participant_id,inserted.privacy_domain_id,(target_source->>'targetId')::uuid,target_source);
 END LOOP;
 RETURN QUERY SELECT jsonb_build_object('replacementId',inserted.replacement_id::text,'successorDigest','sha256:'||encode(inserted.successor_digest,'hex'),
   'state',inserted.state,'revision',inserted.row_version::text,'operationId',inserted.prepare_operation_id::text);
END $$;
REVOKE ALL ON FUNCTION openpc.prepare_platform_scope_replacement(jsonb,bytea,bytea,uuid,uuid) FROM PUBLIC;


CREATE OR REPLACE FUNCTION openpc.read_platform_scope_replacement_readiness(wanted uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE r control.platform_scope_replacement; root control.platform_context; targets jsonb; admins jsonb; bindings jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 PERFORM openpc.assert_runtime_target_disposition_owner();
 IF openpc.current_action_intent_id() NOT IN('ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 SELECT * INTO STRICT r FROM control.platform_scope_replacement WHERE replacement_id=wanted
  AND participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id();
 SELECT * INTO STRICT root FROM control.platform_context p WHERE p.platform_context_id=r.platform_context_id
  AND p.owner_participant_id=r.participant_id AND p.state='ACTIVE';
 IF r.state<>'WITHDRAWING' OR r.row_version<>1 OR root.authority_epoch<>r.predecessor_epoch
  OR root.row_version<>r.expected_root_revision THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PREDECESSOR'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('targetId',q.runtime_target_id::text,'source',q.source,
  'revision',head.revision::text,'deliveryDigest',d.delivery_digest,'acknowledgementDigest',a.acknowledgement_digest,
  'journalSequence',a.claims->>'journal_sequence','ready',coalesce(
    head.binding->>'action'='Withdraw' AND head.binding->'cause'=jsonb_build_object('kind','Dependency','owner','Platform',
      'resource_id',r.replacement_id::text,'operation_id',r.prepare_operation_id::text,'revision',1)
    AND 'sha256:'||(head.binding#>>'{source,capsule_digest}')=q.source->>'capsuleDigest'
    AND head.binding#>>'{source,original_work_id}'=q.source->>'originalWorkId'
    AND head.binding#>>'{source,original_execution_attempt_id}'=q.source->>'originalAttemptId'
    AND d.claims=head.binding||jsonb_build_object('committed_admission_digest',substring(head.admission_digest from 8))
    AND a.claims->>'installed_state'='NewUseDenied' AND a.claims->'target'=head.binding->'target'
    AND a.claims->>'delivery_digest'=substring(d.delivery_digest from 8)
    AND EXISTS(SELECT 1 FROM control.credential credential JOIN control.principal principal
      ON principal.participant_id=credential.participant_id AND principal.principal_id=credential.principal_id
      WHERE credential.participant_id=q.participant_id AND credential.credential_id=(head.binding#>>'{target,credential_id}')::uuid
        AND credential.kind='WORKLOAD_MTLS' AND credential.state='ACTIVE' AND principal.state='ACTIVE'
        AND credential.principal_id=(head.binding#>>'{target,principal_id}')::uuid
        AND credential.credential_epoch::text=head.binding#>>'{target,credential_epoch}'
        AND principal.authority_epoch::text=head.binding#>>'{target,principal_epoch}'
        AND credential.valid_from<=clock_timestamp() AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp()))
    AND (a.claims->>'disposition_revision')::bigint=head.revision
    AND d.delivery_digest='sha256:'||encode(sha256(d.signed_delivery),'hex')
    AND a.acknowledgement_digest='sha256:'||encode(sha256(a.signed_acknowledgement),'hex'),false))
    ORDER BY q.runtime_target_id),'[]') INTO targets
 FROM control.platform_scope_target_withdrawal q
 LEFT JOIN LATERAL(SELECT h.* FROM control.runtime_target_disposition_admission h WHERE h.participant_id=q.participant_id
  AND h.privacy_domain_id=q.privacy_domain_id AND h.runtime_target_id=q.runtime_target_id ORDER BY h.revision DESC LIMIT 1) head ON true
 LEFT JOIN control.runtime_target_disposition_delivery d ON d.participant_id=q.participant_id AND d.privacy_domain_id=q.privacy_domain_id
  AND d.runtime_target_id=q.runtime_target_id AND d.revision=head.revision
 LEFT JOIN control.runtime_target_disposition_acknowledgement a ON a.participant_id=q.participant_id AND a.privacy_domain_id=q.privacy_domain_id
  AND a.runtime_target_id=q.runtime_target_id AND a.delivery_digest=d.delivery_digest
 WHERE q.participant_id=r.participant_id AND q.privacy_domain_id=r.privacy_domain_id AND q.replacement_id=r.replacement_id;
 IF jsonb_array_length(targets)<>jsonb_array_length(r.candidate->'affectedTargets')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-COHORT'; END IF;
 SELECT jsonb_agg(jsonb_build_object('principalId',plan->>'principalId','envelopeId',plan->>'envelopeId',
  'assignmentId',plan->>'assignmentId','envelopeDigest','sha256:'||encode(e.semantic_digest,'hex'),
  'signatureDigest','sha256:'||encode(sha256(e.cose_sign1),'hex'),'assignmentRevision',a.row_version::text,
  'roleRevision',role.row_version::text,'ready',coalesce(
    e.state='ACTIVE' AND e.representation='TYPED_V1' AND e.platform_context_id=r.platform_context_id
    AND e.platform_authority_epoch=r.predecessor_epoch+1 AND e.maker_checker_required AND e.step_up_required
    AND e.onward_delegation_depth=0 AND cardinality(e.runtime_capability_ids)=0
    AND e.valid_from<=clock_timestamp() AND e.valid_until>clock_timestamp() AND octet_length(e.cose_sign1)>0
    AND p.state='APPROVED' AND p.row_version=3 AND p.proposal_cbor=e.semantic_cbor
    AND create_intent.state='CONSUMED' AND create_intent.candidate_document->>'platformScopeReplacementId'=r.replacement_id::text
    AND create_intent.candidate_document->'usable'=plan->'usable' AND create_intent.candidate_document->'grantable'=plan->'grantable'
    AND openpc.platform_scope_document_value(openpc.business_cbor(p.proposal_cbor)->'8')=plan->'usable'
    AND openpc.platform_scope_document_value(openpc.business_cbor(p.proposal_cbor)->'9')=plan->'grantable'
    AND activation.state='COMMITTED' AND activation.row_version=4 AND activation.cose_sign1=e.cose_sign1
    AND principal.state='ACTIVE' AND principal.kind IN('USER','PLATFORM_OPERATOR')
    AND role.state='ACTIVE' AND role.row_version::text=plan->>'expectedRoleRevision'
    AND plan->>'roleDigest'='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
      'domain','pc.identity.envelope-role-binding.v1','participantId',r.participant_id::text,
      'role',jsonb_build_object('roleId',role.role_id,'version',role.row_version::text,'actions',role.action_intent_ids,
       'origin',role.origin,'createdByPrincipalId',role.created_by_principal_id::text,'creatorParticipantId',role.creator_participant_id::text,
       'bootstrapMandateId',role.bootstrap_mandate_id::text,'bootstrapPlatformParticipantId',role.bootstrap_platform_participant_id::text))),'UTF8')),'hex')
    AND a.state='ACTIVE' AND a.principal_id=principal.principal_id AND a.authority_envelope_id=e.authority_envelope_id
    AND a.role_id=role.role_id AND a.authority_group_id IS NULL AND a.delegation_epoch=e.delegation_epoch
    AND a.valid_during=tstzrange(e.valid_from,e.valid_until,'[)') AND a.valid_during @> clock_timestamp()
    AND a.privacy_domain_ids=e.privacy_domain_ids AND a.action_intent_ids=e.action_intent_ids AND a.resource_ids=e.resource_ids
    AND a.risk_classes=e.risk_classes AND cardinality(a.runtime_capability_ids)=0
    AND a.maker_checker_required AND a.step_up_required AND a.onward_delegation_depth=0,false))
    ORDER BY plan->>'principalId') INTO admins
 FROM jsonb_array_elements(r.candidate->'administrators') plan
 LEFT JOIN control.authority_envelope e ON e.participant_id=r.participant_id AND e.authority_envelope_id=(plan->>'envelopeId')::uuid
 LEFT JOIN control.identity_envelope_proposal p ON p.participant_id=r.participant_id AND p.privacy_domain_id=r.privacy_domain_id AND p.envelope_id=e.authority_envelope_id
 LEFT JOIN control.mutation_candidate create_intent ON create_intent.participant_id=r.participant_id AND create_intent.mutation_candidate_id=p.create_candidate_id
 LEFT JOIN control.identity_envelope_activation activation ON activation.participant_id=r.participant_id AND activation.privacy_domain_id=r.privacy_domain_id
  AND activation.envelope_id=e.authority_envelope_id AND activation.operation_id=e.last_mutation_operation_id
 LEFT JOIN control.assignment a ON a.participant_id=r.participant_id AND a.assignment_id=(plan->>'assignmentId')::uuid
 LEFT JOIN control.authority_role role ON role.participant_id=r.participant_id AND role.authority_role_id=(plan->>'roleId')::uuid
 LEFT JOIN control.principal principal ON principal.participant_id=r.participant_id AND principal.principal_id=(plan->>'principalId')::uuid;
 bindings:=jsonb_build_object('replacementId',r.replacement_id::text,'platformContextId',r.platform_context_id::text,
  'rootRevision',root.row_version::text,'predecessorEpoch',r.predecessor_epoch::text,'predecessorDigest','sha256:'||encode(r.predecessor_digest,'hex'),
  'successorDigest','sha256:'||encode(r.successor_digest,'hex'),'replacementRevision',r.row_version::text,'state',r.state,
  'targets',targets,'administrators',admins,'sourceExpiresAtNs',openpc.business_cbor(r.successor_scope_cbor)->>'4');
 RETURN bindings||jsonb_build_object('readinessDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
  jsonb_build_object('domain','pc.identity.platform-scope-readiness.v1','source',bindings)),'UTF8')),'hex'),
  'unacknowledgedTargets',(SELECT count(*) FROM jsonb_array_elements(targets) t WHERE t->>'ready' IS DISTINCT FROM 'true'),
  'unpreparedAdministrators',(SELECT count(*) FROM jsonb_array_elements(admins) a WHERE a->>'ready' IS DISTINCT FROM 'true'),
  'nowNs',(floor(extract(epoch from clock_timestamp())*1000000)*1000)::text);
END $$;
REVOKE ALL ON FUNCTION openpc.read_platform_scope_replacement_readiness(uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.commit_platform_scope_replacement(document jsonb,candidate_id uuid,approval_id uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE r control.platform_scope_replacement; initial control.platform_envelope_scope; current_root control.platform_context; readiness jsonb; queued record;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-CONTEXT'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('platform-scope-replacement:'||(document->>'platformContextId'),0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT r FROM control.platform_scope_replacement WHERE replacement_id=(document->>'replacementId')::uuid
  AND participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() FOR UPDATE;
 SELECT * INTO STRICT current_root FROM control.platform_context p WHERE p.platform_context_id=r.platform_context_id
  AND p.owner_participant_id=r.participant_id AND p.state='ACTIVE' FOR UPDATE;
 FOR queued IN SELECT q.runtime_target_id FROM control.platform_scope_target_withdrawal q WHERE q.replacement_id=r.replacement_id
  AND q.participant_id=r.participant_id AND q.privacy_domain_id=r.privacy_domain_id ORDER BY q.runtime_target_id LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||r.participant_id::text||':'||r.privacy_domain_id::text||':'||queued.runtime_target_id::text,0))
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 readiness:=openpc.read_platform_scope_replacement_readiness(r.replacement_id);
 IF coalesce((document->>'platformContextId'<>readiness->>'platformContextId'
   OR document->>'expectedRootRevision'<>readiness->>'rootRevision'
   OR document->>'expectedReplacementRevision'<>readiness->>'replacementRevision'
   OR document->>'predecessorEpoch'<>readiness->>'predecessorEpoch'
   OR document->>'predecessorDigest'<>readiness->>'predecessorDigest'
   OR document->>'successorDigest'<>readiness->>'successorDigest' OR document->>'readinessDigest'<>readiness->>'readinessDigest'
   OR readiness->>'unacknowledgedTargets'<>'0' OR readiness->>'unpreparedAdministrators'<>'0'
   OR (readiness->>'sourceExpiresAtNs')::numeric<=(readiness->>'nowNs')::numeric),true)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-READINESS'; END IF;
 SELECT * INTO STRICT initial FROM control.platform_envelope_scope s WHERE s.platform_context_id=r.platform_context_id;
 UPDATE control.platform_scope_replacement SET state='COMMITTED',row_version=2,commit_operation_id=openpc.current_operation_id(),
  commit_candidate_id=candidate_id,commit_approval_id=approval_id,readiness_digest=decode(substring(document->>'readinessDigest' from 8),'hex'),
  committed_at=clock_timestamp() WHERE replacement_id=r.replacement_id;
 INSERT INTO control.platform_envelope_scope_successor(platform_context_id,platform_authority_epoch,owner_participant_id,installation_privacy_domain_id,
  replacement_id,preparation_operation_id,predecessor_epoch,predecessor_digest,environment_id,installation_digest,scope_cbor,admission_preimage,admission_digest)
 VALUES(r.platform_context_id,r.predecessor_epoch+1,r.participant_id,r.privacy_domain_id,r.replacement_id,r.prepare_operation_id,
  r.predecessor_epoch,r.predecessor_digest,initial.environment_id,initial.installation_digest,r.successor_scope_cbor,r.successor_preimage,r.successor_digest);
 UPDATE control.platform_context SET authority_epoch=authority_epoch+1,row_version=row_version+1,updated_at=clock_timestamp()
  WHERE platform_context_id=r.platform_context_id AND authority_epoch=r.predecessor_epoch AND row_version=r.expected_root_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-PREDECESSOR'; END IF;
 RETURN jsonb_build_object('replacementId',r.replacement_id::text,'successorDigest','sha256:'||encode(r.successor_digest,'hex'),
  'state','COMMITTED','revision','2','operationId',openpc.current_operation_id()::text,'platformAuthorityEpoch',(r.predecessor_epoch+1)::text);
END $$;
REVOKE ALL ON FUNCTION openpc.commit_platform_scope_replacement(jsonb,uuid,uuid) FROM PUBLIC;

DROP POLICY IF EXISTS platform_scope_replacement_root_commit ON control.platform_context;
CREATE POLICY platform_scope_replacement_root_commit ON control.platform_context FOR UPDATE TO openpc_control_owner
 USING(openpc.matches_participant(owner_participant_id) AND openpc.current_action_intent_id()='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1')
 WITH CHECK(openpc.matches_participant(owner_participant_id) AND openpc.current_action_intent_id()='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  AND state='ACTIVE' AND EXISTS(SELECT 1 FROM control.platform_scope_replacement r WHERE r.platform_context_id=platform_context.platform_context_id
    AND r.participant_id=platform_context.owner_participant_id AND r.state='COMMITTED'
    AND r.commit_operation_id=openpc.current_operation_id() AND r.predecessor_epoch+1=platform_context.authority_epoch
    AND r.expected_root_revision+1=platform_context.row_version));


CREATE OR REPLACE FUNCTION openpc.reject_platform_scope_truncate()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-SCOPE-HISTORY'; END $$;
REVOKE ALL ON FUNCTION openpc.reject_platform_scope_truncate() FROM PUBLIC;
DROP TRIGGER IF EXISTS platform_scope_replacement_truncate ON control.platform_scope_replacement;
CREATE TRIGGER platform_scope_replacement_truncate BEFORE TRUNCATE ON control.platform_scope_replacement
 FOR EACH STATEMENT EXECUTE FUNCTION openpc.reject_platform_scope_truncate();
DROP TRIGGER IF EXISTS platform_scope_successor_truncate ON control.platform_envelope_scope_successor;
CREATE TRIGGER platform_scope_successor_truncate BEFORE TRUNCATE ON control.platform_envelope_scope_successor
 FOR EACH STATEMENT EXECUTE FUNCTION openpc.reject_platform_scope_truncate();


-- A separate PL/pgSQL statement prevents the Root's envelope visibility policy
-- from recursively expanding inside the envelope row-lock policy. INVOKER keeps
-- the actual installation owner and FORCE RLS; this returns no source data.
CREATE OR REPLACE FUNCTION openpc.platform_recovery_installation_source_current(p_enrollment uuid)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog,control SET row_security=on AS $$
BEGIN
 RETURN current_user='openpc_control_owner'
 AND openpc.current_action_intent_id() IN ('ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1')
 AND EXISTS(SELECT 1 FROM control.platform_recovery_enrollment enrollment
  JOIN control.platform_context root ON root.platform_context_id=enrollment.platform_context_id
   AND root.owner_participant_id=enrollment.participant_id AND root.state='ACTIVE'
   AND root.authority_epoch=enrollment.root_epoch AND root.row_version=enrollment.root_revision
  JOIN control.platform_scope_replacement replacement ON replacement.replacement_id=enrollment.expired_replacement_id
   AND replacement.participant_id=enrollment.participant_id AND replacement.privacy_domain_id=enrollment.privacy_domain_id
   AND replacement.platform_context_id=root.platform_context_id AND replacement.state='COMMITTED'
  JOIN control.platform_envelope_scope_successor successor ON successor.replacement_id=replacement.replacement_id
   AND successor.platform_context_id=root.platform_context_id AND successor.platform_authority_epoch=root.authority_epoch
   AND successor.admission_digest=enrollment.root_digest
  WHERE enrollment.enrollment_id=p_enrollment AND openpc.matches_participant(enrollment.participant_id)
   AND openpc.matches_privacy(enrollment.privacy_domain_id) AND enrollment.state='ACTIVE' AND enrollment.row_version=1
   AND enrollment.valid_from<=clock_timestamp() AND enrollment.valid_until>clock_timestamp());
END $$;
REVOKE ALL ON FUNCTION openpc.platform_recovery_installation_source_current(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.platform_recovery_installation_source_current(uuid) TO openpc_control_owner;

CREATE OR REPLACE FUNCTION openpc.is_platform_recovery_executor(p_principal uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
 SELECT EXISTS(SELECT 1 FROM control.platform_recovery_enrollment e
  WHERE openpc.matches_participant(e.participant_id)
   AND e.document#>>'{recoveryPrincipal,principalId}'=p_principal::text)
$$;
REVOKE ALL ON FUNCTION openpc.is_platform_recovery_executor(uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.lock_platform_recovery_enrollment(p_enrollment_id uuid)
RETURNS SETOF control.platform_recovery_enrollment LANGUAGE plpgsql VOLATILE SECURITY DEFINER
 SET search_path=pg_catalog,control SET row_security=on AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 -- Recovery activation writes recipient epochs and session families. Declare the
 -- common Participant write fence first, rather than upgrading child share locks.
 PERFORM 1 FROM control.participant p WHERE p.participant_id=openpc.current_participant_id() AND p.state='ACTIVE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 RETURN QUERY SELECT e.* FROM control.platform_recovery_enrollment e WHERE e.enrollment_id=p_enrollment_id
  AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id) FOR UPDATE OF e;
END $$;
REVOKE ALL ON FUNCTION openpc.lock_platform_recovery_enrollment(uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.guard_platform_recovery_enrollment()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED' OR NEW.row_version<>OLD.row_version+1
   OR (to_jsonb(NEW)-ARRAY['state','row_version','revoked_at','revocation_reason_digest']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['state','row_version','revoked_at','revocation_reason_digest']) THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 ELSE
  IF NEW.document->>'schema' IS NULL OR NEW.document->>'schema' NOT IN ('pc.identity.platform-recovery-enrollment','pc.identity.discovery-certificate-recovery-enrollment')
   OR NEW.document->>'schemaVersion' IS DISTINCT FROM '1'
   OR NEW.state<>'ACTIVE' OR NEW.row_version<>1 OR NEW.document_digest<>sha256(convert_to(openpc.signing_canonical_json(NEW.document),'UTF8'))
   OR NEW.document->>'enrollmentId' IS DISTINCT FROM NEW.enrollment_id::text
   OR NEW.document->>'participantId' IS DISTINCT FROM NEW.participant_id::text
   OR NEW.document->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
   OR NEW.document->>'platformContextId' IS DISTINCT FROM NEW.platform_context_id::text
   OR NEW.document->>'expiredReplacementId' IS DISTINCT FROM NEW.expired_replacement_id::text
   OR NEW.document->>'rootEpoch' IS DISTINCT FROM NEW.root_epoch::text
   OR NEW.document->>'rootRevision' IS DISTINCT FROM NEW.root_revision::text
   OR NEW.document->>'rootDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.root_digest,'hex')
   OR (NEW.document->>'validFrom')::timestamptz IS DISTINCT FROM NEW.valid_from
   OR (NEW.document->>'validUntil')::timestamptz IS DISTINCT FROM NEW.valid_until
   OR NOT EXISTS(SELECT 1 FROM control.platform_context p JOIN control.platform_scope_replacement r
      ON r.platform_context_id=p.platform_context_id AND r.replacement_id=NEW.expired_replacement_id
       AND r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id AND r.state='COMMITTED'
      JOIN control.platform_envelope_scope_successor s ON s.replacement_id=r.replacement_id
       AND s.platform_context_id=p.platform_context_id AND s.platform_authority_epoch=p.authority_epoch
       AND s.admission_digest=NEW.root_digest
      WHERE p.platform_context_id=NEW.platform_context_id AND p.owner_participant_id=NEW.participant_id
       AND p.state='ACTIVE' AND p.authority_epoch=NEW.root_epoch AND p.row_version=NEW.root_revision)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS platform_recovery_enrollment_guard ON control.platform_recovery_enrollment;
CREATE TRIGGER platform_recovery_enrollment_guard BEFORE INSERT OR UPDATE OR DELETE ON control.platform_recovery_enrollment
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_platform_recovery_enrollment();

-- A new recovery request may supersede only the independently governed expired, uneffected handoff.
CREATE OR REPLACE FUNCTION openpc.platform_recovery_supersession_current(participant uuid,enrollment uuid,link jsonb,preparation jsonb)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
 SELECT EXISTS(SELECT 1 FROM control.platform_recovery_case original
  JOIN control.platform_scope_replacement r ON r.participant_id=original.participant_id
   AND r.privacy_domain_id=original.privacy_domain_id AND r.candidate=original.intent->'preparation'
  JOIN control.mutation_candidate m ON m.participant_id=r.participant_id AND m.privacy_domain_id=r.privacy_domain_id
   AND m.mutation_candidate_id=r.prepare_candidate_id AND m.candidate_digest=r.candidate_digest
   AND m.catalog_operation_id='ID-OP-PLATFORM-SCOPE-PREPARE' AND m.state='CONSUMED' AND m.consumed_operation_id=r.prepare_operation_id
  JOIN control.approval_request a ON a.participant_id=m.participant_id AND a.privacy_domain_id=m.privacy_domain_id
   AND a.subject_id=m.mutation_candidate_id AND a.subject_digest=m.candidate_digest
   AND a.approval_request_id=r.prepare_approval_id AND a.state='APPROVED'
  WHERE original.participant_id=participant AND original.enrollment_id=enrollment
   AND openpc.matches_participant(participant) AND openpc.matches_privacy(original.privacy_domain_id)
   AND original.state='EXPIRED' AND original.valid_until<=clock_timestamp() AND original.activation_operation_id IS NOT NULL
   AND link=jsonb_build_object('recoveryId',original.recovery_id::text,'intentDigest','sha256:'||encode(original.intent_digest,'hex'),
     'replacementId',r.replacement_id::text,'preparationDigest','sha256:'||encode(r.candidate_digest,'hex'),
     'preparationOperationId',r.prepare_operation_id::text,'preparationApprovalId',r.prepare_approval_id::text,
     'expectedRevision','1','successorDigest','sha256:'||encode(r.successor_digest,'hex'))
   AND preparation->'supersedes'=jsonb_build_object('replacementId',r.replacement_id::text,'expectedRevision','1',
       'successorDigest','sha256:'||encode(r.successor_digest,'hex'))
   AND preparation->>'replacementId'<>r.replacement_id::text
   AND preparation->>'platformContextId'=r.platform_context_id::text
   AND preparation->>'predecessorEpoch'=r.predecessor_epoch::text
   AND preparation->>'expectedRootRevision'=r.expected_root_revision::text
   AND preparation->>'predecessorDigest'='sha256:'||encode(r.predecessor_digest,'hex')
   AND ((r.state='WITHDRAWING' AND r.row_version=1 AND r.superseded_by IS NULL)
     OR (r.state='SUPERSEDED' AND r.row_version=2 AND r.superseded_by::text=preparation->>'replacementId'
       AND EXISTS(SELECT 1 FROM control.platform_scope_replacement next WHERE next.replacement_id=r.superseded_by
         AND next.participant_id=participant AND next.privacy_domain_id=r.privacy_domain_id AND next.state='WITHDRAWING'
         AND next.candidate=preparation)))
   AND jsonb_array_length(r.candidate->'administrators')=2
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r.candidate->'administrators') admin
    WHERE (admin#>>'{usable,validUntilNs}')::numeric>floor(extract(epoch FROM clock_timestamp())*1000000000)
      OR (admin#>>'{grantable,validUntilNs}')::numeric>floor(extract(epoch FROM clock_timestamp())*1000000000)
      OR EXISTS(SELECT 1 FROM control.authority_envelope e WHERE e.participant_id=participant AND e.authority_envelope_id::text=admin->>'envelopeId')
      OR EXISTS(SELECT 1 FROM control.assignment assignment WHERE assignment.participant_id=participant AND assignment.assignment_id::text=admin->>'assignmentId')
      OR EXISTS(SELECT 1 FROM control.identity_envelope_proposal proposal WHERE proposal.participant_id=participant AND proposal.envelope_id::text=admin->>'envelopeId'))
 )
$$;
REVOKE ALL ON FUNCTION openpc.platform_recovery_supersession_current(uuid,uuid,jsonb,jsonb) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.guard_platform_recovery_case()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control AS $$
DECLARE source record; signer_repair boolean; review boolean;
BEGIN
 signer_repair:=NEW.signer_repair_enrollment_id IS NOT NULL;
 review:=TG_OP='UPDATE' AND NEW.reviewed_at IS NOT NULL AND OLD.reviewed_at IS NULL;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'DRAFT' OR NEW.row_version<>1 OR NEW.activated_at IS NOT NULL
   OR NEW.intent_digest<>sha256(convert_to(openpc.signing_canonical_json(NEW.intent),'UTF8'))
   OR NEW.intent->>'recoveryId' IS DISTINCT FROM NEW.recovery_id::text
   OR NEW.intent->>'enrollmentId' IS DISTINCT FROM coalesce(NEW.enrollment_id,NEW.signer_repair_enrollment_id)::text
   OR NEW.intent->>'enrollmentRevision' IS DISTINCT FROM NEW.enrollment_revision::text
   OR NEW.intent->>'enrollmentDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.enrollment_digest,'hex')
   OR (NEW.intent->>'validFrom')::timestamptz IS DISTINCT FROM NEW.valid_from
   OR (NEW.intent->>'validUntil')::timestamptz IS DISTINCT FROM NEW.valid_until
   OR NEW.intent->>'schema' IS NULL OR NEW.intent->>'schema' NOT IN ('pc.identity.platform-recovery-intent','pc.identity.discovery-certificate-recovery-intent','pc.identity.identity-envelope-recovery-intent')
   OR NEW.intent->>'schemaVersion' IS DISTINCT FROM '1'
   OR jsonb_array_length(NEW.planned_record_ids)<>(CASE WHEN signer_repair THEN 2 WHEN NEW.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent' THEN 0 ELSE 5 END)
   OR NEW.completion_operation_id IS NOT NULL OR NEW.completion_result IS NOT NULL
   OR num_nonnulls(NEW.reviewed_at,NEW.reviewed_by_principal_id,NEW.review_operation_id,NEW.review_note_digest)<>0
   OR (NEW.intent ? 'lifetimes' AND (NOT (NEW.intent->'lifetimes' ?& ARRAY['profile','leaseMs','administratorMs'])
      OR (NEW.intent->'lifetimes')-ARRAY['profile','leaseMs','administratorMs']<>'{}'::jsonb
      OR NEW.intent#>>'{lifetimes,profile}' NOT IN ('C17','LOCAL_QA')
      OR (NEW.intent#>>'{lifetimes,leaseMs}')::bigint NOT BETWEEN 1 AND CASE WHEN NEW.intent#>>'{lifetimes,profile}'='LOCAL_QA' THEN 3600000 ELSE 900000 END
      OR (NEW.intent#>>'{lifetimes,administratorMs}')::bigint NOT BETWEEN 1 AND CASE WHEN NEW.intent#>>'{lifetimes,profile}'='LOCAL_QA' THEN 86400000 ELSE 3600000 END
      OR NEW.valid_until>NEW.valid_from+((NEW.intent#>>'{lifetimes,leaseMs}')::bigint*interval '1 millisecond')))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 ELSE
  IF NEW.row_version<>OLD.row_version+1 OR NEW.updated_at<=OLD.updated_at
   OR (to_jsonb(NEW)-ARRAY['state','row_version','updated_at','activated_at','activation_operation_id',
      'activation_evidence_cbor','activation_evidence_digest','activation_cose','lease_bindings','completion_operation_id','completion_result',
      'reviewed_at','reviewed_by_principal_id','review_operation_id','review_note_digest']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['state','row_version','updated_at','activated_at','activation_operation_id',
      'activation_evidence_cbor','activation_evidence_digest','activation_cose','lease_bindings','completion_operation_id','completion_result',
      'reviewed_at','reviewed_by_principal_id','review_operation_id','review_note_digest'])
   OR NOT ((OLD.state='DRAFT' AND NEW.state IN ('REQUESTED','REVOKED','EXPIRED'))
      OR (OLD.state='REQUESTED' AND NEW.state IN ('ACTIVE','REVOKED','EXPIRED'))
      OR (OLD.state='ACTIVE' AND NEW.state IN ('COMPLETED','REVOKED','EXPIRED'))
      OR (review AND OLD.state=NEW.state AND OLD.state IN ('COMPLETED','REVOKED','EXPIRED')))
   OR (NEW.state<>'ACTIVE' AND (NEW.activated_at,NEW.activation_operation_id,NEW.activation_evidence_cbor,
      NEW.activation_evidence_digest,NEW.activation_cose,NEW.lease_bindings) IS DISTINCT FROM
     (OLD.activated_at,OLD.activation_operation_id,OLD.activation_evidence_cbor,
      OLD.activation_evidence_digest,OLD.activation_cose,OLD.lease_bindings))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 END IF;
 IF TG_OP='UPDATE' AND (NEW.completion_operation_id,NEW.completion_result) IS DISTINCT FROM (OLD.completion_operation_id,OLD.completion_result)
  AND NOT (OLD.state='ACTIVE' AND NEW.state='COMPLETED' AND NEW.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent'
   AND NEW.completion_operation_id IS NOT NULL AND NEW.completion_result IS NOT NULL) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF signer_repair THEN
  IF NEW.enrollment_id IS NOT NULL OR NEW.intent->>'schema' IS DISTINCT FROM 'pc.identity.identity-envelope-recovery-intent'
   OR NEW.intent->>'purpose' IS DISTINCT FROM 'IDENTITY_ENVELOPE_SIGNER_REPAIR_ONLY'
   OR NEW.intent->'postReviewRequired' IS DISTINCT FROM 'true'::jsonb
   OR NEW.intent-ARRAY['schema','schemaVersion','purpose','recoveryId','enrollmentId','enrollmentRevision','enrollmentDigest',
     'rotationId','creationOperationId','sourceParticipantEpoch','sourceIssuerPrincipalEpoch','sourceIssuerCredentialEpoch',
     'oldTrustDigest','selectionAdmissionVersion','validFrom','validUntil','postReviewRequired']<>'{}'::jsonb
   OR NEW.planned_record_ids IS DISTINCT FROM jsonb_build_array(NEW.intent->>'rotationId',NEW.intent->>'creationOperationId')
   OR NEW.intent->>'rotationId'=NEW.intent->>'creationOperationId'
   OR NEW.valid_until>NEW.valid_from+interval '15 minutes'
   OR (TG_OP='INSERT' AND EXISTS(SELECT 1 FROM control.platform_recovery_case prior
     JOIN control.identity_envelope_recovery_enrollment original ON original.enrollment_id=prior.signer_repair_enrollment_id
      AND original.participant_id=prior.participant_id
     JOIN control.identity_envelope_recovery_enrollment proposed ON proposed.enrollment_id=NEW.signer_repair_enrollment_id
      AND proposed.participant_id=NEW.participant_id
     WHERE prior.participant_id=NEW.participant_id AND original.document->>'issuerPrincipalId'=proposed.document->>'issuerPrincipalId'
      AND prior.activated_at IS NOT NULL AND prior.reviewed_at IS NULL))
   -- Completion is owned by the genuine consumer/old-key retirement suffix.
   OR NEW.state='COMPLETED' THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
  IF NEW.state='ACTIVE' AND (NEW.activation_operation_id IS DISTINCT FROM openpc.current_operation_id()
    OR NEW.activation_operation_id::text IS DISTINCT FROM NEW.lease_bindings->>'activationOperationId'
    OR NEW.activated_at IS DISTINCT FROM (NEW.lease_bindings->>'validFrom')::timestamptz
    OR NOT coalesce(openpc.identity_envelope_recovery_binding_current(NEW.signer_repair_enrollment_id,NEW.intent,NEW.lease_bindings),false)
    OR NOT openpc.identity_envelope_recovery_proofs_current(NEW,(NEW.lease_bindings#>>'{proofIds,3}')::uuid)) THEN
    RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 END IF;
 IF TG_OP='UPDATE' AND (NEW.reviewed_at,NEW.reviewed_by_principal_id,NEW.review_operation_id,NEW.review_note_digest)
   IS DISTINCT FROM (OLD.reviewed_at,OLD.reviewed_by_principal_id,OLD.review_operation_id,OLD.review_note_digest) THEN
  IF NOT review OR NOT signer_repair OR NEW.review_operation_id IS DISTINCT FROM openpc.current_operation_id()
    OR OLD.activated_at IS NULL OR OLD.state NOT IN ('COMPLETED','REVOKED','EXPIRED')
    OR NEW.reviewed_by_principal_id IS NULL OR NEW.review_note_digest IS NULL
    OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_recovery_enrollment enrollment
      JOIN control.mutation_candidate candidate ON candidate.participant_id=enrollment.participant_id
       AND candidate.privacy_domain_id=enrollment.privacy_domain_id AND candidate.catalog_operation_id='ID-OP-RECOVERY-POST-REVIEW'
       AND candidate.resource_id=NEW.recovery_id AND candidate.maker_principal_id=NEW.reviewed_by_principal_id
       AND candidate.state='APPROVED' AND candidate.candidate_document->>'recoveryId'=NEW.recovery_id::text
       AND sha256(convert_to(candidate.candidate_document->>'note','UTF8'))=NEW.review_note_digest
      JOIN control.approval_request approval ON approval.participant_id=candidate.participant_id
       AND approval.privacy_domain_id=candidate.privacy_domain_id AND approval.subject_id=candidate.mutation_candidate_id
       AND approval.subject_digest=candidate.candidate_digest AND approval.state='APPROVED'
      WHERE enrollment.enrollment_id=NEW.signer_repair_enrollment_id
       AND NEW.reviewed_by_principal_id::text NOT IN (enrollment.document->>'issuerPrincipalId',enrollment.document#>>'{recoveryPrincipal,principalId}')
       AND approval.checker_principal_id::text NOT IN (enrollment.document->>'issuerPrincipalId',enrollment.document#>>'{recoveryPrincipal,principalId}')
       AND approval.checker_principal_id<>NEW.reviewed_by_principal_id
       AND EXISTS(SELECT 1 FROM control.approval_decision_record decision WHERE decision.participant_id=approval.participant_id
         AND decision.privacy_domain_id=approval.privacy_domain_id AND decision.approval_request_id=approval.approval_request_id
         AND decision.approver_principal_id=approval.checker_principal_id AND decision.decision='APPROVE'
         AND decision.candidate_digest=candidate.candidate_digest)) THEN
    RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY-REVIEW'; END IF;
 END IF;
 IF NEW.state IN ('DRAFT','REQUESTED','ACTIVE') THEN
  IF NEW.intent ? 'supersession' AND NOT openpc.platform_recovery_supersession_current(NEW.participant_id,NEW.enrollment_id,NEW.intent->'supersession',NEW.intent->'preparation') THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
  IF signer_repair THEN
   SELECT * INTO source FROM control.identity_envelope_recovery_enrollment e WHERE e.enrollment_id=NEW.signer_repair_enrollment_id
    AND e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id AND e.state='ACTIVE'
    AND e.row_version=NEW.enrollment_revision AND e.document_digest=NEW.enrollment_digest
    AND e.valid_from<=clock_timestamp() AND e.valid_until>clock_timestamp()
    AND openpc.identity_envelope_recovery_source_current(e.enrollment_id);
  ELSE
   SELECT * INTO source FROM control.platform_recovery_enrollment e WHERE e.enrollment_id=NEW.enrollment_id
    AND e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id AND e.state='ACTIVE'
    AND e.row_version=NEW.enrollment_revision AND e.document_digest=NEW.enrollment_digest
    AND e.valid_from<=clock_timestamp() AND e.valid_until>clock_timestamp();
  END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
  IF signer_repair AND (
    NEW.intent->>'sourceParticipantEpoch' IS DISTINCT FROM source.document->>'issuerParticipantEpoch'
    OR NEW.intent->>'sourceIssuerPrincipalEpoch' IS DISTINCT FROM source.document->>'issuerPrincipalEpoch'
    OR NEW.intent->>'sourceIssuerCredentialEpoch' IS DISTINCT FROM source.document->>'issuerCredentialEpoch'
    OR NEW.intent->>'oldTrustDigest' IS DISTINCT FROM source.document->>'oldTrustDigest'
    OR NEW.intent->>'selectionAdmissionVersion' IS DISTINCT FROM source.document->>'selectionAdmissionVersion') THEN
   RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
  IF NEW.intent->>'schema' IS DISTINCT FROM (CASE source.document->>'schema'
     WHEN 'pc.identity.platform-recovery-enrollment' THEN 'pc.identity.platform-recovery-intent'
     WHEN 'pc.identity.discovery-certificate-recovery-enrollment' THEN 'pc.identity.discovery-certificate-recovery-intent'
     WHEN 'pc.identity.identity-envelope-recovery-enrollment' THEN 'pc.identity.identity-envelope-recovery-intent' ELSE NULL END)
    OR NEW.valid_until>source.valid_until OR NEW.valid_until<=clock_timestamp()
   OR (source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR' AND current_setting('openpc.local_qa_runtime',true) IS DISTINCT FROM '1')
   OR (NEW.intent#>>'{lifetimes,profile}'='LOCAL_QA' AND source.document->>'assurance' IS DISTINCT FROM 'LOCAL_QA_VIRTUAL_AUTHENTICATOR') THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 END IF;
 IF NEW.state IN ('REQUESTED','ACTIVE') THEN
  IF NOT EXISTS(SELECT 1 FROM control.platform_recovery_proof proof WHERE proof.recovery_id=NEW.recovery_id
   AND proof.participant_id=NEW.participant_id AND proof.privacy_domain_id=NEW.privacy_domain_id AND proof.phase='REQUEST'
   AND proof.principal_id::text=source.document#>>'{recoveryPrincipal,principalId}' AND proof.intent_digest=NEW.intent_digest
   AND proof.verified_at>clock_timestamp()-interval '5 minutes') THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 END IF;
 IF NEW.state='ACTIVE' THEN
  IF NEW.activation_evidence_digest<>sha256(NEW.activation_evidence_cbor)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(source.document->'custodians') custodian
    WHERE NOT EXISTS(SELECT 1 FROM control.platform_recovery_proof proof WHERE proof.recovery_id=NEW.recovery_id
     AND proof.participant_id=NEW.participant_id AND proof.privacy_domain_id=NEW.privacy_domain_id AND proof.phase='APPROVE'
     AND proof.principal_id::text=custodian->>'principalId' AND proof.credential_id::text=custodian->>'credentialId'
     AND proof.principal_epoch::text=custodian->>'principalEpoch' AND proof.credential_epoch::text=custodian->>'credentialEpoch'
     AND proof.intent_digest=NEW.intent_digest AND proof.verified_at>clock_timestamp()-interval '5 minutes'))
   OR NOT EXISTS(SELECT 1 FROM control.platform_recovery_proof proof WHERE proof.recovery_id=NEW.recovery_id
    AND proof.participant_id=NEW.participant_id AND proof.privacy_domain_id=NEW.privacy_domain_id AND proof.phase='ACTIVATE'
    AND proof.principal_id::text=source.document#>>'{recoveryPrincipal,principalId}' AND proof.intent_digest=NEW.intent_digest
    AND proof.verified_at>clock_timestamp()-interval '5 minutes') THEN
   RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS platform_recovery_case_guard ON control.platform_recovery_case;
CREATE TRIGGER platform_recovery_case_guard BEFORE INSERT OR UPDATE OR DELETE ON control.platform_recovery_case
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_platform_recovery_case();

CREATE OR REPLACE FUNCTION openpc.guard_platform_recovery_challenge()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF TG_OP='UPDATE' AND (OLD.consumed_at IS NOT NULL OR NEW.consumed_at IS NULL OR NEW.proof_id IS NULL
   OR (to_jsonb(NEW)-ARRAY['consumed_at','proof_id']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['consumed_at','proof_id'])
   OR NOT EXISTS(SELECT 1 FROM control.platform_recovery_proof p WHERE p.proof_id=NEW.proof_id AND p.challenge_id=NEW.challenge_id
    AND p.participant_id=NEW.participant_id AND p.privacy_domain_id=NEW.privacy_domain_id AND p.recovery_id=NEW.recovery_id)) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF TG_OP='INSERT' AND (NEW.consumed_at IS NOT NULL OR NEW.proof_id IS NOT NULL) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS platform_recovery_challenge_guard ON control.platform_recovery_challenge;
CREATE TRIGGER platform_recovery_challenge_guard BEFORE INSERT OR UPDATE OR DELETE ON control.platform_recovery_challenge
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_platform_recovery_challenge();

CREATE OR REPLACE FUNCTION openpc.guard_platform_recovery_proof()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.platform_recovery_challenge c JOIN control.platform_recovery_case r
   ON r.recovery_id=c.recovery_id AND r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id
  JOIN (SELECT enrollment_id,participant_id,privacy_domain_id,state,row_version,document_digest,document,valid_from,valid_until,
    CASE document->>'schema' WHEN 'pc.identity.platform-recovery-enrollment' THEN 'pc.identity.platform-recovery-intent'
      WHEN 'pc.identity.discovery-certificate-recovery-enrollment' THEN 'pc.identity.discovery-certificate-recovery-intent' END purpose
    FROM control.platform_recovery_enrollment
   UNION ALL SELECT enrollment_id,participant_id,privacy_domain_id,state,row_version,document_digest,document,valid_from,valid_until,
    'pc.identity.identity-envelope-recovery-intent' purpose FROM control.identity_envelope_recovery_enrollment) source
   ON source.enrollment_id=coalesce(r.enrollment_id,r.signer_repair_enrollment_id) AND source.purpose=r.intent->>'schema'
   AND source.participant_id=r.participant_id AND source.privacy_domain_id=r.privacy_domain_id
   AND source.state='ACTIVE' AND source.row_version=r.enrollment_revision AND source.document_digest=r.enrollment_digest
   AND (r.signer_repair_enrollment_id IS NULL OR openpc.identity_envelope_recovery_source_current(source.enrollment_id))
  JOIN LATERAL jsonb_array_elements(CASE WHEN NEW.phase='APPROVE' THEN source.document->'custodians'
    ELSE jsonb_build_array(source.document->'recoveryPrincipal') END) signer
   ON signer->>'principalId'=NEW.principal_id::text AND signer->>'credentialId'=NEW.credential_id::text
    AND signer->>'principalEpoch'=NEW.principal_epoch::text AND signer->>'credentialEpoch'=NEW.credential_epoch::text
  JOIN control.principal p ON p.participant_id=NEW.participant_id AND p.principal_id=NEW.principal_id
   AND p.state='ACTIVE' AND p.authority_epoch=NEW.principal_epoch
  JOIN control.credential credential ON credential.participant_id=p.participant_id AND credential.principal_id=p.principal_id
   AND credential.credential_id=NEW.credential_id AND credential.credential_epoch=NEW.credential_epoch
   AND credential.kind='WEBAUTHN' AND credential.state='ACTIVE' AND credential.valid_from<=clock_timestamp()
   AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
  JOIN control.session session ON session.participant_id=p.participant_id AND session.principal_id=p.principal_id
   AND session.session_id=NEW.session_id AND session.session_epoch=NEW.session_epoch AND session.authority_epoch=p.authority_epoch
   AND session.context_mode='PLATFORM' AND session.privacy_domain_id IS NULL AND session.state='ACTIVE'
   AND session.idle_expires_at>clock_timestamp() AND session.absolute_expires_at>clock_timestamp()
  JOIN control.participant participant ON participant.participant_id=p.participant_id AND participant.state='ACTIVE'
   AND participant.authority_epoch=session.participant_epoch
  WHERE c.challenge_id=NEW.challenge_id AND c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
   AND c.recovery_id=NEW.recovery_id AND c.principal_id=NEW.principal_id AND c.credential_id=NEW.credential_id
   AND c.session_id=NEW.session_id AND c.session_epoch=NEW.session_epoch AND c.phase=NEW.phase
   AND c.intent_digest=NEW.intent_digest AND r.intent_digest=NEW.intent_digest
   AND ((NEW.phase='REQUEST' AND r.state='DRAFT') OR (NEW.phase IN ('APPROVE','ACTIVATE') AND r.state='REQUESTED'))
   AND c.consumed_at IS NULL AND c.expires_at>clock_timestamp() AND r.valid_until>clock_timestamp()
   AND NEW.verified_at BETWEEN c.created_at AND clock_timestamp()
   AND source.valid_from<=clock_timestamp() AND source.valid_until>clock_timestamp()
   AND (source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR' OR EXISTS(SELECT 1 FROM control.hardware_authenticator h
    WHERE h.participant_id=p.participant_id AND h.principal_id=p.principal_id AND h.credential_id=credential.credential_id))
   AND NEW.assertion_evidence#>>'{verified,version}'='OPENPC_VERIFIED_WEBAUTHN_ASSERTION_V1'
   AND NEW.assertion_evidence#>>'{verified,userVerification}'='REQUIRED_VERIFIED'
   AND NEW.assertion_evidence#>>'{verified,credentialId}'=credential.credential_id::text
   AND NEW.assertion_evidence#>>'{verified,credentialPublicKeyDigest}'='sha256:'||encode(credential.public_key_digest,'hex')
   AND NEW.assertion_evidence#>>'{verified,principalId}'=NEW.principal_id::text
   AND NEW.assertion_evidence#>>'{verified,sessionId}'=NEW.session_id::text
   AND NEW.assertion_evidence#>>'{verified,actionIntentId}'='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
   AND NEW.assertion_evidence#>>'{verified,resourceDigest}'='sha256:'||encode(NEW.intent_digest,'hex')
   AND NEW.assertion_evidence#>>'{verified,challengeDigest}'='sha256:'||encode(c.challenge_digest,'hex')
   AND NEW.assertion_evidence#>>'{verified,origin}'=c.origin
   AND NEW.assertion_evidence#>>'{verified,signCount}'=NEW.authenticator_sign_count::text
   AND (NEW.assertion_evidence#>>'{verified,verifiedAt}')::timestamptz=NEW.verified_at) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 IF NEW.assertion_digest IS DISTINCT FROM sha256(convert_to(NEW.assertion_evidence#>>'{verified,version}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,credentialId}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,credentialPublicKeyDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,principalId}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,sessionId}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,actionIntentId}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,resourceDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,challengeDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,rpIdHash}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,origin}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,authenticatorDataDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,clientDataJsonDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,signatureDigest}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,signCount}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,verifiedAt}','UTF8')||decode('00','hex')||convert_to(NEW.assertion_evidence#>>'{verified,userVerification}','UTF8')) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS platform_recovery_proof_guard ON control.platform_recovery_proof;
CREATE TRIGGER platform_recovery_proof_guard BEFORE INSERT OR UPDATE OR DELETE ON control.platform_recovery_proof
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_platform_recovery_proof();

CREATE OR REPLACE FUNCTION openpc.discovery_certificate_recovery_source(p_enrollment uuid,p_case uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
 SELECT jsonb_build_object(
  'participantId',e.participant_id::text,'privacyDomainId',e.privacy_domain_id::text,
  'participantState',participant.state::text,'privacyState',privacy.state::text,
  'targetId',target.runtime_target_id::text,'targetParticipantId',target.participant_id::text,
  'targetPrivacyDomainId',target.privacy_domain_id::text,'targetRevision',target.revision::text,
  'requiresAuthenticatedDiscovery',target.requires_authenticated_discovery,
  'workloadPrincipalId',principal.principal_id::text,'workloadPrincipalParticipantId',principal.participant_id::text,
  'workloadPrincipalState',principal.state::text,'workloadPrincipalKind',principal.kind::text,
  'workloadPrincipalEpoch',principal.authority_epoch::text,
  'credentialId',credential.credential_id::text,'credentialParticipantId',credential.participant_id::text,
  'credentialPrincipalId',credential.principal_id::text,'credentialState',credential.state::text,
  'credentialKind',credential.kind::text,'credentialRevision',credential.row_version::text,
  'credentialEpoch',credential.credential_epoch::text,
  'certificateFingerprint','sha256:'||encode(credential.secret_fingerprint,'hex'),
  'certificateBytesDigest','sha256:'||encode(sha256(credential.certificate_der),'hex'),
  'publicKeyDigest','sha256:'||encode(credential.public_key_digest,'hex'),
  'publicKeyBytesDigest','sha256:'||encode(sha256(credential.public_key_spki_der),'hex'),
  'issuer',credential.issuer,'subject',credential.subject,'audience',credential.audience,
  'notBefore',credential.valid_from,'notAfter',credential.valid_until,'now',clock_timestamp(),
  'successorExists',exists(select 1 from control.credential successor where successor.participant_id=e.participant_id
    and successor.credential_id::text=e.document#>>'{certificateRecovery,successorCredentialId}'),
  'competingSuccessor',exists(select 1 from control.credential successor where successor.participant_id=e.participant_id
    and successor.rotated_from_credential_id=credential.credential_id)
   or exists(select 1 from control.discovery_certificate_issuance attempt where attempt.participant_id=e.participant_id
    and attempt.predecessor_credential_id=credential.credential_id and attempt.state<>'REJECTED'
    and attempt.recovery_id is distinct from p_case))
 FROM control.platform_recovery_enrollment e
 JOIN control.participant participant on participant.participant_id=e.participant_id and participant.state='ACTIVE'
 JOIN control.privacy_domain privacy on privacy.participant_id=e.participant_id and privacy.privacy_domain_id=e.privacy_domain_id and privacy.state='ACTIVE'
 JOIN control.platform_context root on root.platform_context_id=e.platform_context_id and root.owner_participant_id=e.participant_id
  and root.state='ACTIVE' and root.authority_epoch=e.root_epoch and root.row_version=e.root_revision
 JOIN control.platform_envelope_scope_successor scope on scope.platform_context_id=root.platform_context_id
  and scope.platform_authority_epoch=root.authority_epoch and scope.admission_digest=e.root_digest
 JOIN control.runtime_target target on target.participant_id=e.participant_id and target.privacy_domain_id=e.privacy_domain_id
  and target.runtime_target_id::text=e.document#>>'{certificateRecovery,targetId}'
 JOIN control.principal principal on principal.participant_id=e.participant_id
  and principal.principal_id::text=e.document#>>'{certificateRecovery,workloadPrincipalId}'
 JOIN control.credential credential on credential.participant_id=e.participant_id and credential.principal_id=principal.principal_id
  and credential.credential_id::text=e.document#>>'{certificateRecovery,predecessorCredentialId}'
 WHERE e.enrollment_id=p_enrollment and e.state='ACTIVE'
  and e.document->>'schema'='pc.identity.discovery-certificate-recovery-enrollment'
  and e.document#>>'{certificateRecovery,purpose}'='DISCOVERY_CERTIFICATE_REPLACEMENT'
  and openpc.matches_participant(e.participant_id) and openpc.matches_privacy(e.privacy_domain_id)
  and e.valid_from<=clock_timestamp() and e.valid_until>clock_timestamp()
  and (e.document->>'assurance'<>'LOCAL_QA_VIRTUAL_AUTHENTICATOR' or current_setting('openpc.local_qa_runtime',true)='1')
  and (p_case is null or exists(select 1 from control.platform_recovery_case c where c.recovery_id=p_case
   and c.enrollment_id=e.enrollment_id and c.participant_id=e.participant_id and c.privacy_domain_id=e.privacy_domain_id
   and c.enrollment_revision=e.row_version and c.enrollment_digest=e.document_digest
   and c.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent'
   and c.intent->'certificateRecovery'=e.document->'certificateRecovery'))
$$;
REVOKE ALL ON FUNCTION openpc.discovery_certificate_recovery_source(uuid,uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.discovery_certificate_recovery_current(p_enrollment uuid,p_case uuid)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
DECLARE source jsonb; binding jsonb;
BEGIN
 SELECT openpc.discovery_certificate_recovery_source(p_enrollment,p_case) INTO source;
 IF source IS NULL THEN RETURN false; END IF;
 SELECT e.document->'certificateRecovery' INTO binding FROM control.platform_recovery_enrollment e
  WHERE e.enrollment_id=p_enrollment and openpc.matches_participant(e.participant_id) and openpc.matches_privacy(e.privacy_domain_id);
 RETURN coalesce(source->>'participantState'='ACTIVE' and source->>'privacyState'='ACTIVE'
  and source->>'targetId'=binding->>'targetId' and source->>'targetRevision'=binding->>'targetRevision'
  and source->>'requiresAuthenticatedDiscovery'='true'
  and source->>'workloadPrincipalId'=binding->>'workloadPrincipalId' and source->>'workloadPrincipalState'='ACTIVE'
  and source->>'workloadPrincipalKind'='WORKLOAD' and source->>'workloadPrincipalEpoch'=binding->>'workloadPrincipalEpoch'
  and source->>'credentialId'=binding->>'predecessorCredentialId' and source->>'credentialState'='ACTIVE'
  and source->>'credentialKind'='WORKLOAD_MTLS' and source->>'credentialRevision'=binding->>'predecessorRevision'
  and source->>'credentialEpoch'=binding->>'predecessorEpoch' and (source->>'credentialEpoch')::numeric>0
  and source->>'certificateFingerprint'=binding->>'predecessorFingerprint'
  and source->>'certificateBytesDigest'=binding->>'predecessorFingerprint'
  and source->>'publicKeyDigest'=binding->>'predecessorPublicKeyDigest'
  and source->>'publicKeyBytesDigest'=binding->>'predecessorPublicKeyDigest' and source->>'issuer'=binding->>'issuer'
  and source->>'subject'='urn:openpc:participant:'||(source->>'participantId')||':workload:'||(binding->>'targetId')
  and source->>'audience'='urn:openpc:workload:'||(binding->>'targetId')
  and (source->>'notAfter')::timestamptz=(binding->>'predecessorNotAfter')::timestamptz
  and (source->>'notAfter')::timestamptz<=clock_timestamp()
  and (source->>'notBefore')::timestamptz<(source->>'notAfter')::timestamptz
  and (source->>'notBefore')::timestamptz<=clock_timestamp()
  and source->>'successorExists'='false' and source->>'competingSuccessor'='false',false);
END $$;
REVOKE ALL ON FUNCTION openpc.discovery_certificate_recovery_current(uuid,uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.lock_discovery_certificate_recovery_source(p_enrollment uuid,p_case uuid)
RETURNS TABLE(source jsonb) LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
DECLARE enrolled control.platform_recovery_enrollment;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT * INTO enrolled FROM control.platform_recovery_enrollment e WHERE e.enrollment_id=p_enrollment
  and openpc.matches_participant(e.participant_id) and openpc.matches_privacy(e.privacy_domain_id)
  and e.document->>'schema'='pc.identity.discovery-certificate-recovery-enrollment';
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-RECOVERY'; END IF;
 PERFORM 1 FROM control.principal p WHERE p.participant_id=enrolled.participant_id
  and p.principal_id::text=enrolled.document#>>'{certificateRecovery,workloadPrincipalId}' FOR SHARE;
 PERFORM 1 FROM control.credential c WHERE c.participant_id=enrolled.participant_id
  and c.credential_id::text=enrolled.document#>>'{certificateRecovery,predecessorCredentialId}' FOR SHARE;
 IF NOT openpc.discovery_certificate_recovery_current(p_enrollment,p_case) THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-RECOVERY'; END IF;
 RETURN QUERY SELECT openpc.discovery_certificate_recovery_source(p_enrollment,p_case);
END $$;
REVOKE ALL ON FUNCTION openpc.lock_discovery_certificate_recovery_source(uuid,uuid) FROM PUBLIC;

DROP POLICY IF EXISTS discovery_recovery_target_read ON control.runtime_target;
CREATE POLICY discovery_recovery_target_read ON control.runtime_target FOR SELECT TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) and openpc.matches_privacy(privacy_domain_id)
  and exists(select 1 from control.platform_recovery_enrollment e where e.participant_id=runtime_target.participant_id
    and e.privacy_domain_id=runtime_target.privacy_domain_id and e.state='ACTIVE'
    and e.document->>'schema'='pc.identity.discovery-certificate-recovery-enrollment'
    and e.document#>>'{certificateRecovery,targetId}'=runtime_target.runtime_target_id::text
    and openpc.platform_recovery_installation_source_current(e.enrollment_id)));

-- Definer source predicates retain FORCE RLS and exact purpose/scoped reads.
DROP POLICY IF EXISTS discovery_recovery_case_source_read ON control.platform_recovery_case;
CREATE POLICY discovery_recovery_case_source_read ON control.platform_recovery_case FOR SELECT TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) and openpc.matches_privacy(privacy_domain_id)
  and intent->>'schema'='pc.identity.discovery-certificate-recovery-intent');
DROP POLICY IF EXISTS discovery_recovery_issuance_source_read ON control.discovery_certificate_issuance;
CREATE POLICY discovery_recovery_issuance_source_read ON control.discovery_certificate_issuance FOR SELECT TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) and openpc.matches_privacy(privacy_domain_id));
DROP POLICY IF EXISTS discovery_recovery_role_source_read ON control.authority_role;
CREATE POLICY discovery_recovery_role_source_read ON control.authority_role FOR SELECT TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) and exists(select 1 from control.platform_recovery_enrollment e
  join control.platform_scope_replacement original on original.replacement_id=e.expired_replacement_id
   and original.participant_id=e.participant_id and original.privacy_domain_id=e.privacy_domain_id and original.state='COMMITTED'
  where e.participant_id=authority_role.participant_id and openpc.matches_privacy(e.privacy_domain_id) and e.state='ACTIVE'
   and e.document->>'schema'='pc.identity.discovery-certificate-recovery-enrollment'
   and openpc.platform_recovery_installation_source_current(e.enrollment_id)
   and exists(select 1 from jsonb_array_elements(original.candidate->'administrators') administrator
    where administrator->>'roleId'=authority_role.authority_role_id::text)));

CREATE OR REPLACE FUNCTION openpc.discovery_certificate_recovery_administrators_current(p_enrollment uuid,p_administrators jsonb,p_bindings jsonb)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
 SELECT coalesce(jsonb_array_length(p_administrators)=2
  and (select count(distinct a->>'principalId') from jsonb_array_elements(p_administrators) a)=2
  and NOT EXISTS(select 1 from jsonb_array_elements(p_administrators) administrator
   where NOT EXISTS(select 1 from control.platform_recovery_enrollment e
    join control.platform_scope_replacement original on original.replacement_id=e.expired_replacement_id
     and original.participant_id=e.participant_id and original.privacy_domain_id=e.privacy_domain_id and original.state='COMMITTED'
    join control.platform_envelope_scope_successor scope on scope.platform_context_id=e.platform_context_id
     and scope.platform_authority_epoch=e.root_epoch and scope.admission_digest=e.root_digest
    join lateral jsonb_array_elements(original.candidate->'administrators') declared
     on declared->>'principalId'=administrator->>'principalId'
    join control.principal principal on principal.participant_id=e.participant_id and principal.principal_id::text=declared->>'principalId'
     and principal.state='ACTIVE' and principal.kind in ('USER','PLATFORM_OPERATOR')
    join control.authority_envelope expired on expired.participant_id=e.participant_id
     and expired.authority_envelope_id::text=declared->>'envelopeId' and expired.state='ACTIVE'
     and expired.platform_context_id=e.platform_context_id and expired.platform_authority_epoch=e.root_epoch
     and expired.valid_until<=clock_timestamp()
    join control.assignment assignment on assignment.participant_id=e.participant_id
     and assignment.assignment_id::text=declared->>'assignmentId' and assignment.authority_envelope_id=expired.authority_envelope_id
     and assignment.principal_id=principal.principal_id and assignment.state='ACTIVE' and upper(assignment.valid_during)<=clock_timestamp()
    join control.authority_role role on role.participant_id=e.participant_id and role.authority_role_id::text=declared->>'roleId'
     and role.state='ACTIVE' and role.row_version::text=declared->>'expectedRoleRevision'
    where e.enrollment_id=p_enrollment and openpc.matches_participant(e.participant_id) and openpc.matches_privacy(e.privacy_domain_id)
     and administrator->>'principalId' IN (e.document#>>'{administratorPrincipalIds,0}',e.document#>>'{administratorPrincipalIds,1}')
     and administrator->>'roleId'=declared->>'roleId' and administrator->>'roleRevision'=role.row_version::text
     and administrator->>'roleDigest'=declared->>'roleDigest'
     and administrator->>'roleDigest'='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
       'domain','pc.identity.envelope-role-binding.v1','participantId',e.participant_id::text,'role',jsonb_build_object(
        'roleId',role.role_id,'version',role.row_version::text,'actions',role.action_intent_ids,'origin',role.origin,
        'createdByPrincipalId',role.created_by_principal_id::text,'creatorParticipantId',role.creator_participant_id::text,
        'bootstrapMandateId',role.bootstrap_mandate_id::text,'bootstrapPlatformParticipantId',role.bootstrap_platform_participant_id::text))),'UTF8')),'hex')
     and role.action_intent_ids @> ARRAY['ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1',
      'ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1',
      'ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1']::text[]
     and (original.candidate#>'{successorScope,administration,actionIntentIds}') @> to_jsonb(ARRAY['ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1',
      'ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1',
      'ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1']::text[])
     and (declared#>>'{usable,validUntilNs}')::numeric<=floor(extract(epoch from clock_timestamp())*1000000000)
     and (declared#>>'{grantable,validUntilNs}')::numeric<=floor(extract(epoch from clock_timestamp())*1000000000)
     and administrator->'riskClasses'=(select jsonb_agg(risk.value order by risk.ordinality)
      from jsonb_array_elements(declared#>'{usable,administration,riskClasses}') with ordinality risk(value,ordinality)
      where (original.candidate#>'{successorScope,administration,riskClasses}') @> jsonb_build_array(risk.value))
     and jsonb_array_length(administrator->'riskClasses')>0
     and ((p_bindings is null and principal.authority_epoch::text=administrator->>'principalEpoch')
      or (jsonb_array_length(p_bindings)=2 and principal.authority_epoch=(administrator->>'principalEpoch')::numeric+1
       and exists(select 1 from jsonb_array_elements(p_bindings) binding
        where binding->>'principalId'=principal.principal_id::text and binding->>'principalEpoch'=principal.authority_epoch::text)))))
 ,false)
$$;
REVOKE ALL ON FUNCTION openpc.discovery_certificate_recovery_administrators_current(uuid,jsonb,jsonb) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.discovery_certificate_recovery_binding_current(p_intent jsonb,p_privacy uuid,p_binding jsonb,p_activated timestamptz,p_until timestamptz)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
 SELECT coalesce(EXISTS(select 1 from jsonb_array_elements(p_intent->'administrators') administrator
  join control.authority_role role on role.participant_id=openpc.current_participant_id()
   and role.authority_role_id::text=administrator->>'roleId' and role.state='ACTIVE'
   and role.row_version::text=administrator->>'roleRevision'
  where p_binding->>'principalId'=administrator->>'principalId'
   and (p_binding->>'principalEpoch')::numeric=(administrator->>'principalEpoch')::numeric+1
   and (p_binding#>>'{permissions,validFrom}')::timestamptz=p_activated
   and (p_binding#>>'{permissions,validUntil}')::timestamptz=p_until
   and p_binding->'permissions'=jsonb_build_object(
    'roleId',role.role_id,'validFrom',p_binding#>>'{permissions,validFrom}','validUntil',p_binding#>>'{permissions,validUntil}',
    'riskClasses',administrator->'riskClasses','privacyDomainIds',jsonb_build_array(p_privacy::text),
    'capabilityIds','[]'::jsonb,'makerCheckerRequired',true,'stepUpRequired',true,'onwardDelegationDepth',0,
    'actionIntentIds',jsonb_build_array('ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1',
     'ACT-IDENTITY_CREATE_SESSION-V1','ACT-IDENTITY_DELETE_SESSION-V1','ACT-IDENTITY_UPDATE_STEP_UP-V1','ACT-OPERATIONS_READ_OPERATION-V1',
     'ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','ACT-POLICY_APPROVE_REQUEST-V1','ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'),
    'resourceIds',(select jsonb_agg(resource order by resource collate "C") from (select distinct unnest(ARRAY[
     p_intent#>>'{certificateRecovery,targetId}',p_intent#>>'{certificateRecovery,workloadPrincipalId}',
     p_intent#>>'{certificateRecovery,predecessorCredentialId}',p_intent#>>'{certificateRecovery,successorCredentialId}',
     administrator->>'principalId','urn:openpc:self-session:'||(administrator->>'principalId')]) resource) resources)))
 ,false)
$$;
REVOKE ALL ON FUNCTION openpc.discovery_certificate_recovery_binding_current(jsonb,uuid,jsonb,timestamptz,timestamptz) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.guard_discovery_certificate_recovery_case()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control AS $$
DECLARE source control.platform_recovery_enrollment;
BEGIN
 IF NEW.intent->>'schema'<>'pc.identity.discovery-certificate-recovery-intent' THEN RETURN NEW; END IF;
 SELECT * INTO source FROM control.platform_recovery_enrollment e WHERE e.enrollment_id=NEW.enrollment_id
  and e.participant_id=NEW.participant_id and e.privacy_domain_id=NEW.privacy_domain_id;
 IF NOT FOUND or source.document->>'schema' IS DISTINCT FROM 'pc.identity.discovery-certificate-recovery-enrollment'
  or NEW.intent->'certificateRecovery' IS DISTINCT FROM source.document->'certificateRecovery'
  or NEW.intent-ARRAY['schema','schemaVersion','recoveryId','enrollmentId','enrollmentRevision','enrollmentDigest',
    'certificateRecovery','administrators','validFrom','validUntil','lifetimes']<>'{}'::jsonb
  or NOT (NEW.intent ?& ARRAY['certificateRecovery','administrators','lifetimes'])
  or NEW.planned_record_ids<>'[]'::jsonb THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-RECOVERY'; END IF;
 IF NEW.state IN ('DRAFT','REQUESTED','ACTIVE') and (NOT openpc.discovery_certificate_recovery_current(NEW.enrollment_id,null)
  or NOT openpc.discovery_certificate_recovery_administrators_current(NEW.enrollment_id,NEW.intent->'administrators',
   case when NEW.state='ACTIVE' then NEW.lease_bindings else null end)) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-RECOVERY'; END IF;
 IF NEW.state='ACTIVE' and (jsonb_array_length(NEW.lease_bindings)<>2
  or (select count(distinct binding->>'principalId') from jsonb_array_elements(NEW.lease_bindings) binding)<>2
  or EXISTS(select 1 from jsonb_array_elements(NEW.lease_bindings) binding where NOT
    openpc.discovery_certificate_recovery_binding_current(NEW.intent,NEW.privacy_domain_id,binding,NEW.activated_at,NEW.valid_until))) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-RECOVERY'; END IF;
 IF NEW.state='COMPLETED' and (NEW.completion_operation_id IS DISTINCT FROM openpc.current_operation_id()
  or NOT EXISTS(select 1 from control.discovery_certificate_issuance issuance where issuance.participant_id=NEW.participant_id
   and issuance.privacy_domain_id=NEW.privacy_domain_id and issuance.recovery_id=NEW.recovery_id and issuance.state='COMMITTED'
   and issuance.committed_operation_id=NEW.completion_operation_id
   and NEW.completion_result=jsonb_build_object('issuanceId',issuance.issuance_id::text,'operationId',issuance.committed_operation_id::text,
    'predecessorCredentialId',issuance.predecessor_credential_id::text,'successorCredentialId',issuance.successor_credential_id::text,
    'certificateFingerprint','sha256:'||encode(issuance.certificate_fingerprint,'hex')))) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-RECOVERY'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS platform_recovery_discovery_case_guard ON control.platform_recovery_case;
CREATE TRIGGER platform_recovery_discovery_case_guard BEFORE INSERT OR UPDATE ON control.platform_recovery_case
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_discovery_certificate_recovery_case();

CREATE OR REPLACE FUNCTION openpc.guard_discovery_certificate_issuance()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control AS $$
DECLARE intent jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUANCE'; END IF;
 SELECT c.intent INTO intent FROM control.platform_recovery_case c WHERE c.recovery_id=NEW.recovery_id
  and c.participant_id=NEW.participant_id and c.privacy_domain_id=NEW.privacy_domain_id;
 IF intent IS NULL or intent->>'schema'<>'pc.identity.discovery-certificate-recovery-intent'
  or NEW.request_digest<>sha256(convert_to(openpc.signing_canonical_json(NEW.request),'UTF8'))
  or NEW.predecessor_credential_id::text IS DISTINCT FROM intent#>>'{certificateRecovery,predecessorCredentialId}'
  or NEW.successor_credential_id::text IS DISTINCT FROM intent#>>'{certificateRecovery,successorCredentialId}'
  or NEW.request IS DISTINCT FROM jsonb_build_object('credentialId',NEW.successor_credential_id::text,
   'participantId',NEW.participant_id::text,'principalId',intent#>>'{certificateRecovery,workloadPrincipalId}',
   'workloadId','urn:openpc:workload:'||(intent#>>'{certificateRecovery,targetId}'),
   'publicKeySpkiDer',intent#>>'{certificateRecovery,successorPublicKeySpkiDer}')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUANCE'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'PREPARED' or NEW.row_version<>1 or NOT EXISTS(select 1 from control.mutation_candidate candidate
    join control.approval_request approval on approval.participant_id=candidate.participant_id
     and approval.privacy_domain_id=candidate.privacy_domain_id and approval.subject_id=candidate.mutation_candidate_id
     and approval.subject_digest=candidate.candidate_digest and approval.subject_version=candidate.expected_revision
     and approval.maker_principal_id=candidate.maker_principal_id and approval.state='APPROVED'
     and approval.expires_at>clock_timestamp() and approval.approval_request_id=NEW.approval_request_id
    join control.authority_envelope envelope on envelope.participant_id=candidate.participant_id
     and envelope.authority_envelope_id=candidate.maker_authority_envelope_id and envelope.recovery_case_id=NEW.recovery_id
     and envelope.representation='RECOVERY_V1' and openpc.platform_recovery_envelope_current(envelope.authority_envelope_id)
    where candidate.participant_id=NEW.participant_id and candidate.privacy_domain_id=NEW.privacy_domain_id
     and candidate.mutation_candidate_id=NEW.mutation_candidate_id and candidate.candidate_digest=NEW.candidate_digest
     and candidate.state='APPROVED' and candidate.expires_at>clock_timestamp()
     and candidate.catalog_operation_id='ID-OP-WORKLOAD-ROTATE'
     and candidate.resource_id=NEW.predecessor_credential_id
     and candidate.expected_revision=(intent#>>'{certificateRecovery,predecessorRevision}')::numeric
     and candidate.candidate_document=jsonb_build_object('replacedCredentialId',NEW.predecessor_credential_id::text,
       'credentialId',NEW.successor_credential_id::text,'publicKeySpkiDer',intent#>>'{certificateRecovery,successorPublicKeySpkiDer}'))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUANCE'; END IF;
 ELSE
  IF NEW.row_version<>OLD.row_version+1 or NEW.updated_at<=OLD.updated_at
   or (to_jsonb(NEW)-ARRAY['state','row_version','updated_at','certificate_der','certificate_fingerprint','failure_code','committed_operation_id'])
    IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','row_version','updated_at','certificate_der','certificate_fingerprint','failure_code','committed_operation_id'])
   or NOT ((OLD.state='PREPARED' and NEW.state IN ('ISSUING','REJECTED'))
     or (OLD.state='ISSUING' and NEW.state IN ('OBSERVED','AMBIGUOUS','REJECTED'))
     or (OLD.state='AMBIGUOUS' and NEW.state='ISSUING' and OLD.replay_profile='IMMUTABLE_REQUEST_RESPONSE')
     or (OLD.state='OBSERVED' and NEW.state='COMMITTED'))
   or (OLD.state='OBSERVED' and (NEW.certificate_der,NEW.certificate_fingerprint) IS DISTINCT FROM (OLD.certificate_der,OLD.certificate_fingerprint))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUANCE'; END IF;
 END IF;
 IF NEW.state='COMMITTED' and (NEW.committed_operation_id IS DISTINCT FROM openpc.current_operation_id()
  or NOT EXISTS(select 1 from control.credential successor join control.credential predecessor
    on predecessor.participant_id=successor.participant_id and predecessor.credential_id=NEW.predecessor_credential_id
   where successor.participant_id=NEW.participant_id and successor.credential_id=NEW.successor_credential_id
    and successor.rotated_from_credential_id=predecessor.credential_id and predecessor.state='REVOKED'
    and successor.state='ACTIVE' and successor.kind='WORKLOAD_MTLS' and successor.certificate_der=NEW.certificate_der
    and successor.secret_fingerprint=NEW.certificate_fingerprint)) THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUANCE'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS discovery_certificate_issuance_guard ON control.discovery_certificate_issuance;
CREATE TRIGGER discovery_certificate_issuance_guard BEFORE INSERT OR UPDATE OR DELETE ON control.discovery_certificate_issuance
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_discovery_certificate_issuance();

CREATE OR REPLACE FUNCTION openpc.platform_recovery_envelope_current(p_envelope uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
 SELECT EXISTS(SELECT 1 FROM control.authority_envelope e
  JOIN control.platform_recovery_case c ON c.recovery_id=e.recovery_case_id AND c.participant_id=e.participant_id
  JOIN control.platform_recovery_enrollment source ON source.enrollment_id=c.enrollment_id
   AND source.participant_id=c.participant_id AND source.privacy_domain_id=c.privacy_domain_id
  JOIN control.platform_context root ON root.platform_context_id=source.platform_context_id
  JOIN control.platform_envelope_scope_successor scope ON scope.platform_context_id=root.platform_context_id
   AND scope.platform_authority_epoch=root.authority_epoch
  JOIN LATERAL jsonb_array_elements(c.lease_bindings) binding ON binding->>'envelopeId'=e.authority_envelope_id::text
  JOIN control.principal recipient ON recipient.participant_id=e.participant_id AND recipient.principal_id=e.principal_id
  WHERE e.authority_envelope_id=p_envelope AND e.representation='RECOVERY_V1' AND e.state='ACTIVE'
   AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(c.privacy_domain_id)
   AND e.valid_from<=clock_timestamp() AND e.valid_until>clock_timestamp() AND cardinality(e.runtime_capability_ids)=0
   AND (NOT (c.intent ? 'supersession') OR openpc.platform_recovery_supersession_current(c.participant_id,c.enrollment_id,c.intent->'supersession',c.intent->'preparation'))
   AND ((c.intent->>'schema'='pc.identity.platform-recovery-intent' AND source.document->>'schema'='pc.identity.platform-recovery-enrollment')
    OR (c.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent'
     AND source.document->>'schema'='pc.identity.discovery-certificate-recovery-enrollment'
     AND openpc.discovery_certificate_recovery_current(c.enrollment_id,c.recovery_id) AND openpc.discovery_certificate_recovery_administrators_current(c.enrollment_id,c.intent->'administrators',c.lease_bindings)))
   AND c.state='ACTIVE' AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp()
   AND (source.document->>'assurance'<>'LOCAL_QA_VIRTUAL_AUTHENTICATOR' OR current_setting('openpc.local_qa_runtime',true)='1')
   AND (coalesce(c.intent#>>'{lifetimes,profile}','C17')<>'LOCAL_QA' OR (source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR' AND current_setting('openpc.local_qa_runtime',true)='1'))
   AND source.state='ACTIVE' AND source.row_version=c.enrollment_revision AND source.document_digest=c.enrollment_digest
   AND source.valid_from<=clock_timestamp() AND source.valid_until>clock_timestamp()
   AND root.state='ACTIVE' AND root.authority_epoch=source.root_epoch AND root.row_version=source.root_revision
   AND root.owner_participant_id=e.participant_id AND scope.admission_digest=source.root_digest
   AND e.platform_context_id=root.platform_context_id AND e.platform_authority_epoch=root.authority_epoch
   AND recipient.state='ACTIVE' AND recipient.authority_epoch::text=binding->>'principalEpoch'
   AND recipient.principal_id::text=binding->>'principalId'
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(jsonb_build_array(source.document->'recoveryPrincipal')||(source.document->'custodians')) signer
    WHERE NOT EXISTS(SELECT 1 FROM control.principal p JOIN control.credential credential
      ON credential.participant_id=p.participant_id AND credential.principal_id=p.principal_id
     WHERE p.participant_id=e.participant_id AND p.principal_id::text=signer->>'principalId' AND p.state='ACTIVE'
      AND p.authority_epoch::text=signer->>'principalEpoch' AND credential.credential_id::text=signer->>'credentialId'
      AND credential.credential_epoch::text=signer->>'credentialEpoch' AND credential.kind='WEBAUTHN' AND credential.state='ACTIVE'
      AND credential.valid_from<=clock_timestamp() AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
      AND (source.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR' OR EXISTS(SELECT 1 FROM control.hardware_authenticator hardware
       WHERE hardware.participant_id=p.participant_id AND hardware.principal_id=p.principal_id AND hardware.credential_id=credential.credential_id))))
 )
$$;

CREATE OR REPLACE FUNCTION openpc.guard_platform_recovery_envelope()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control AS $$
DECLARE recovery control.platform_recovery_case; source control.platform_recovery_enrollment; binding jsonb;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.representation='RECOVERY_V1' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
  RETURN OLD;
 END IF;
 IF NEW.representation<>'RECOVERY_V1' THEN RETURN NEW; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 SELECT * INTO recovery FROM control.platform_recovery_case c WHERE c.recovery_id=NEW.recovery_case_id
  AND c.participant_id=NEW.participant_id AND c.state='ACTIVE' AND c.valid_until>clock_timestamp();
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 SELECT * INTO source FROM control.platform_recovery_enrollment s WHERE s.enrollment_id=recovery.enrollment_id
  AND s.participant_id=recovery.participant_id AND s.privacy_domain_id=recovery.privacy_domain_id AND s.state='ACTIVE'
  AND s.row_version=recovery.enrollment_revision AND s.document_digest=recovery.enrollment_digest;
 SELECT value INTO binding FROM jsonb_array_elements(recovery.lease_bindings) a(value)
  WHERE value->>'envelopeId'=NEW.authority_envelope_id::text;
 IF source.enrollment_id IS NULL OR binding IS NULL OR NEW.state<>'ACTIVE' OR NEW.row_version<>1
  OR NEW.authority_epoch<>1 OR NEW.delegation_epoch<>0
  OR NEW.last_mutation_operation_id IS DISTINCT FROM recovery.activation_operation_id
  OR NEW.last_mutation_operation_id IS DISTINCT FROM openpc.current_operation_id()
  OR NEW.principal_id::text IS DISTINCT FROM binding->>'principalId'
  OR NEW.maker_principal_id::text IS DISTINCT FROM source.document#>>'{recoveryPrincipal,principalId}'
  OR NEW.checker_principal_id::text IS DISTINCT FROM source.document#>>'{custodians,0,principalId}'
  OR NEW.platform_context_id IS DISTINCT FROM source.platform_context_id OR NEW.platform_authority_epoch IS DISTINCT FROM source.root_epoch
  OR NEW.valid_from IS DISTINCT FROM (binding#>>'{permissions,validFrom}')::timestamptz OR NEW.valid_until IS DISTINCT FROM recovery.valid_until
  OR NEW.semantic_cbor IS DISTINCT FROM decode(binding->>'evidenceCbor','hex')
  OR NEW.semantic_digest IS DISTINCT FROM decode(binding->>'evidenceDigest','hex') OR NEW.semantic_digest<>sha256(NEW.semantic_cbor)
  OR NEW.cose_sign1 IS DISTINCT FROM decode(binding->>'coseSign1','hex') OR octet_length(NEW.cose_sign1)=0
  OR to_jsonb(NEW.privacy_domain_ids) IS DISTINCT FROM binding#>'{permissions,privacyDomainIds}'
  OR to_jsonb(NEW.action_intent_ids) IS DISTINCT FROM binding#>'{permissions,actionIntentIds}'
  OR to_jsonb(NEW.resource_ids) IS DISTINCT FROM binding#>'{permissions,resourceIds}'
  OR to_jsonb(NEW.risk_classes) IS DISTINCT FROM binding#>'{permissions,riskClasses}'
  OR cardinality(NEW.runtime_capability_ids)<>0 OR '*'=ANY(NEW.resource_ids)
  OR NOT NEW.maker_checker_required OR NOT NEW.step_up_required OR NEW.onward_delegation_depth<>0 THEN
  RAISE EXCEPTION 'PC-AUTH-0005-PLATFORM-RECOVERY'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS authority_envelope_recovery_guard ON control.authority_envelope;
CREATE TRIGGER authority_envelope_recovery_guard BEFORE INSERT OR UPDATE OR DELETE ON control.authority_envelope
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_platform_recovery_envelope();

CREATE OR REPLACE FUNCTION openpc.administration_resource_permits(
 resources text[],target text,action text,participant uuid,principal uuid,authenticated_session uuid,selected_envelope uuid)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE selected control.authority_envelope;
BEGIN
 SELECT * INTO selected FROM control.authority_envelope e WHERE e.participant_id=participant AND e.authority_envelope_id=selected_envelope;
 IF NOT FOUND THEN RETURN false; END IF;
 IF selected.representation<>'RECOVERY_V1' THEN
  RETURN openpc.administration_resource_permits(resources,target,action,participant,principal,authenticated_session);
 END IF;
 IF selected.principal_id IS DISTINCT FROM principal OR NOT (action=ANY(selected.action_intent_ids))
  OR NOT (resources<@selected.resource_ids) OR NOT openpc.platform_recovery_envelope_current(selected_envelope) THEN RETURN false; END IF;
 IF openpc.administration_resource_permits(resources,target,action,participant,principal,authenticated_session) THEN RETURN true; END IF;
 IF action IN ('ACT-POLICY_APPROVE_REQUEST-V1','ACT-APPROVAL_REQUESTS_READ_RESOURCE-V1','ACT-OPERATIONS_READ_OPERATION-V1') THEN
  RETURN EXISTS(SELECT 1 FROM control.mutation_candidate candidate
   JOIN control.authority_envelope maker ON maker.authority_envelope_id=candidate.maker_authority_envelope_id AND maker.participant_id=candidate.participant_id
   LEFT JOIN control.approval_request approval ON approval.participant_id=candidate.participant_id AND approval.privacy_domain_id=candidate.privacy_domain_id
    AND approval.subject_type='CONFIGURATION_CANDIDATE' AND approval.subject_id=candidate.mutation_candidate_id
    AND approval.subject_digest=candidate.candidate_digest AND approval.subject_version=candidate.expected_revision
    AND approval.maker_principal_id=candidate.maker_principal_id
   WHERE candidate.participant_id=participant AND openpc.matches_privacy(candidate.privacy_domain_id)
    AND maker.representation='RECOVERY_V1' AND maker.recovery_case_id=selected.recovery_case_id
    AND ((candidate.catalog_operation_id IN ('ID-OP-PLATFORM-SCOPE-PREPARE','ID-OP-PLATFORM-SCOPE-COMMIT',
      'ID-OP-ENVELOPE-CREATE','ID-OP-ENVELOPE-ACTIVATE','ID-OP-ASSIGNMENT-CREATE')
      AND EXISTS(SELECT 1 FROM control.platform_recovery_case c WHERE c.recovery_id=selected.recovery_case_id
       AND c.participant_id=participant AND c.intent->>'schema'='pc.identity.platform-recovery-intent'))
     OR (candidate.catalog_operation_id='ID-OP-WORKLOAD-ROTATE'
      AND EXISTS(SELECT 1 FROM control.platform_recovery_case c WHERE c.recovery_id=selected.recovery_case_id
       AND c.participant_id=participant AND c.intent->>'schema'='pc.identity.discovery-certificate-recovery-intent'
       AND candidate.resource_id::text=c.intent#>>'{certificateRecovery,predecessorCredentialId}'
       AND candidate.expected_revision=(c.intent#>>'{certificateRecovery,predecessorRevision}')::numeric
       AND candidate.candidate_document=jsonb_build_object('replacedCredentialId',c.intent#>>'{certificateRecovery,predecessorCredentialId}',
        'credentialId',c.intent#>>'{certificateRecovery,successorCredentialId}',
        'publicKeySpkiDer',c.intent#>>'{certificateRecovery,successorPublicKeySpkiDer}'))))
    AND candidate.resource_id::text=ANY(resources)
    AND ((action='ACT-OPERATIONS_READ_OPERATION-V1' AND target=candidate.consumed_operation_id::text)
      OR (action<>'ACT-OPERATIONS_READ_OPERATION-V1' AND target=approval.approval_request_id::text)))
   OR EXISTS(SELECT 1 FROM control.identity_envelope_proposal proposal
    JOIN control.authority_envelope maker ON maker.authority_envelope_id::text=proposal.issuer_authority#>>'{binding,authorityEnvelopeId}'
     AND maker.participant_id=proposal.participant_id AND maker.recovery_case_id=selected.recovery_case_id
    JOIN control.platform_recovery_case c ON c.participant_id=maker.participant_id AND c.recovery_id=maker.recovery_case_id
     AND c.intent->>'schema'='pc.identity.platform-recovery-intent'
    WHERE proposal.participant_id=participant AND openpc.matches_privacy(proposal.privacy_domain_id)
     AND proposal.envelope_id::text=ANY(resources) AND action<>'ACT-OPERATIONS_READ_OPERATION-V1'
     AND proposal.submission_approval_id::text=target);
 END IF;
 RETURN false;
END $$;

CREATE OR REPLACE FUNCTION openpc.guard_discovery_certificate_issuer_attempt()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control AS $$
DECLARE issuance control.discovery_certificate_issuance;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 SELECT * INTO issuance FROM control.discovery_certificate_issuance i WHERE i.issuance_id=NEW.issuance_id
  and i.participant_id=NEW.participant_id and i.privacy_domain_id=NEW.privacy_domain_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'ISSUING' or NEW.row_version<>1 or NEW.preparation_operation_id IS DISTINCT FROM openpc.current_operation_id()
   or NEW.sequence<>(select coalesce(max(a.sequence),0)+1 from control.discovery_certificate_issuer_attempt a
    where a.participant_id=NEW.participant_id and a.privacy_domain_id=NEW.privacy_domain_id and a.issuance_id=NEW.issuance_id)
   or NEW.sequence>10 or EXISTS(select 1 from control.discovery_certificate_issuer_attempt a
    where a.participant_id=NEW.participant_id and a.privacy_domain_id=NEW.privacy_domain_id and a.issuance_id=NEW.issuance_id and a.state='ISSUING')
   or NOT ((NEW.sequence=1 and issuance.state='PREPARED')
     or (NEW.sequence>1 and issuance.state='AMBIGUOUS' and issuance.replay_profile='IMMUTABLE_REQUEST_RESPONSE'
       and current_setting('openpc.local_qa_runtime',true)='1'))
   or NOT EXISTS(select 1 from control.mutation_candidate candidate
    join control.approval_request approval on approval.participant_id=candidate.participant_id
     and approval.privacy_domain_id=candidate.privacy_domain_id and approval.subject_id=candidate.mutation_candidate_id
     and approval.subject_digest=candidate.candidate_digest and approval.subject_version=candidate.expected_revision
     and approval.maker_principal_id=candidate.maker_principal_id and approval.approval_request_id=issuance.approval_request_id
     and approval.subject_type='CONFIGURATION_CANDIDATE' and approval.state='APPROVED' and approval.expires_at>clock_timestamp()
    join control.authority_envelope maker on maker.participant_id=candidate.participant_id
     and maker.authority_envelope_id=candidate.maker_authority_envelope_id and maker.representation='RECOVERY_V1'
     and maker.recovery_case_id=issuance.recovery_id and openpc.platform_recovery_envelope_current(maker.authority_envelope_id)
    join control.platform_recovery_case recovery on recovery.participant_id=maker.participant_id
     and recovery.recovery_id=maker.recovery_case_id and recovery.privacy_domain_id=candidate.privacy_domain_id and recovery.state='ACTIVE'
    join control.session session on session.participant_id=candidate.participant_id and session.session_id=candidate.maker_session_id
     and session.principal_id=candidate.maker_principal_id and session.session_epoch=candidate.maker_session_epoch
     and session.authority_epoch=candidate.maker_principal_epoch and session.participant_epoch=candidate.maker_participant_epoch
     and session.context_mode='PLATFORM' and session.privacy_domain_id is null and session.state='ACTIVE'
     and session.idle_expires_at>clock_timestamp() and session.absolute_expires_at>clock_timestamp()
    join control.approval_decision_record decision on decision.participant_id=approval.participant_id
     and decision.approval_request_id=approval.approval_request_id and decision.decision='APPROVE'
     and decision.approver_principal_id<>candidate.maker_principal_id and decision.candidate_digest=candidate.candidate_digest
     and decision.aggregate_version=candidate.expected_revision and decision.evidence_cbor=NEW.authorization_evidence_cbor
     and decision.cose_sign1=NEW.authorization_cose
    join control.authority_envelope checker on checker.participant_id=decision.participant_id
     and checker.authority_envelope_id=decision.approver_authority_envelope_id and checker.representation='RECOVERY_V1'
     and checker.recovery_case_id=recovery.recovery_id and openpc.platform_recovery_envelope_current(checker.authority_envelope_id)
    join control.mfa_challenge challenge on challenge.participant_id=candidate.participant_id
     and challenge.principal_id=candidate.maker_principal_id and challenge.session_id=candidate.maker_session_id
     and challenge.action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' and challenge.resource_digest=candidate.candidate_digest
     and challenge.consumed_at>clock_timestamp()-interval '5 minutes' and challenge.used_at is null
    join control.mutation_evidence verification on verification.participant_id=challenge.participant_id
     and verification.privacy_domain_id=candidate.privacy_domain_id and verification.principal_id=candidate.maker_principal_id
     and verification.mfa_challenge_id=challenge.mfa_challenge_id and verification.catalog_operation_id='ID-OP-WEBAUTHN-VERIFY'
     and verification.aggregate_type='webauthn-verification' and verification.aggregate_id=challenge.session_id
     and verification.webauthn_assertion_binding_digest=NEW.webauthn_assertion_binding_digest
    join control.idempotency_record verified on verified.participant_id=verification.participant_id
     and verified.privacy_domain_id=verification.privacy_domain_id and verified.operation_id=verification.operation_id
     and verified.catalog_operation_id=verification.catalog_operation_id and verified.input_digest=verification.candidate_digest
     and verified.webauthn_assertion_binding_digest=verification.webauthn_assertion_binding_digest and verified.terminal_state='COMMITTED'
    join control.outbox_event event on event.participant_id=verification.participant_id and event.privacy_domain_id=verification.privacy_domain_id
     and event.aggregate_type=verification.aggregate_type and event.aggregate_id=verification.aggregate_id
     and event.event_type='openpc.identity.webauthn-verification.mutation.committed.v1'
     and event.webauthn_assertion_binding_digest=verification.webauthn_assertion_binding_digest
     and event.payload_cbor=verification.evidence_cbor and event.payload_digest=verification.evidence_digest and event.cose_sign1=verification.cose_sign1
    where candidate.participant_id=issuance.participant_id and candidate.privacy_domain_id=issuance.privacy_domain_id
     and candidate.mutation_candidate_id=issuance.mutation_candidate_id and candidate.state='APPROVED' and candidate.expires_at>clock_timestamp()
     and candidate.candidate_digest=issuance.candidate_digest and candidate.catalog_operation_id='ID-OP-WORKLOAD-ROTATE'
     and candidate.idempotency_key=NEW.idempotency_key and candidate.maker_principal_id=NEW.maker_principal_id
     and candidate.maker_session_id=NEW.maker_session_id and NEW.started_at<=clock_timestamp() and NEW.deadline>clock_timestamp()
     and NEW.deadline<=least(recovery.valid_until,approval.expires_at,candidate.expires_at,challenge.consumed_at+interval '5 minutes')
     and (issuance.replay_profile<>'IMMUTABLE_REQUEST_RESPONSE' or (current_setting('openpc.local_qa_runtime',true)='1'
      and exists(select 1 from control.platform_recovery_enrollment enrollment where enrollment.enrollment_id=recovery.enrollment_id
       and enrollment.participant_id=recovery.participant_id and enrollment.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR'))))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 ELSE
  IF OLD.state<>'ISSUING' or NEW.state NOT IN ('AMBIGUOUS','OBSERVED','REJECTED') or NEW.row_version<>OLD.row_version+1
   or (to_jsonb(NEW)-ARRAY['state','row_version','finished_at','certificate_fingerprint','failure_code']) IS DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['state','row_version','finished_at','certificate_fingerprint','failure_code'])
   or (NEW.failure_code='CLAIM_EXPIRED' and OLD.deadline>clock_timestamp())
   or NEW.finished_at>clock_timestamp() THEN RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS discovery_certificate_issuer_attempt_guard ON control.discovery_certificate_issuer_attempt;
CREATE TRIGGER discovery_certificate_issuer_attempt_guard BEFORE INSERT OR UPDATE OR DELETE ON control.discovery_certificate_issuer_attempt
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_discovery_certificate_issuer_attempt();

CREATE OR REPLACE FUNCTION openpc.guard_discovery_certificate_issuance_attempt_phase()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control AS $$
DECLARE attempt control.discovery_certificate_issuer_attempt;
BEGIN
 IF TG_OP='INSERT' THEN RETURN NEW; END IF;
 SELECT * INTO attempt FROM control.discovery_certificate_issuer_attempt a WHERE a.participant_id=NEW.participant_id
  and a.privacy_domain_id=NEW.privacy_domain_id and a.issuance_id=NEW.issuance_id ORDER BY a.sequence DESC LIMIT 1;
 IF NEW.state IN ('ISSUING','AMBIGUOUS','OBSERVED','COMMITTED') and NOT FOUND THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 IF NEW.state='ISSUING' and (attempt.state<>'ISSUING' or attempt.deadline<=clock_timestamp()
  or attempt.preparation_operation_id IS DISTINCT FROM openpc.current_operation_id()) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 IF NEW.state='AMBIGUOUS' and (attempt.state<>'AMBIGUOUS' or NEW.failure_code IS DISTINCT FROM attempt.failure_code) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 IF NEW.state IN ('OBSERVED','COMMITTED') and (attempt.state<>'OBSERVED'
  or NEW.certificate_fingerprint IS DISTINCT FROM attempt.certificate_fingerprint) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 IF NEW.state='REJECTED' and OLD.state='ISSUING' and attempt.state<>'REJECTED' THEN
  RAISE EXCEPTION 'PC-AUTH-0005-DISCOVERY-ISSUER-ATTEMPT'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS discovery_certificate_issuance_attempt_phase_guard ON control.discovery_certificate_issuance;
CREATE TRIGGER discovery_certificate_issuance_attempt_phase_guard BEFORE INSERT OR UPDATE ON control.discovery_certificate_issuance
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_discovery_certificate_issuance_attempt_phase();


-- Fact-only live source validation. The actual fixed actor, signature, issuer,
-- credential, ceremony and effect authority remain mandatory application fences.
CREATE OR REPLACE FUNCTION openpc.identity_envelope_recovery_source_current(p_enrollment uuid)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 RETURN openpc.current_action_intent_id()='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
 AND EXISTS(SELECT 1 FROM control.identity_envelope_recovery_enrollment e
  JOIN control.identity_envelope_recovery_custody_trust t ON t.custody_trust_id=e.custody_trust_id
   AND t.participant_id=e.participant_id AND t.privacy_domain_id=e.privacy_domain_id
   AND t.platform_context_id=e.platform_context_id AND t.document_digest=e.custody_trust_digest
   AND t.state='ACTIVE' AND t.row_version=1 AND t.valid_from<=e.valid_from AND t.valid_until>=e.valid_until
  JOIN control.platform_context p ON p.platform_context_id=e.platform_context_id
   AND p.owner_participant_id=e.participant_id AND p.state='ACTIVE'
   AND p.authority_epoch::text=e.document->>'rootEpoch' AND p.row_version::text=e.document->>'rootRevision'
  JOIN control.operations_installation i ON i.participant_id=e.participant_id AND i.privacy_domain_id=e.privacy_domain_id
   AND i.environment_id=e.document->>'installationEnvironmentId' AND i.installation_digest=e.document->>'installationDigest'
   AND i.state='ACTIVE'
  WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
   AND e.state='ACTIVE' AND e.row_version=1 AND e.valid_from<=clock_timestamp() AND e.valid_until>clock_timestamp()
   AND e.document_digest=sha256(convert_to(openpc.signing_canonical_json(e.document),'UTF8'))
   AND t.document_digest=sha256(convert_to(openpc.signing_canonical_json(t.document),'UTF8'))
   AND i.installation_bytes=convert_to(openpc.signing_canonical_json(i.installation),'UTF8')
   AND i.installation_digest='sha256:'||encode(sha256(i.installation_bytes),'hex')
   AND openpc.operations_source_authentication_valid(i.installation)
   AND NOT EXISTS(SELECT 1 FROM control.platform_scope_replacement r WHERE r.platform_context_id=p.platform_context_id AND r.state='WITHDRAWING'));
END $$;
REVOKE ALL ON FUNCTION openpc.identity_envelope_recovery_source_current(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.identity_envelope_recovery_source_current(uuid) TO openpc_control_runtime,openpc_control_platform_runtime;

CREATE OR REPLACE FUNCTION openpc.lock_identity_envelope_recovery_enrollment(p_enrollment uuid)
RETURNS SETOF control.identity_envelope_recovery_enrollment LANGUAGE plpgsql VOLATILE SECURITY DEFINER
 SET search_path=pg_catalog,control SET row_security=on AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' THEN
  RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 PERFORM 1 FROM control.participant WHERE participant_id=openpc.current_participant_id() AND state='ACTIVE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 PERFORM 1 FROM control.platform_context p JOIN control.identity_envelope_recovery_enrollment e
  ON e.platform_context_id=p.platform_context_id AND e.participant_id=p.owner_participant_id
  WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
   AND p.state='ACTIVE' FOR SHARE OF p;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 PERFORM 1 FROM control.identity_envelope_recovery_custody_trust t
  JOIN control.identity_envelope_recovery_enrollment e ON e.custody_trust_id=t.custody_trust_id
   AND e.participant_id=t.participant_id AND e.privacy_domain_id=t.privacy_domain_id AND e.custody_trust_digest=t.document_digest
  WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
  FOR SHARE OF t;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 -- Declare the affected issuer write before session/credential children. The
 -- parent Participant write serializes same-Participant recovery/cutover.
 PERFORM 1 FROM control.principal issuer JOIN control.identity_envelope_recovery_enrollment e
  ON e.participant_id=issuer.participant_id AND issuer.principal_id::text=e.document->>'issuerPrincipalId'
  WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
   AND issuer.state='ACTIVE' AND issuer.kind='WORKLOAD' FOR UPDATE OF issuer;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 RETURN QUERY SELECT e.* FROM control.identity_envelope_recovery_enrollment e
  WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
  FOR SHARE;
END $$;
REVOKE ALL ON FUNCTION openpc.lock_identity_envelope_recovery_enrollment(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.lock_identity_envelope_recovery_enrollment(uuid) TO openpc_control_runtime,openpc_control_platform_runtime;

-- INVOKER and a separate statement retain FORCE RLS without recursively
-- expanding the Root's envelope policy inside identity row-lock policies.
-- This is installation read eligibility, never business or lease authority.
CREATE OR REPLACE FUNCTION openpc.identity_envelope_recovery_installation_source_current(p_enrollment uuid)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog,control SET row_security=on AS $$
BEGIN
 RETURN current_user='openpc_control_owner'
 AND pg_has_role(session_user,'openpc_control_owner','MEMBER')
 AND EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolcanlogin AND NOT rolsuper AND NOT rolbypassrls)
 AND openpc.current_action_intent_id() IN ('ACT-PARTICIPANTS_READ_RESOURCE-V1','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1')
 AND EXISTS(SELECT 1 FROM control.identity_envelope_recovery_enrollment enrollment
  JOIN control.identity_envelope_recovery_custody_trust trust ON trust.custody_trust_id=enrollment.custody_trust_id
   AND trust.participant_id=enrollment.participant_id AND trust.privacy_domain_id=enrollment.privacy_domain_id
   AND trust.platform_context_id=enrollment.platform_context_id AND trust.document_digest=enrollment.custody_trust_digest
   AND trust.state='ACTIVE' AND trust.row_version=1
   AND trust.valid_from<=enrollment.valid_from AND trust.valid_until>=enrollment.valid_until
  JOIN control.platform_context root ON root.platform_context_id=enrollment.platform_context_id
   AND root.owner_participant_id=enrollment.participant_id AND root.state='ACTIVE'
   AND root.authority_epoch::text=enrollment.document->>'rootEpoch'
   AND root.row_version::text=enrollment.document->>'rootRevision'
  JOIN (
   SELECT platform_context_id,owner_participant_id,installation_privacy_domain_id,
    platform_authority_epoch,environment_id,installation_digest,admission_digest FROM control.platform_envelope_scope
   UNION ALL
   SELECT platform_context_id,owner_participant_id,installation_privacy_domain_id,
    platform_authority_epoch,environment_id,installation_digest,admission_digest FROM control.platform_envelope_scope_successor
  ) scope ON scope.platform_context_id=root.platform_context_id AND scope.owner_participant_id=enrollment.participant_id
   AND scope.installation_privacy_domain_id=enrollment.privacy_domain_id AND scope.platform_authority_epoch=root.authority_epoch
   AND 'sha256:'||encode(scope.admission_digest,'hex')=enrollment.document->>'rootDigest'
   AND scope.environment_id=enrollment.document->>'installationEnvironmentId'
   AND scope.installation_digest=enrollment.document->>'installationDigest'
  JOIN control.operations_installation installation ON installation.participant_id=enrollment.participant_id
   AND installation.privacy_domain_id=enrollment.privacy_domain_id AND installation.environment_id=scope.environment_id
   AND installation.installation_digest=scope.installation_digest AND installation.state='ACTIVE'
  WHERE enrollment.enrollment_id=p_enrollment AND openpc.matches_participant(enrollment.participant_id)
   AND openpc.matches_privacy(enrollment.privacy_domain_id) AND enrollment.state='ACTIVE' AND enrollment.row_version=1
   AND enrollment.document->>'schema'='pc.identity.identity-envelope-recovery-enrollment'
   AND enrollment.document->>'purpose'='pc.installation.identity-envelope-repair-custody.v1'
   AND trust.document->>'purpose'=enrollment.document->>'purpose'
   AND trust.document->>'installationEnvironmentId'=scope.environment_id
   AND trust.document->>'installationDigest'=scope.installation_digest
   AND trust.document->>'profile'=enrollment.document->>'profile'
   AND enrollment.document_digest=sha256(convert_to(openpc.signing_canonical_json(enrollment.document),'UTF8'))
   AND trust.document_digest=sha256(convert_to(openpc.signing_canonical_json(trust.document),'UTF8'))
   AND installation.installation_bytes=convert_to(openpc.signing_canonical_json(installation.installation),'UTF8')
   AND installation.installation_digest='sha256:'||encode(sha256(installation.installation_bytes),'hex')
   AND openpc.operations_source_authentication_valid(installation.installation)
   AND enrollment.valid_from<=clock_timestamp() AND enrollment.valid_until>clock_timestamp()
   AND NOT EXISTS(SELECT 1 FROM control.platform_scope_replacement replacement
    WHERE replacement.platform_context_id=root.platform_context_id AND replacement.state='WITHDRAWING'));
END $$;
REVOKE ALL ON FUNCTION openpc.identity_envelope_recovery_installation_source_current(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.identity_envelope_recovery_installation_source_current(uuid) TO openpc_control_owner;

CREATE OR REPLACE FUNCTION openpc.guard_identity_envelope_recovery_installation()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control AS $$
DECLARE expected_schema text; record_id text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED' OR NEW.row_version<>OLD.row_version+1
   OR (to_jsonb(NEW)-ARRAY['state','row_version','revoked_at','revocation_reason_digest']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['state','row_version','revoked_at','revocation_reason_digest']) THEN
   RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
  NEW.revoked_at:=clock_timestamp();
  RETURN NEW;
 END IF;
 IF current_user<>'openpc_control_owner' OR NOT pg_has_role(session_user,'openpc_control_owner','MEMBER')
  OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolcanlogin AND NOT rolsuper AND NOT rolbypassrls)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY-INSTALLATION'; END IF;
 PERFORM openpc.assert_request_context(true);
 expected_schema:=CASE TG_TABLE_NAME
  WHEN 'identity_envelope_recovery_custody_trust' THEN 'pc.installation.identity-envelope-recovery-receiving-trust'
  WHEN 'identity_envelope_recovery_enrollment' THEN 'pc.identity.identity-envelope-recovery-enrollment'
  ELSE NULL END;
 record_id:=CASE TG_TABLE_NAME
  WHEN 'identity_envelope_recovery_custody_trust' THEN to_jsonb(NEW)->>'custody_trust_id'
  ELSE to_jsonb(NEW)->>'enrollment_id' END;
 IF expected_schema IS NULL OR NEW.document->>'schema' IS DISTINCT FROM expected_schema
  OR NEW.document->>'schemaVersion' IS DISTINCT FROM '1'
  OR NEW.document->>'purpose' IS DISTINCT FROM 'pc.installation.identity-envelope-repair-custody.v1'
  OR NEW.state<>'ACTIVE' OR NEW.row_version<>1
  OR NEW.document_digest<>sha256(convert_to(openpc.signing_canonical_json(NEW.document),'UTF8'))
  OR NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
  OR NEW.document->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR NEW.document->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR NEW.document->>'platformContextId' IS DISTINCT FROM NEW.platform_context_id::text
  OR (NEW.document->>'validFrom')::timestamptz IS DISTINCT FROM NEW.valid_from
  OR (NEW.document->>'validUntil')::timestamptz IS DISTINCT FROM NEW.valid_until
  OR NEW.valid_from>clock_timestamp() OR NEW.valid_until<=clock_timestamp()
  OR (CASE WHEN TG_TABLE_NAME='identity_envelope_recovery_custody_trust'
    THEN NEW.document->>'custodyTrustId' ELSE NEW.document->>'enrollmentId' END) IS DISTINCT FROM record_id
  THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY-INSTALLATION'; END IF;
 IF TG_TABLE_NAME='identity_envelope_recovery_enrollment' THEN
  IF NEW.document->>'custodyTrustId' IS DISTINCT FROM NEW.custody_trust_id::text
   OR NEW.document->>'custodyTrustDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.custody_trust_digest,'hex')
   OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_recovery_custody_trust trust
    WHERE trust.custody_trust_id=NEW.custody_trust_id AND trust.participant_id=NEW.participant_id
     AND trust.privacy_domain_id=NEW.privacy_domain_id AND trust.document_digest=NEW.custody_trust_digest
     AND trust.state='ACTIVE' AND trust.row_version=1 AND trust.valid_from<=NEW.valid_from AND trust.valid_until>=NEW.valid_until)
   THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY-CUSTODY'; END IF;
 END IF;
 NEW.created_at:=clock_timestamp();
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS identity_envelope_recovery_trust_guard ON control.identity_envelope_recovery_custody_trust;
CREATE TRIGGER identity_envelope_recovery_trust_guard BEFORE INSERT OR UPDATE OR DELETE ON control.identity_envelope_recovery_custody_trust
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_identity_envelope_recovery_installation();
DROP TRIGGER IF EXISTS identity_envelope_recovery_enrollment_guard ON control.identity_envelope_recovery_enrollment;
CREATE TRIGGER identity_envelope_recovery_enrollment_guard BEFORE INSERT OR UPDATE OR DELETE ON control.identity_envelope_recovery_enrollment
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_identity_envelope_recovery_installation();

-- Permanently preserve the dedicated recovery-principal separation, including
-- after enrollment revocation. This returns no enrollment or signing material.
CREATE OR REPLACE FUNCTION openpc.is_platform_recovery_executor(p_principal uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
 SELECT EXISTS(SELECT 1 FROM control.platform_recovery_enrollment e
   WHERE openpc.matches_participant(e.participant_id) AND e.document#>>'{recoveryPrincipal,principalId}'=p_principal::text)
 OR EXISTS(SELECT 1 FROM control.identity_envelope_recovery_enrollment e
   WHERE openpc.matches_participant(e.participant_id) AND e.document#>>'{recoveryPrincipal,principalId}'=p_principal::text)
$$;
REVOKE ALL ON FUNCTION openpc.is_platform_recovery_executor(uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.identity_envelope_recovery_old_selection_current(p_enrollment uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
 SELECT EXISTS(SELECT 1 FROM control.identity_envelope_recovery_enrollment e
  JOIN control.identity_envelope_signing_selection selection ON selection.participant_id=e.participant_id
   AND selection.privacy_domain_id=e.privacy_domain_id AND selection.environment_id=e.document#>>'{request,environmentId}'
   AND selection.signer_id=e.document#>>'{request,oldFingerprint}' AND selection.admission_version::text=e.document->>'selectionAdmissionVersion'
   AND selection.profile_digest=decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex')
  JOIN control.identity_envelope_signing_grant grant_row ON grant_row.participant_id=selection.participant_id
   AND grant_row.privacy_domain_id=selection.privacy_domain_id AND grant_row.signer_id=selection.signer_id
   AND grant_row.profile_digest=selection.profile_digest AND grant_row.signing_purpose_code=371
  JOIN control.business_signing_key key ON key.participant_id=selection.participant_id AND key.privacy_domain_id=selection.privacy_domain_id
   AND key.signer_id=selection.signer_id AND key.signing_purpose_code=371 AND key.secret_reference=e.document#>>'{request,oldReference}'
   AND key.environment_id=selection.environment_id AND key.workload_credential_id::text=e.document#>>'{request,workloadCredentialId}'
   AND 'sha256:'||encode(key.trust_digest,'hex')=e.document->>'oldTrustDigest'
  JOIN control.business_signing_key_state lifecycle ON lifecycle.participant_id=key.participant_id
   AND lifecycle.privacy_domain_id=key.privacy_domain_id AND lifecycle.signer_id=key.signer_id AND lifecycle.state='ACTIVE'
  WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
   AND NOT EXISTS(SELECT 1 FROM control.business_signing_grant receipt WHERE receipt.participant_id=key.participant_id
    AND receipt.privacy_domain_id=key.privacy_domain_id AND receipt.signer_id=key.signer_id));
$$;
REVOKE ALL ON FUNCTION openpc.identity_envelope_recovery_old_selection_current(uuid) FROM PUBLIC;
CREATE OR REPLACE FUNCTION openpc.identity_envelope_recovery_proofs_current(p_case control.platform_recovery_case,p_activation uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
 SELECT p_case.signer_repair_enrollment_id IS NOT NULL
 AND openpc.matches_participant(p_case.participant_id) AND openpc.matches_privacy(p_case.privacy_domain_id)
 AND EXISTS(SELECT 1 FROM control.identity_envelope_recovery_enrollment e
  WHERE e.enrollment_id=p_case.signer_repair_enrollment_id AND e.participant_id=p_case.participant_id
   AND e.privacy_domain_id=p_case.privacy_domain_id AND e.state='ACTIVE' AND e.row_version=p_case.enrollment_revision
   AND e.document_digest=p_case.enrollment_digest AND openpc.identity_envelope_recovery_source_current(e.enrollment_id)
   AND jsonb_array_length(e.document->'custodians')=2
   AND (SELECT count(*) FROM control.platform_recovery_proof proof WHERE proof.participant_id=e.participant_id
    AND proof.recovery_id=p_case.recovery_id)=4
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(
    jsonb_build_array(jsonb_build_object('signer',e.document->'recoveryPrincipal','phase','REQUEST'),
     jsonb_build_object('signer',e.document->'recoveryPrincipal','phase','ACTIVATE')) ||
     (SELECT jsonb_agg(jsonb_build_object('signer',custodian,'phase','APPROVE')) FROM jsonb_array_elements(e.document->'custodians') custodian)) required
    WHERE NOT EXISTS(SELECT 1 FROM control.platform_recovery_proof proof
     JOIN control.platform_recovery_challenge h ON h.participant_id=proof.participant_id AND h.recovery_id=proof.recovery_id
      AND h.challenge_id=proof.challenge_id AND h.proof_id=proof.proof_id AND h.consumed_at IS NOT NULL
     JOIN control.principal p ON p.participant_id=proof.participant_id AND p.principal_id=proof.principal_id
      AND p.state='ACTIVE' AND p.kind IN ('USER','PLATFORM_OPERATOR') AND p.authority_epoch=proof.principal_epoch
     JOIN control.credential c ON c.participant_id=p.participant_id AND c.principal_id=p.principal_id
      AND c.credential_id=proof.credential_id AND c.credential_epoch=proof.credential_epoch AND c.kind='WEBAUTHN' AND c.state='ACTIVE'
      AND c.valid_from<=clock_timestamp() AND (c.valid_until IS NULL OR c.valid_until>clock_timestamp())
     JOIN control.session s ON s.participant_id=p.participant_id AND s.principal_id=p.principal_id
      AND s.session_id=proof.session_id AND s.session_epoch=proof.session_epoch AND s.authority_epoch=p.authority_epoch
      AND s.participant_epoch=(p_case.intent->>'sourceParticipantEpoch')::numeric AND s.state='ACTIVE'
      AND s.context_mode='PLATFORM' AND s.privacy_domain_id IS NULL
      AND s.idle_expires_at>clock_timestamp() AND s.absolute_expires_at>clock_timestamp()
     WHERE proof.participant_id=p_case.participant_id AND proof.privacy_domain_id=p_case.privacy_domain_id
      AND proof.recovery_id=p_case.recovery_id AND proof.intent_digest=p_case.intent_digest
      AND proof.phase=required->>'phase' AND proof.principal_id::text=required#>>'{signer,principalId}'
      AND proof.credential_id::text=required#>>'{signer,credentialId}'
      AND proof.principal_epoch::text=required#>>'{signer,principalEpoch}' AND proof.credential_epoch::text=required#>>'{signer,credentialEpoch}'
      AND (proof.phase<>'ACTIVATE' OR proof.proof_id=p_activation)
      AND proof.verified_at>=p_case.valid_from AND proof.verified_at<=clock_timestamp()
      AND proof.verified_at>clock_timestamp()-interval '5 minutes'
      AND (e.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR' OR EXISTS(SELECT 1 FROM control.hardware_authenticator hardware
        WHERE hardware.participant_id=c.participant_id AND hardware.principal_id=c.principal_id AND hardware.credential_id=c.credential_id))))
 );
$$;
REVOKE ALL ON FUNCTION openpc.identity_envelope_recovery_proofs_current(control.platform_recovery_case,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.identity_envelope_recovery_proofs_current(control.platform_recovery_case,uuid) TO openpc_control_runtime,openpc_control_platform_runtime;

CREATE OR REPLACE FUNCTION openpc.fence_identity_envelope_recovery_issuer(p_recovery uuid,p_activation uuid)
RETURNS numeric LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
DECLARE recovery control.platform_recovery_case; enrollment control.identity_envelope_recovery_enrollment; epoch numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' OR openpc.current_operation_id() IS NULL THEN
  RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 SELECT * INTO recovery FROM control.platform_recovery_case c WHERE c.recovery_id=p_recovery
  AND openpc.matches_participant(c.participant_id) AND openpc.matches_privacy(c.privacy_domain_id);
 IF NOT FOUND OR recovery.signer_repair_enrollment_id IS NULL THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 SELECT * INTO enrollment FROM openpc.lock_identity_envelope_recovery_enrollment(recovery.signer_repair_enrollment_id);
 SELECT * INTO recovery FROM control.platform_recovery_case c WHERE c.recovery_id=p_recovery FOR UPDATE;
 IF enrollment.enrollment_id IS NULL OR recovery.state<>'REQUESTED' OR recovery.activated_at IS NOT NULL
  OR recovery.valid_from>clock_timestamp() OR recovery.valid_until<=clock_timestamp()
  OR recovery.intent_digest<>sha256(convert_to(openpc.signing_canonical_json(recovery.intent),'UTF8'))
  OR NOT coalesce(openpc.identity_envelope_recovery_proofs_current(recovery,p_activation),false)
  OR NOT openpc.identity_envelope_recovery_old_selection_current(enrollment.enrollment_id)
  OR recovery.intent->>'sourceIssuerPrincipalEpoch' IS DISTINCT FROM enrollment.document->>'issuerPrincipalEpoch'
  OR recovery.intent->>'sourceIssuerCredentialEpoch' IS DISTINCT FROM enrollment.document->>'issuerCredentialEpoch'
  OR recovery.intent->>'sourceParticipantEpoch' IS DISTINCT FROM enrollment.document->>'issuerParticipantEpoch'
  OR EXISTS(SELECT 1 FROM control.platform_recovery_case prior JOIN control.identity_envelope_recovery_enrollment original
    ON original.enrollment_id=prior.signer_repair_enrollment_id AND original.participant_id=prior.participant_id
    WHERE prior.participant_id=recovery.participant_id AND original.document->>'issuerPrincipalId'=enrollment.document->>'issuerPrincipalId'
     AND prior.recovery_id<>recovery.recovery_id AND prior.activated_at IS NOT NULL AND prior.reviewed_at IS NULL)
  OR EXISTS(SELECT 1 FROM control.signing_key_rotation rotation WHERE rotation.participant_id=enrollment.participant_id
    AND rotation.privacy_domain_id=enrollment.privacy_domain_id AND rotation.environment_id=enrollment.document#>>'{request,environmentId}'
    AND rotation.workload_credential_id::text=enrollment.document#>>'{request,workloadCredentialId}' AND rotation.state<>'COMPLETE')
  THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 PERFORM 1 FROM control.credential credential JOIN control.principal issuer
  ON issuer.participant_id=credential.participant_id AND issuer.principal_id=credential.principal_id
  JOIN control.participant participant ON participant.participant_id=issuer.participant_id
  WHERE credential.participant_id=enrollment.participant_id AND credential.credential_id::text=enrollment.document#>>'{request,workloadCredentialId}'
   AND issuer.principal_id::text=enrollment.document->>'issuerPrincipalId' AND issuer.kind='WORKLOAD' AND issuer.state='ACTIVE'
   AND issuer.authority_epoch::text=enrollment.document->>'issuerPrincipalEpoch'
   AND participant.state='ACTIVE' AND participant.authority_epoch::text=enrollment.document->>'issuerParticipantEpoch'
   AND credential.kind='WORKLOAD_MTLS' AND credential.state='ACTIVE' AND credential.credential_epoch::text=enrollment.document->>'issuerCredentialEpoch'
   AND 'sha256:'||encode(credential.public_key_digest,'hex')=enrollment.document->>'issuerCredentialPublicKeyDigest'
   AND credential.valid_from<=clock_timestamp() AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
  FOR UPDATE OF issuer FOR SHARE OF credential;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 UPDATE control.principal SET authority_epoch=authority_epoch+1,row_version=row_version+1,updated_at=clock_timestamp()
  WHERE participant_id=enrollment.participant_id AND principal_id::text=enrollment.document->>'issuerPrincipalId'
   AND state='ACTIVE' AND authority_epoch=(enrollment.document->>'issuerPrincipalEpoch')::numeric RETURNING authority_epoch INTO epoch;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005-SIGNER-RECOVERY'; END IF;
 UPDATE control.session SET state='REVOKED',revoked_at=clock_timestamp(),revoked_reason='identity-envelope-signer-recovery',
  session_epoch=session_epoch+1,row_version=row_version+1,updated_at=clock_timestamp()
  WHERE participant_id=enrollment.participant_id AND principal_id::text=enrollment.document->>'issuerPrincipalId'
   AND state IN ('ACTIVE','STEP_UP_REQUIRED');
 RETURN epoch;
END $$;
REVOKE ALL ON FUNCTION openpc.fence_identity_envelope_recovery_issuer(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.fence_identity_envelope_recovery_issuer(uuid,uuid) TO openpc_control_runtime,openpc_control_platform_runtime;

-- Validate the exact recorded post-fence issuer. Epoch drift cannot be recaptured
-- as new authority, and an unchanged proof cannot refresh a signed lifetime.
CREATE OR REPLACE FUNCTION openpc.identity_envelope_recovery_rotation_selection_current(p_enrollment uuid,p_binding jsonb)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
BEGIN
 IF openpc.identity_envelope_recovery_old_selection_current(p_enrollment) THEN RETURN true; END IF;
 RETURN EXISTS(SELECT 1 FROM control.identity_envelope_recovery_enrollment e
  JOIN control.signing_key_rotation r ON r.participant_id=e.participant_id AND r.privacy_domain_id=e.privacy_domain_id
    AND r.rotation_id::text=p_binding->>'rotationId' AND r.recovery_case_id::text=p_binding->>'recoveryId'
    AND r.old_signer_id=e.document#>>'{request,oldFingerprint}' AND r.approval_request_id IS NULL
    AND r.state IN('CUTOVER_FENCED','OBSERVING','OLD_REVOKED','OLD_RETIRED','COMPLETE')
  JOIN control.identity_envelope_rotation_step cutover ON cutover.participant_id=r.participant_id AND cutover.privacy_domain_id=r.privacy_domain_id
    AND cutover.rotation_id=r.rotation_id AND cutover.recovery_id=r.recovery_case_id AND cutover.state='COMMITTED'
    AND cutover.from_revision=5 AND cutover.from_state='VERIFIED' AND cutover.to_state='CUTOVER_FENCED'
    AND cutover.authority_binding=jsonb_build_object('kind','IDENTITY_ENVELOPE_SIGNER_RECOVERY','enrollment',e.document,'lease',p_binding)
    AND cutover.evidence_digest=sha256(cutover.evidence_cbor) AND octet_length(cutover.cose_sign1)>0
  JOIN control.identity_envelope_signing_selection selection ON selection.participant_id=r.participant_id AND selection.privacy_domain_id=r.privacy_domain_id
    AND selection.environment_id=r.environment_id AND selection.signer_id=r.new_signer_id
    AND selection.admission_version=(p_binding->>'selectionAdmissionVersion')::numeric+1
    AND selection.admission_version::text=cutover.result->>'selectionAdmissionVersion'
    AND selection.profile_digest=decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex')
  JOIN control.business_signing_key k ON k.participant_id=selection.participant_id AND k.privacy_domain_id=selection.privacy_domain_id
    AND k.signer_id=selection.signer_id AND k.signing_purpose_code=371 AND k.environment_id=selection.environment_id
    AND 'sha256:'||encode(k.trust_digest,'hex')=cutover.result->>'trustDigest'
  JOIN control.business_signing_key_state life ON life.participant_id=k.participant_id AND life.privacy_domain_id=k.privacy_domain_id
    AND life.signer_id=k.signer_id AND life.state='ACTIVE'
  WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
    AND k.workload_credential_id::text=p_binding#>>'{issuer,workloadCredentialId}'
    AND k.workload_credential_epoch::text=p_binding#>>'{issuer,workloadCredentialEpoch}'
    AND k.envelope_workload_participant_epoch::text=p_binding#>>'{issuer,workloadParticipantEpoch}'
    AND k.envelope_workload_principal_epoch::text=p_binding#>>'{issuer,workloadPrincipalEpoch}'
    AND k.valid_from_ns<=floor(extract(epoch from clock_timestamp())*1000000)*1000 AND k.valid_until_ns>floor(extract(epoch from clock_timestamp())*1000000)*1000
    AND NOT EXISTS(SELECT 1 FROM control.business_signing_grant ordinary WHERE ordinary.participant_id=k.participant_id AND ordinary.privacy_domain_id=k.privacy_domain_id AND ordinary.signer_id=k.signer_id));
END $$;
REVOKE ALL ON FUNCTION openpc.identity_envelope_recovery_rotation_selection_current(uuid,jsonb) FROM PUBLIC;
CREATE OR REPLACE FUNCTION openpc.identity_envelope_recovery_binding_current(p_enrollment uuid,p_intent jsonb,p_binding jsonb)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
 SELECT p_binding->>'schema'='pc.identity.identity-envelope-recovery-lease' AND p_binding->>'schemaVersion'='1'
  AND p_binding->>'purpose'='IDENTITY_ENVELOPE_SIGNER_REPAIR_ONLY' AND p_binding->'postReviewRequired'='true'::jsonb
  AND p_binding-ARRAY['schema','schemaVersion','purpose','recoveryId','enrollmentId','enrollmentDigest','intentDigest','rotationId',
    'creationOperationId','activationOperationId','executorPrincipalId','issuer','oldTrustDigest','selectionAdmissionVersion',
    'proofIds','proofEvidenceDigest','validFrom','validUntil','postReviewRequired']='{}'::jsonb
  AND p_binding->>'recoveryId'=p_intent->>'recoveryId' AND p_binding->>'enrollmentId'=p_intent->>'enrollmentId'
  AND p_binding->>'enrollmentDigest'=p_intent->>'enrollmentDigest'
  AND p_binding->>'intentDigest'='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p_intent),'UTF8')),'hex')
  AND p_binding->>'rotationId'=p_intent->>'rotationId' AND p_binding->>'creationOperationId'=p_intent->>'creationOperationId'
  AND p_binding->>'oldTrustDigest'=p_intent->>'oldTrustDigest' AND p_binding->>'selectionAdmissionVersion'=p_intent->>'selectionAdmissionVersion'
  AND (p_binding->>'validFrom')::timestamptz>=(p_intent->>'validFrom')::timestamptz
  AND (p_binding->>'validFrom')::timestamptz<=clock_timestamp() AND (p_binding->>'validUntil')::timestamptz>clock_timestamp()
  AND (p_binding->>'validUntil')::timestamptz<=(p_intent->>'validUntil')::timestamptz
  AND (p_binding->>'validUntil')::timestamptz<=(p_binding->>'validFrom')::timestamptz+interval '15 minutes'
  AND EXISTS(SELECT 1 FROM control.identity_envelope_recovery_enrollment e
   JOIN control.principal issuer ON issuer.participant_id=e.participant_id AND issuer.principal_id::text=e.document->>'issuerPrincipalId'
    AND issuer.state='ACTIVE' AND issuer.kind='WORKLOAD' AND issuer.authority_epoch=(p_intent->>'sourceIssuerPrincipalEpoch')::numeric+1
   JOIN control.participant participant ON participant.participant_id=e.participant_id AND participant.state='ACTIVE'
    AND participant.authority_epoch=(p_intent->>'sourceParticipantEpoch')::numeric
   JOIN control.credential credential ON credential.participant_id=e.participant_id AND credential.principal_id=issuer.principal_id
    AND credential.credential_id::text=e.document#>>'{request,workloadCredentialId}' AND credential.kind='WORKLOAD_MTLS'
    AND credential.state='ACTIVE' AND credential.credential_epoch=(p_intent->>'sourceIssuerCredentialEpoch')::numeric
    AND credential.valid_from<=clock_timestamp() AND (credential.valid_until IS NULL OR credential.valid_until>=(p_binding->>'validUntil')::timestamptz)
   WHERE e.enrollment_id=p_enrollment AND openpc.matches_participant(e.participant_id) AND openpc.matches_privacy(e.privacy_domain_id)
    AND e.enrollment_id::text=p_binding->>'enrollmentId' AND e.document_digest=decode(substr(p_binding->>'enrollmentDigest',8),'hex')
    AND e.state='ACTIVE' AND e.row_version=1 AND e.valid_until>=(p_binding->>'validUntil')::timestamptz
    AND openpc.identity_envelope_recovery_source_current(e.enrollment_id)
    AND openpc.identity_envelope_recovery_rotation_selection_current(e.enrollment_id,p_binding)
    AND p_binding->>'executorPrincipalId'=e.document#>>'{recoveryPrincipal,principalId}'
    AND p_binding->'issuer'=jsonb_build_object('participantId',e.participant_id::text,'privacyDomainId',e.privacy_domain_id::text,
      'workloadCredentialId',credential.credential_id::text,'workloadPrincipalId',issuer.principal_id::text,
      'workloadParticipantEpoch',participant.authority_epoch::text,'workloadPrincipalEpoch',issuer.authority_epoch::text,
      'workloadCredentialEpoch',credential.credential_epoch::text,'workloadPublicKeyDigest','sha256:'||encode(credential.public_key_digest,'hex'),
      'credentialValidFromNs',(floor(extract(epoch FROM credential.valid_from)*1000000)*1000)::text,
      'credentialValidUntilNs',(floor(extract(epoch FROM credential.valid_until)*1000000)*1000)::text)
    AND NOT EXISTS(SELECT 1 FROM control.session s WHERE s.participant_id=e.participant_id AND s.principal_id=issuer.principal_id
      AND s.state IN ('ACTIVE','STEP_UP_REQUIRED') AND s.authority_epoch<= (p_intent->>'sourceIssuerPrincipalEpoch')::numeric)
    AND jsonb_array_length(p_binding->'proofIds')=4
    AND p_binding->>'proofEvidenceDigest'='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
      (SELECT jsonb_agg(jsonb_build_object('proofId',proof.proof_id::text,'principalId',proof.principal_id::text,
        'principalEpoch',proof.principal_epoch::text,'credentialId',proof.credential_id::text,'credentialEpoch',proof.credential_epoch::text,
        'sessionId',proof.session_id::text,'sessionEpoch',proof.session_epoch::text,'phase',proof.phase,
        'intentDigest','sha256:'||encode(proof.intent_digest,'hex'),
        'verifiedAt',to_char(proof.verified_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
        'assertionDigest','sha256:'||encode(proof.assertion_digest,'hex')) ORDER BY names.ordinality)
       FROM jsonb_array_elements_text(p_binding->'proofIds') WITH ORDINALITY names(proof_id,ordinality)
       JOIN control.platform_recovery_proof proof ON proof.proof_id::text=names.proof_id
        AND proof.participant_id=e.participant_id AND proof.privacy_domain_id=e.privacy_domain_id
        AND proof.recovery_id::text=p_binding->>'recoveryId')),'UTF8')),'hex')
    AND (SELECT count(DISTINCT value) FROM jsonb_array_elements_text(p_binding->'proofIds'))=4
    AND (SELECT count(*) FROM control.platform_recovery_proof proof WHERE proof.participant_id=e.participant_id
      AND proof.privacy_domain_id=e.privacy_domain_id AND proof.recovery_id::text=p_binding->>'recoveryId'
      AND proof.intent_digest=decode(substr(p_binding->>'intentDigest',8),'hex'))=4
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_binding->'proofIds') supplied(proof_id)
      WHERE NOT EXISTS(SELECT 1 FROM control.platform_recovery_proof proof
       JOIN control.principal human ON human.participant_id=proof.participant_id AND human.principal_id=proof.principal_id
        AND human.state='ACTIVE' AND human.authority_epoch=proof.principal_epoch
       JOIN control.credential authenticator ON authenticator.participant_id=human.participant_id AND authenticator.principal_id=human.principal_id
        AND authenticator.credential_id=proof.credential_id AND authenticator.credential_epoch=proof.credential_epoch
        AND authenticator.state='ACTIVE' AND authenticator.kind='WEBAUTHN'
       JOIN control.session s ON s.participant_id=human.participant_id AND s.principal_id=human.principal_id AND s.session_id=proof.session_id
        AND s.authority_epoch=human.authority_epoch AND s.participant_epoch=participant.authority_epoch AND s.session_epoch=proof.session_epoch
        AND s.state='ACTIVE' AND s.context_mode='PLATFORM' AND s.privacy_domain_id IS NULL
       WHERE proof.proof_id::text=supplied.proof_id AND proof.participant_id=e.participant_id AND proof.privacy_domain_id=e.privacy_domain_id
        AND proof.recovery_id::text=p_binding->>'recoveryId' AND proof.intent_digest=decode(substr(p_binding->>'intentDigest',8),'hex')
        AND s.idle_expires_at>=(p_binding->>'validUntil')::timestamptz AND s.absolute_expires_at>=(p_binding->>'validUntil')::timestamptz
        AND authenticator.valid_from<=clock_timestamp() AND (authenticator.valid_until IS NULL OR authenticator.valid_until>=(p_binding->>'validUntil')::timestamptz)
        AND EXISTS(SELECT 1 FROM jsonb_array_elements(jsonb_build_array(e.document->'recoveryPrincipal')||e.document->'custodians') actor
          WHERE actor->>'principalId'=human.principal_id::text AND actor->>'credentialId'=authenticator.credential_id::text
           AND actor->>'principalEpoch'=human.authority_epoch::text AND actor->>'credentialEpoch'=authenticator.credential_epoch::text)
        AND (e.document->>'assurance'='LOCAL_QA_VIRTUAL_AUTHENTICATOR' OR EXISTS(SELECT 1 FROM control.hardware_authenticator hardware
          WHERE hardware.participant_id=human.participant_id AND hardware.principal_id=human.principal_id AND hardware.credential_id=authenticator.credential_id)))))
$$;
REVOKE ALL ON FUNCTION openpc.identity_envelope_recovery_binding_current(uuid,jsonb,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.identity_envelope_recovery_binding_current(uuid,jsonb,jsonb) TO openpc_control_runtime,openpc_control_platform_runtime;

CREATE OR REPLACE FUNCTION openpc.identity_envelope_recovery_lease_current(p_recovery uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
 SELECT EXISTS(SELECT 1 FROM control.platform_recovery_case c WHERE c.recovery_id=p_recovery
  AND c.state='ACTIVE' AND c.signer_repair_enrollment_id IS NOT NULL
  AND openpc.matches_participant(c.participant_id) AND openpc.matches_privacy(c.privacy_domain_id)
  AND c.activation_operation_id::text=c.lease_bindings->>'activationOperationId'
  AND c.activation_evidence_digest=sha256(c.activation_evidence_cbor) AND octet_length(c.activation_cose)>0
  AND openpc.identity_envelope_recovery_binding_current(c.signer_repair_enrollment_id,c.intent,c.lease_bindings));
$$;
REVOKE ALL ON FUNCTION openpc.identity_envelope_recovery_lease_current(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.identity_envelope_recovery_lease_current(uuid) TO openpc_control_runtime,openpc_control_platform_runtime;



CREATE OR REPLACE FUNCTION openpc.check_identity_envelope_recovery_trust_admission(p_key control.business_signing_key)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE rotation control.signing_key_rotation; step control.identity_envelope_rotation_step;
 old_key control.business_signing_key; descriptor jsonb; issuer jsonb; expected_digest bytea; proofs integer;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR p_key.signing_purpose_code<>371 OR p_key.admission_kind<>'GOVERNED'
  OR NOT openpc.matches_participant(p_key.participant_id) OR NOT openpc.matches_privacy(p_key.privacy_domain_id)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-TRUST-ADMISSION'; END IF;
 SELECT * INTO STRICT rotation FROM control.signing_key_rotation r WHERE r.participant_id=p_key.participant_id
  AND r.privacy_domain_id=p_key.privacy_domain_id AND r.recovery_case_id IS NOT NULL
  AND p_key.admission_reference='urn:openpc:resource:'||r.rotation_id::text AND r.new_signer_id=p_key.signer_id
  AND r.state='VERIFIED' AND r.revision=5 AND r.approval_request_id IS NULL;
 SELECT * INTO STRICT step FROM control.identity_envelope_rotation_step s WHERE s.operation_id=openpc.current_operation_id()
  AND s.participant_id=rotation.participant_id AND s.privacy_domain_id=rotation.privacy_domain_id
  AND s.rotation_id=rotation.rotation_id AND s.recovery_id=rotation.recovery_case_id
  AND s.from_revision=4 AND s.from_state='DISTRIBUTED' AND s.to_state='VERIFIED' AND s.state='COMMITTED';
 IF NOT coalesce(openpc.identity_envelope_rotation_step_current(step),false)
  OR step.result->>'state' IS DISTINCT FROM 'VERIFIED' OR step.result->>'admissionState' IS DISTINCT FROM 'ADMITTED'
  OR step.result->>'signerId' IS DISTINCT FROM p_key.signer_id
  OR step.result->>'trustDigest' IS DISTINCT FROM 'sha256:'||encode(p_key.trust_digest,'hex')
  OR step.evidence_digest IS DISTINCT FROM sha256(step.evidence_cbor) OR step.cose_sign1 IS NULL
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-TRUST-PROVENANCE'; END IF;
 SELECT * INTO STRICT old_key FROM control.business_signing_key k WHERE k.participant_id=rotation.participant_id
  AND k.privacy_domain_id=rotation.privacy_domain_id AND k.signer_id=rotation.old_signer_id AND k.signing_purpose_code=371;
 SELECT a.observation->'descriptor' INTO STRICT descriptor FROM control.identity_envelope_rotation_step prepared
  JOIN control.identity_envelope_rotation_attempt a USING(participant_id,privacy_domain_id,rotation_id,operation_id)
  WHERE prepared.participant_id=rotation.participant_id AND prepared.privacy_domain_id=rotation.privacy_domain_id
   AND prepared.rotation_id=rotation.rotation_id AND prepared.recovery_id=rotation.recovery_case_id
   AND prepared.state='COMMITTED' AND prepared.from_revision=2 AND prepared.to_state='PREPARED'
   AND a.slot='new' AND a.state='OBSERVED';
 issuer:=step.authority_binding#>'{lease,issuer}';
 expected_digest:=sha256(convert_to('pc.identity.envelope-key-recovery-admission.v1','UTF8')||decode('00','hex')||
  convert_to(openpc.signing_canonical_json(step.authority_binding||jsonb_build_object('issuer',issuer,
    'newFingerprint',descriptor->>'fingerprint','newReference',descriptor->>'reference','newVersion',descriptor->>'version')),'UTF8'));
 IF old_key.trust_digest<>rotation.old_trust_digest OR p_key.key_epoch<>old_key.key_epoch+1
  OR p_key.workload_credential_id<>old_key.workload_credential_id OR p_key.workload_credential_epoch<>old_key.workload_credential_epoch
  OR p_key.environment_id<>old_key.environment_id OR p_key.environment_id<>rotation.environment_id
  OR p_key.workload_credential_id::text IS DISTINCT FROM issuer->>'workloadCredentialId'
  OR p_key.workload_credential_epoch::text IS DISTINCT FROM issuer->>'workloadCredentialEpoch'
  OR p_key.envelope_workload_participant_epoch::text IS DISTINCT FROM issuer->>'workloadParticipantEpoch'
  OR p_key.envelope_workload_principal_epoch::text IS DISTINCT FROM issuer->>'workloadPrincipalEpoch'
  OR p_key.admission_digest<>expected_digest OR p_key.secret_class<>'SECRET-SIGNING-KEY'
  OR p_key.secret_reference IS DISTINCT FROM descriptor->>'reference' OR p_key.secret_version IS DISTINCT FROM descriptor->>'version'
  OR p_key.signer_id IS DISTINCT FROM descriptor->>'fingerprint' OR encode(p_key.public_key_spki_der,'hex') IS DISTINCT FROM descriptor->>'publicKeySpkiHex'
  OR p_key.valid_from_ns::text IS DISTINCT FROM descriptor->>'validFromNs' OR p_key.valid_until_ns::text IS DISTINCT FROM descriptor->>'validUntilNs'
  OR p_key.valid_from_ns>floor(extract(epoch from clock_timestamp())*1000000)*1000
  OR p_key.valid_until_ns<=floor(extract(epoch from clock_timestamp())*1000000)*1000
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-TRUST-BINDING'; END IF;
 SELECT count(*) INTO proofs FROM control.identity_envelope_rotation_attempt a WHERE a.operation_id=step.operation_id
  AND a.participant_id=step.participant_id AND a.privacy_domain_id=step.privacy_domain_id AND a.rotation_id=step.rotation_id
  AND a.slot IN('old','new') AND a.state='OBSERVED' AND a.observation=a.first_observation
  AND a.request->>'method'='PROVE' AND a.request->>'challengeHex'=encode(p_key.trust_digest,'hex')
  AND a.request->>'expectedFingerprint'=CASE a.slot WHEN 'old' THEN old_key.signer_id ELSE p_key.signer_id END
  AND a.observation->>'outcome'='SUCCEEDED' AND a.observation->>'resultHex' ~ '^[0-9a-f]{128}$'
  AND a.observation->>'attemptId'=a.attempt_id::text AND a.observation->>'operationId'=step.operation_id::text
  AND a.observation->>'requestDigest'='sha256:'||encode(a.request_digest,'hex')
  AND a.observation_digest=sha256(convert_to(openpc.signing_canonical_json(a.observation),'UTF8'))
  AND a.first_observation_digest=a.observation_digest
  AND (a.request->>'challengeIssuedAtNs')::numeric<=(a.observation->>'recordedAtNs')::numeric
  AND (a.observation->>'recordedAtNs')::numeric<=floor(extract(epoch from clock_timestamp())*1000000)*1000
  AND (a.request->>'challengeExpiresAtNs')::numeric>floor(extract(epoch from clock_timestamp())*1000000)*1000
  AND (a.request->>'challengeExpiresAtNs')::numeric>(a.observation->>'recordedAtNs')::numeric
  AND a.observation#>>'{descriptor,state}'='ACTIVE'
  AND a.observation#>>'{descriptor,publicKeySpkiHex}'=CASE a.slot WHEN 'old' THEN encode(old_key.public_key_spki_der,'hex') ELSE encode(p_key.public_key_spki_der,'hex') END
  AND a.observation#>>'{descriptor,fingerprint}'=CASE a.slot WHEN 'old' THEN old_key.signer_id ELSE p_key.signer_id END
  AND a.observation#>>'{descriptor,reference}'=CASE a.slot WHEN 'old' THEN old_key.secret_reference ELSE p_key.secret_reference END
  AND a.observation#>>'{descriptor,version}'=CASE a.slot WHEN 'old' THEN old_key.secret_version ELSE p_key.secret_version END
  AND a.observation#>>'{descriptor,validFromNs}'=CASE a.slot WHEN 'old' THEN old_key.valid_from_ns::text ELSE p_key.valid_from_ns::text END
  AND a.observation#>>'{descriptor,validUntilNs}'=CASE a.slot WHEN 'old' THEN old_key.valid_until_ns::text ELSE p_key.valid_until_ns::text END
  AND a.observation#>'{descriptor,revokedAtNs}'='null'::jsonb AND a.observation#>'{descriptor,retiredAtNs}'='null'::jsonb
  AND (a.slot='old' OR a.observation->'descriptor'=descriptor);
 IF (SELECT count(DISTINCT a.request->>'challengeIssuedAtNs') FROM control.identity_envelope_rotation_attempt a WHERE a.operation_id=step.operation_id)<>1
  OR step.result->>'observationsDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
    (SELECT jsonb_agg(jsonb_build_object('slot',a.slot,'request',a.request,'observation',a.observation) ORDER BY CASE a.slot WHEN 'old' THEN 0 ELSE 1 END)
     FROM control.identity_envelope_rotation_attempt a WHERE a.operation_id=step.operation_id)),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-TRUST-PROOF-BINDING'; END IF;
 IF proofs<>2 OR (SELECT count(*) FROM control.identity_envelope_rotation_attempt a WHERE a.operation_id=step.operation_id)<>2
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-TRUST-DUAL-PROOF'; END IF;
END $$;
REVOKE ALL ON FUNCTION openpc.check_identity_envelope_recovery_trust_admission(control.business_signing_key) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.check_identity_envelope_recovery_trust_admission(control.business_signing_key) TO openpc_control_runtime,openpc_control_platform_runtime;

CREATE OR REPLACE FUNCTION openpc.admit_identity_envelope_recovery_trust(p_preimage bytea,p_digest bytea)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
DECLARE step control.identity_envelope_rotation_step; rotation control.signing_key_rotation; old_key control.business_signing_key;
 descriptor jsonb; issuer jsonb; key_row control.business_signing_key; admission bytea;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT * INTO STRICT step FROM control.identity_envelope_rotation_step s WHERE s.operation_id=openpc.current_operation_id()
  AND openpc.matches_participant(s.participant_id) AND openpc.matches_privacy(s.privacy_domain_id)
  AND s.from_revision=4 AND s.from_state='DISTRIBUTED' AND s.to_state='VERIFIED' AND s.state='COMMITTED';
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' OR p_digest<>sha256(p_preimage)
  OR step.result->>'trustDigest' IS DISTINCT FROM 'sha256:'||encode(p_digest,'hex') THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-TRUST-ADMISSION'; END IF;
 SELECT * INTO STRICT rotation FROM control.signing_key_rotation r WHERE r.participant_id=step.participant_id
  AND r.privacy_domain_id=step.privacy_domain_id AND r.rotation_id=step.rotation_id AND r.recovery_case_id=step.recovery_id
  AND r.state='VERIFIED' AND r.revision=5;
 SELECT * INTO STRICT old_key FROM control.business_signing_key k WHERE k.participant_id=step.participant_id
  AND k.privacy_domain_id=step.privacy_domain_id AND k.signer_id=rotation.old_signer_id;
 SELECT a.observation->'descriptor' INTO STRICT descriptor FROM control.identity_envelope_rotation_attempt a
  JOIN control.identity_envelope_rotation_step prepared USING(participant_id,privacy_domain_id,rotation_id,operation_id)
  WHERE prepared.participant_id=step.participant_id AND prepared.privacy_domain_id=step.privacy_domain_id
   AND prepared.rotation_id=step.rotation_id AND prepared.recovery_id=step.recovery_id
   AND prepared.from_revision=2 AND prepared.to_state='PREPARED' AND prepared.state='COMMITTED' AND a.slot='new' AND a.state='OBSERVED';
 issuer:=step.authority_binding#>'{lease,issuer}';
 admission:=sha256(convert_to('pc.identity.envelope-key-recovery-admission.v1','UTF8')||decode('00','hex')||
  convert_to(openpc.signing_canonical_json(step.authority_binding||jsonb_build_object('issuer',issuer,
    'newFingerprint',descriptor->>'fingerprint','newReference',descriptor->>'reference','newVersion',descriptor->>'version')),'UTF8'));
 key_row.participant_id:=step.participant_id;key_row.privacy_domain_id:=step.privacy_domain_id;key_row.signer_id:=descriptor->>'fingerprint';
 key_row.signing_purpose_code:=371;key_row.environment_id:=rotation.environment_id;key_row.public_key_spki_der:=decode(descriptor->>'publicKeySpkiHex','hex');
 key_row.workload_credential_id:=(issuer->>'workloadCredentialId')::uuid;key_row.workload_credential_epoch:=(issuer->>'workloadCredentialEpoch')::numeric;
 key_row.envelope_workload_participant_epoch:=(issuer->>'workloadParticipantEpoch')::numeric;key_row.envelope_workload_principal_epoch:=(issuer->>'workloadPrincipalEpoch')::numeric;
 key_row.key_epoch:=old_key.key_epoch+1;key_row.valid_from_ns:=(descriptor->>'validFromNs')::numeric;key_row.valid_until_ns:=(descriptor->>'validUntilNs')::numeric;
 key_row.admission_kind:='GOVERNED';key_row.admission_reference:='urn:openpc:resource:'||rotation.rotation_id::text;key_row.admission_digest:=admission;
 key_row.secret_class:='SECRET-SIGNING-KEY';key_row.secret_reference:=descriptor->>'reference';key_row.secret_version:=descriptor->>'version';
 key_row.trust_preimage:=p_preimage;key_row.trust_digest:=p_digest;
 PERFORM openpc.check_identity_envelope_recovery_trust_admission(key_row);
 INSERT INTO control.business_signing_key SELECT (key_row).*;
 INSERT INTO control.identity_envelope_signing_grant(participant_id,privacy_domain_id,signer_id,signing_purpose_code,profile_digest)
  VALUES(key_row.participant_id,key_row.privacy_domain_id,key_row.signer_id,371,decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex'));
 INSERT INTO control.business_signing_key_state(participant_id,privacy_domain_id,signer_id,state,row_version,changed_at_ns,change_reference,change_digest)
  VALUES(key_row.participant_id,key_row.privacy_domain_id,key_row.signer_id,'ADMITTED',1,
   floor(extract(epoch from clock_timestamp())*1000000)*1000,key_row.admission_reference,step.evidence_digest);
 RETURN jsonb_build_object('signerId',key_row.signer_id,'trustDigest','sha256:'||encode(key_row.trust_digest,'hex'),'state','ADMITTED');
END $$;
REVOKE ALL ON FUNCTION openpc.admit_identity_envelope_recovery_trust(bytea,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.admit_identity_envelope_recovery_trust(bytea,bytea) TO openpc_control_runtime,openpc_control_platform_runtime;

CREATE OR REPLACE FUNCTION openpc.guard_identity_envelope_recovery_rotation(p_new control.signing_key_rotation,p_old control.signing_key_rotation,p_operation text)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE recovery control.platform_recovery_case; enrollment control.identity_envelope_recovery_enrollment; method text; expected_revision numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT * INTO recovery FROM control.platform_recovery_case c WHERE c.recovery_id=p_new.recovery_case_id
  AND c.participant_id=p_new.participant_id AND c.privacy_domain_id=p_new.privacy_domain_id;
 IF NOT FOUND OR NOT openpc.matches_participant(p_new.participant_id) OR NOT openpc.matches_privacy(p_new.privacy_domain_id)
  OR openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR NOT coalesce(openpc.identity_envelope_recovery_lease_current(recovery.recovery_id),false)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-CUSTODY'; END IF;
 SELECT * INTO STRICT enrollment FROM control.identity_envelope_recovery_enrollment e WHERE e.enrollment_id=recovery.signer_repair_enrollment_id
  AND e.participant_id=recovery.participant_id AND e.privacy_domain_id=recovery.privacy_domain_id;
 IF p_new.rotation_id::text IS DISTINCT FROM recovery.lease_bindings->>'rotationId'
  OR p_new.request IS DISTINCT FROM enrollment.document->'request'
  OR p_new.request->>'signerRole' IS DISTINCT FROM 'IDENTITY_ENVELOPE'
  OR p_new.request->>'purpose' IS DISTINCT FROM 'pc.cose.identity-authority-envelope.v1'
  OR NOT EXISTS(SELECT 1 FROM control.action_intent action WHERE action.action_intent_id='ACT-SIGNING_KEY_ROTATIONS_CREATE_RESOURCE-V1'
    AND action.action_intent_id=p_new.request->>'actionIntentId' AND action.resource_type='signing-key-rotation'
    AND action.operation_class='CREATE' AND action.maker_checker_required
    AND 'sha256:'||encode(action.semantic_digest,'hex')=p_new.request->>'actionIntentDigest')
  OR p_new.candidate_digest IS DISTINCT FROM sha256(convert_to(openpc.signing_canonical_json(
    jsonb_build_object('request',p_new.request,'lease',recovery.lease_bindings)),'UTF8'))
  OR p_new.old_trust_digest IS DISTINCT FROM decode(substr(recovery.lease_bindings->>'oldTrustDigest',8),'hex')
  OR p_new.maker_principal_id::text IS DISTINCT FROM recovery.lease_bindings->>'executorPrincipalId'
  OR p_new.old_signer_id IS DISTINCT FROM p_new.request->>'oldFingerprint'
  OR p_new.environment_id IS DISTINCT FROM p_new.request->>'environmentId'
  OR p_new.workload_credential_id::text IS DISTINCT FROM p_new.request->>'workloadCredentialId'
  OR p_new.approval_request_id IS NOT NULL
  OR (p_new.state NOT IN ('CUTOVER_FENCED','OBSERVING','OLD_REVOKED','OLD_RETIRED','COMPLETE') AND p_new.cutover_at_ns IS NOT NULL)
  OR p_new.recovery_from_state IS NOT NULL OR p_new.recovery_from_revision IS NOT NULL
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-RESERVATION'; END IF;
 IF p_operation='INSERT' THEN
  IF p_new.state<>'REQUESTED' OR p_new.revision<>1 OR p_new.approved_operation_id IS NOT NULL OR p_new.new_signer_id IS NOT NULL
   OR openpc.current_operation_id()::text IS DISTINCT FROM recovery.lease_bindings->>'creationOperationId' THEN
   RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-INITIAL'; END IF;
 ELSIF p_operation='UPDATE' THEN
  IF p_old.state='VERIFIED' AND p_new.state='CUTOVER_FENCED' THEN
   IF p_old.revision<>5 OR p_new.revision<>6 OR p_new.new_signer_id IS DISTINCT FROM p_old.new_signer_id OR p_old.cutover_at_ns IS NOT NULL
    OR p_new.cutover_at_ns IS NULL OR p_new.cutover_at_ns>floor(extract(epoch from clock_timestamp())*1000000)*1000
    OR p_new.updated_at<=p_old.updated_at
    OR (to_jsonb(p_new)-ARRAY['state','revision','updated_at','cutover_at_ns']) IS DISTINCT FROM (to_jsonb(p_old)-ARRAY['state','revision','updated_at','cutover_at_ns'])
    OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step s WHERE s.operation_id=openpc.current_operation_id() AND s.participant_id=p_new.participant_id
      AND s.privacy_domain_id=p_new.privacy_domain_id AND s.rotation_id=p_new.rotation_id AND s.recovery_id=recovery.recovery_id
      AND s.from_revision=5 AND s.from_state='VERIFIED' AND s.to_state='CUTOVER_FENCED' AND s.state='COMMITTED'
      AND openpc.identity_envelope_rotation_step_current(s) AND s.result->>'signerId'=p_new.new_signer_id AND s.result->>'state'='CUTOVER_FENCED'
      AND s.result->>'permissionEffect'='NONE' AND (s.result->>'selectionAdmissionVersion')::numeric=(recovery.lease_bindings->>'selectionAdmissionVersion')::numeric+1
      AND p_new.cutover_at_ns=floor(extract(epoch from s.completed_at)*1000000)*1000
      AND NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_attempt a WHERE a.operation_id=s.operation_id))
    THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-CUTOVER'; END IF;
   RETURN;
  END IF;
  IF p_old.state='DISTRIBUTED' AND p_new.state='VERIFIED' THEN
   IF p_old.revision<>4 OR p_new.revision<>5 OR p_new.new_signer_id IS DISTINCT FROM p_old.new_signer_id
    OR p_new.updated_at<=p_old.updated_at
    OR (to_jsonb(p_new)-ARRAY['state','revision','updated_at']) IS DISTINCT FROM (to_jsonb(p_old)-ARRAY['state','revision','updated_at'])
    OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step step WHERE step.operation_id=openpc.current_operation_id()
      AND step.participant_id=p_new.participant_id AND step.privacy_domain_id=p_new.privacy_domain_id AND step.rotation_id=p_new.rotation_id
      AND step.recovery_id=recovery.recovery_id AND step.from_revision=4 AND step.from_state='DISTRIBUTED' AND step.to_state='VERIFIED'
      AND step.state='COMMITTED' AND openpc.identity_envelope_rotation_step_current(step)
      AND step.result->>'state'='VERIFIED' AND step.result->>'admissionState'='ADMITTED' AND step.result->>'signerId'=p_new.new_signer_id
      AND (SELECT count(*) FROM control.identity_envelope_rotation_attempt a WHERE a.operation_id=step.operation_id)=2
      AND NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_attempt a WHERE a.operation_id=step.operation_id
        AND (a.state<>'OBSERVED' OR a.request->>'method'<>'PROVE' OR a.observation IS DISTINCT FROM a.first_observation
          OR a.observation->>'outcome'<>'SUCCEEDED' OR a.request->>'challengeHex' IS DISTINCT FROM substr(step.result->>'trustDigest',8))))
    THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-VERIFICATION'; END IF;
   RETURN;
  END IF;
  IF (p_old.state='APPROVED' AND p_new.state='PREPARED') OR (p_old.state='PREPARED' AND p_new.state='DISTRIBUTED') THEN
   method:=CASE WHEN p_new.state='PREPARED' THEN 'PREPARE' ELSE 'DISTRIBUTE' END;
   expected_revision:=CASE WHEN method='PREPARE' THEN 2 ELSE 3 END;
   IF p_old.revision<>expected_revision OR p_new.revision<>expected_revision+1 OR p_new.new_signer_id IS NULL
    OR (method='PREPARE' AND p_old.new_signer_id IS NOT NULL)
    OR (method='DISTRIBUTE' AND p_new.new_signer_id IS DISTINCT FROM p_old.new_signer_id)
    OR p_new.updated_at<=p_old.updated_at
    OR (to_jsonb(p_new)-ARRAY['state','revision','updated_at','new_signer_id'])
      IS DISTINCT FROM (to_jsonb(p_old)-ARRAY['state','revision','updated_at','new_signer_id'])
    OR p_new.approved_operation_id::text IS DISTINCT FROM recovery.lease_bindings->>'activationOperationId'
    OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step step
     JOIN control.identity_envelope_rotation_attempt attempt ON attempt.operation_id=step.operation_id AND attempt.rotation_id=step.rotation_id
      AND attempt.participant_id=step.participant_id AND attempt.privacy_domain_id=step.privacy_domain_id AND attempt.slot='new'
     WHERE step.operation_id=openpc.current_operation_id() AND step.rotation_id=p_new.rotation_id AND step.recovery_id=recovery.recovery_id
      AND step.participant_id=p_new.participant_id AND step.privacy_domain_id=p_new.privacy_domain_id
      AND step.from_revision=expected_revision AND step.from_state=p_old.state AND step.to_state=p_new.state AND step.state='COMMITTED'
      AND openpc.identity_envelope_rotation_step_current(step) AND step.result->>'state'=p_new.state
      AND step.result->>'signerId'=p_new.new_signer_id AND attempt.state='OBSERVED' AND attempt.request->>'method'=method
      AND attempt.observation->>'outcome'='SUCCEEDED' AND attempt.observation=attempt.first_observation
      AND attempt.observation#>>'{descriptor,fingerprint}'=p_new.new_signer_id
      AND attempt.observation#>>'{descriptor,reference}'=p_new.request->>'newReference'
      AND attempt.observation#>>'{descriptor,state}'='ACTIVE'
      AND attempt.observation#>>'{descriptor,fingerprint}'='sha256:'||encode(sha256(decode(attempt.observation#>>'{descriptor,publicKeySpkiHex}','hex')),'hex')
      AND (method='PREPARE' OR EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step prepared
        JOIN control.identity_envelope_rotation_attempt original USING(participant_id,privacy_domain_id,rotation_id,operation_id)
        WHERE prepared.participant_id=step.participant_id AND prepared.privacy_domain_id=step.privacy_domain_id AND prepared.rotation_id=step.rotation_id
          AND prepared.recovery_id=step.recovery_id AND prepared.from_revision=2 AND prepared.to_state='PREPARED'
          AND prepared.state='COMMITTED' AND original.slot='new' AND original.state='OBSERVED'
          AND original.observation->'descriptor'=attempt.observation->'descriptor'
          AND prepared.result->>'trustDigest'=attempt.request->>'trustContextDigest'
          AND prepared.result->>'trustDigest'=step.result->>'trustDigest')))
    THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-PREPARE'; END IF;
   RETURN;
  END IF;
  IF p_old.state<>'REQUESTED' OR p_new.state<>'APPROVED' OR p_new.revision<>p_old.revision+1
   OR openpc.current_operation_id()::text IS DISTINCT FROM recovery.lease_bindings->>'creationOperationId'
   OR p_new.new_signer_id IS NOT NULL
   OR p_new.updated_at<=p_old.updated_at
   OR p_new.approved_operation_id::text IS DISTINCT FROM recovery.lease_bindings->>'activationOperationId'
   OR (to_jsonb(p_new)-ARRAY['state','revision','updated_at','approved_operation_id'])
      IS DISTINCT FROM (to_jsonb(p_old)-ARRAY['state','revision','updated_at','approved_operation_id']) THEN
   -- Later proof/admission/cutover remain closed until immutable
   -- trust, versioned selection and genuine consumer owners are connected.
   RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-PHASE'; END IF;
 ELSE RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-OWNER';
 END IF;
END $$;
REVOKE ALL ON FUNCTION openpc.guard_identity_envelope_recovery_rotation(control.signing_key_rotation,control.signing_key_rotation,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.guard_identity_envelope_recovery_rotation(control.signing_key_rotation,control.signing_key_rotation,text) TO openpc_control_runtime,openpc_control_platform_runtime;

-- The initial rotation is never committed without its original signed creation
-- event. Deferred evaluation observes both state transitions in one transaction.
CREATE OR REPLACE FUNCTION openpc.check_identity_envelope_recovery_rotation_creation()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE recovery control.platform_recovery_case;
BEGIN
 IF NEW.recovery_case_id IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO STRICT recovery FROM control.platform_recovery_case c WHERE c.recovery_id=NEW.recovery_case_id
  AND c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id;
 IF NOT EXISTS(SELECT 1 FROM control.signing_key_rotation r WHERE r.participant_id=NEW.participant_id
    AND r.privacy_domain_id=NEW.privacy_domain_id AND r.rotation_id=NEW.rotation_id AND r.state<>'REQUESTED'
    AND r.approved_operation_id::text=recovery.lease_bindings->>'activationOperationId')
  OR NOT EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=NEW.participant_id
    AND event.privacy_domain_id=NEW.privacy_domain_id AND event.aggregate_type='signing-key-rotation'
    AND event.aggregate_id=NEW.rotation_id AND event.aggregate_sequence=1
    AND event.event_id::text=recovery.lease_bindings->>'creationOperationId'
    AND event.event_type='openpc.identity.envelope-rotation.created.v1'
    AND octet_length(event.payload_cbor)>0 AND event.payload_digest=sha256(event.payload_cbor)
    AND octet_length(event.cose_sign1)>0)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-CREATION'; END IF;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS identity_envelope_recovery_rotation_creation ON control.signing_key_rotation;
CREATE CONSTRAINT TRIGGER identity_envelope_recovery_rotation_creation AFTER INSERT ON control.signing_key_rotation
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.check_identity_envelope_recovery_rotation_creation();

CREATE OR REPLACE FUNCTION openpc.identity_envelope_rotation_step_bound(p_step control.identity_envelope_rotation_step)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
 SELECT openpc.matches_participant(p_step.participant_id) AND openpc.matches_privacy(p_step.privacy_domain_id)
  AND EXISTS(SELECT 1 FROM control.signing_key_rotation r JOIN control.platform_recovery_case c
   ON c.recovery_id=r.recovery_case_id AND c.participant_id=r.participant_id AND c.privacy_domain_id=r.privacy_domain_id
   JOIN control.identity_envelope_recovery_enrollment e ON e.enrollment_id=c.signer_repair_enrollment_id
    AND e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id
   WHERE r.rotation_id=p_step.rotation_id AND r.participant_id=p_step.participant_id AND r.privacy_domain_id=p_step.privacy_domain_id
    AND c.recovery_id=p_step.recovery_id AND c.activated_at IS NOT NULL
    AND r.request=e.document->'request' AND r.approval_request_id IS NULL
    AND r.rotation_id::text=c.lease_bindings->>'rotationId'
    AND p_step.principal_id::text=c.lease_bindings->>'executorPrincipalId'
    AND p_step.authority_binding=jsonb_build_object('kind','IDENTITY_ENVELOPE_SIGNER_RECOVERY','enrollment',e.document,'lease',c.lease_bindings)
    AND p_step.authority_digest=sha256(convert_to(openpc.signing_canonical_json(p_step.authority_binding),'UTF8')));
$$;
REVOKE ALL ON FUNCTION openpc.identity_envelope_rotation_step_bound(control.identity_envelope_rotation_step) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.identity_envelope_rotation_step_bound(control.identity_envelope_rotation_step) TO openpc_control_runtime,openpc_control_platform_runtime;

CREATE OR REPLACE FUNCTION openpc.identity_envelope_rotation_step_current(p_step control.identity_envelope_rotation_step)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
 SELECT openpc.identity_envelope_rotation_step_bound(p_step) AND openpc.identity_envelope_recovery_lease_current(p_step.recovery_id);
$$;
REVOKE ALL ON FUNCTION openpc.identity_envelope_rotation_step_current(control.identity_envelope_rotation_step) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.identity_envelope_rotation_step_current(control.identity_envelope_rotation_step) TO openpc_control_runtime,openpc_control_platform_runtime;

CREATE OR REPLACE FUNCTION openpc.guard_identity_envelope_rotation_step()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE rotation control.signing_key_rotation; effects jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' OR openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR NEW.operation_id IS DISTINCT FROM openpc.current_operation_id()
  OR NOT coalesce(openpc.identity_envelope_rotation_step_bound(NEW),false)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-STEP'; END IF;
 SELECT * INTO STRICT rotation FROM control.signing_key_rotation r WHERE r.participant_id=NEW.participant_id
  AND r.privacy_domain_id=NEW.privacy_domain_id AND r.rotation_id=NEW.rotation_id;
 effects:=openpc.signing_transition_effects('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1',NEW.from_state,NEW.to_state);
 IF effects IS NULL OR effects->>'kind'<>'ADVANCE' OR effects->>'resumeFrom' IS NOT NULL
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-TRANSITION'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'READY' OR NEW.started_at IS NOT NULL OR NEW.result IS NOT NULL
   OR NEW.from_revision<>rotation.revision OR NEW.from_state<>rotation.state
   OR length(NEW.idempotency_key) NOT BETWEEN 1 AND 200
   OR NOT coalesce(openpc.identity_envelope_rotation_step_current(NEW),false)
   THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-STEP'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['state','started_at','completed_at','result','evidence_cbor','evidence_digest','cose_sign1'])
   IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','started_at','completed_at','result','evidence_cbor','evidence_digest','cose_sign1'])
  OR (OLD.started_at IS NOT NULL AND NEW.started_at IS DISTINCT FROM OLD.started_at)
  OR (OLD.completed_at IS NOT NULL AND (NEW.completed_at,NEW.result,NEW.evidence_cbor,NEW.evidence_digest,NEW.cose_sign1)
   IS DISTINCT FROM (OLD.completed_at,OLD.result,OLD.evidence_cbor,OLD.evidence_digest,OLD.cose_sign1))
  THEN RAISE EXCEPTION 'DATA-6020-ENVELOPE-ROTATION-STEP'; END IF;
 IF NOT ((OLD.state='READY' AND NEW.state='STARTED') OR
  (OLD.state='STARTED' AND NEW.state IN ('COMMITTED','WRITE_AMBIGUITY','FAILED')) OR
  (OLD.state='WRITE_AMBIGUITY' AND NEW.state='STARTED')) THEN
  RAISE EXCEPTION 'DATA-6022-ENVELOPE-ROTATION-STEP'; END IF;
 IF NEW.state='STARTED' AND (NEW.started_at IS NULL OR NEW.started_at>clock_timestamp()
   OR rotation.revision<>NEW.from_revision OR rotation.state<>NEW.from_state
   OR (OLD.state='READY' AND NOT coalesce(openpc.identity_envelope_rotation_step_current(NEW),false))) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-START'; END IF;
 IF OLD.state='WRITE_AMBIGUITY' AND NEW.state='STARTED' AND (
  NEW.completed_at IS NOT NULL OR NEW.result IS NOT NULL
  OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_attempt a
    WHERE a.operation_id=NEW.operation_id AND a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id
      AND a.rotation_id=NEW.rotation_id AND a.state='WRITE_AMBIGUITY' AND a.started_at IS NOT NULL AND a.ambiguity_kind IS NOT NULL)
  ) THEN
  -- Historical lookup needs no renewed lease. It cannot open new provider I/O.
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-LOOKUP'; END IF;
 IF NEW.state IN ('COMMITTED','FAILED') AND (
  NOT coalesce(openpc.identity_envelope_rotation_step_current(NEW),false)
  OR rotation.revision<>NEW.from_revision OR rotation.state<>NEW.from_state
  OR NEW.evidence_digest IS DISTINCT FROM sha256(NEW.evidence_cbor)
  OR NEW.result->>'operationId' IS DISTINCT FROM NEW.operation_id::text
  OR NEW.result->>'rotationId' IS DISTINCT FROM NEW.rotation_id::text
  OR NEW.result->>'recoveryId' IS DISTINCT FROM NEW.recovery_id::text
  OR NEW.result->>'fromRevision' IS DISTINCT FROM NEW.from_revision::text
  OR NEW.result->>'revision' IS DISTINCT FROM (NEW.from_revision+1)::text
  OR NEW.result->>'state' IS DISTINCT FROM (CASE WHEN NEW.state='FAILED' THEN 'FAILED' ELSE NEW.to_state END)
  OR EXISTS(SELECT 1 FROM control.identity_envelope_rotation_attempt a WHERE a.operation_id=NEW.operation_id AND a.state<>'OBSERVED')
  OR (SELECT count(*) FROM control.identity_envelope_rotation_attempt a WHERE a.operation_id=NEW.operation_id)<>jsonb_array_length(effects->'providerSteps')
  OR (NEW.state='COMMITTED' AND EXISTS(SELECT 1 FROM control.identity_envelope_rotation_attempt a
    WHERE a.operation_id=NEW.operation_id AND a.observation->>'outcome'<>'SUCCEEDED'))
  OR (NEW.state='FAILED' AND NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_attempt a
    WHERE a.operation_id=NEW.operation_id AND a.observation->>'outcome'='REJECTED')))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-RESULT'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS identity_envelope_rotation_step_guard ON control.identity_envelope_rotation_step;
CREATE TRIGGER identity_envelope_rotation_step_guard BEFORE INSERT OR UPDATE OR DELETE ON control.identity_envelope_rotation_step
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_identity_envelope_rotation_step();

CREATE OR REPLACE FUNCTION openpc.guard_identity_envelope_rotation_attempt()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE step control.identity_envelope_rotation_step; rotation control.signing_key_rotation; effects jsonb; issuer jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' OR openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
  OR NEW.operation_id IS DISTINCT FROM openpc.current_operation_id()
  OR NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-ATTEMPT'; END IF;
 SELECT * INTO STRICT step FROM control.identity_envelope_rotation_step s WHERE s.operation_id=NEW.operation_id
  AND s.participant_id=NEW.participant_id AND s.privacy_domain_id=NEW.privacy_domain_id AND s.rotation_id=NEW.rotation_id;
 IF NOT coalesce(openpc.identity_envelope_rotation_step_bound(step),false) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-ATTEMPT'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO STRICT rotation FROM control.signing_key_rotation r WHERE r.participant_id=NEW.participant_id
   AND r.privacy_domain_id=NEW.privacy_domain_id AND r.rotation_id=NEW.rotation_id;
  effects:=openpc.signing_transition_effects('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1',step.from_state,step.to_state);
  issuer:=step.authority_binding#>'{lease,issuer}';
  IF step.state<>'READY' OR NEW.state<>'READY' OR NEW.started_at IS NOT NULL OR NEW.observation IS NOT NULL OR NEW.first_observation IS NOT NULL OR NEW.ambiguity_kind IS NOT NULL
   OR NOT coalesce(openpc.identity_envelope_rotation_step_current(step),false)
   OR NOT (effects->'providerSteps' @> jsonb_build_array(jsonb_build_array(NEW.slot,NEW.request->>'method')))
   OR NEW.request_digest<>sha256(convert_to('pc.identity.envelope-key-rotation-request.v1','UTF8')||decode('00','hex')||convert_to(openpc.signing_canonical_json(NEW.request),'UTF8'))
   OR NEW.request->>'participantId' IS DISTINCT FROM NEW.participant_id::text OR NEW.request->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
   OR NEW.request->>'rotationId' IS DISTINCT FROM NEW.rotation_id::text OR NEW.request->>'operationId' IS DISTINCT FROM NEW.operation_id::text
   OR NEW.request->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text
   OR NEW.request->>'purpose' IS DISTINCT FROM 'pc.cose.identity-authority-envelope.v1' OR NEW.request->>'purposeCode' IS DISTINCT FROM '371'
   OR NEW.request->>'schemaId' IS DISTINCT FROM '24034' OR NEW.request->>'schemaVersion' IS DISTINCT FROM '1'
   OR NEW.request->>'secretClass' IS DISTINCT FROM 'SECRET-SIGNING-KEY'
   OR NEW.request->>'schemaDefinitionDigest' IS DISTINCT FROM 'sha256:6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5'
   OR NEW.request->>'profileId' IS DISTINCT FROM 'pc.identity.authority-envelope.v1'
   OR NEW.request->>'profileVersion' IS DISTINCT FROM '1'
   OR NEW.request->>'profileDigest' IS DISTINCT FROM 'sha256:54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74'
   OR NEW.request-ARRAY['participantId','privacyDomainId','environmentId','workloadCredentialId','workloadCredentialEpoch',
    'secretClass','reference','version','purpose','purposeCode','schemaId','schemaVersion','schemaDefinitionDigest','profileId',
    'profileVersion','profileDigest','callerWorkloadCredentialId','rotationId','operationId','attemptId','issuerParticipantEpoch',
    'issuerPrincipalEpoch','governanceDigest','method','expectedFingerprint']-
      (CASE NEW.request->>'method' WHEN 'DISTRIBUTE' THEN ARRAY['trustContextDigest']
       WHEN 'PROVE' THEN ARRAY['challengeHex','challengeIssuedAtNs','challengeExpiresAtNs'] ELSE ARRAY[]::text[] END)<>'{}'::jsonb
   OR NEW.request->>'environmentId' IS DISTINCT FROM rotation.environment_id
   OR NEW.request->>'workloadCredentialId' IS DISTINCT FROM issuer->>'workloadCredentialId'
   OR NEW.request->>'callerWorkloadCredentialId' IS DISTINCT FROM issuer->>'workloadCredentialId'
   OR NEW.request->>'workloadCredentialEpoch' IS DISTINCT FROM issuer->>'workloadCredentialEpoch'
   OR NEW.request->>'issuerParticipantEpoch' IS DISTINCT FROM issuer->>'workloadParticipantEpoch'
   OR NEW.request->>'issuerPrincipalEpoch' IS DISTINCT FROM issuer->>'workloadPrincipalEpoch'
   OR NEW.request->>'reference' IS DISTINCT FROM (CASE WHEN NEW.slot='old' THEN rotation.request->>'oldReference' ELSE rotation.request->>'newReference' END)
   OR NEW.request->>'version' IS DISTINCT FROM split_part(NEW.request->>'reference','#',2)
   OR NEW.request->>'governanceDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
      jsonb_build_object('domain','pc.identity.envelope-rotation-governance.v1','admission',step.authority_binding)),'UTF8')),'hex')
   OR (NEW.request->>'method'<>'PREPARE' AND NEW.request->>'expectedFingerprint' IS DISTINCT FROM
     (CASE WHEN NEW.slot='old' THEN rotation.old_signer_id ELSE rotation.new_signer_id END))
   OR (NEW.request->>'method'='PREPARE' AND NEW.request->>'expectedFingerprint' IS DISTINCT FROM rotation.request->>'newFingerprint')
   OR (NEW.request->>'method'='DISTRIBUTE' AND NOT EXISTS(
     SELECT 1 FROM control.identity_envelope_rotation_step prepared WHERE prepared.participant_id=NEW.participant_id
      AND prepared.privacy_domain_id=NEW.privacy_domain_id AND prepared.rotation_id=NEW.rotation_id AND prepared.recovery_id=step.recovery_id
      AND prepared.from_revision=2 AND prepared.from_state='APPROVED' AND prepared.to_state='PREPARED' AND prepared.state='COMMITTED'
      AND prepared.result->>'signerId'=rotation.new_signer_id AND prepared.result->>'trustDigest'=NEW.request->>'trustContextDigest'))
   OR (NEW.request->>'method'='PROVE' AND (
      coalesce(NEW.request->>'challengeHex','') !~ '^[0-9a-f]{64}$'
      OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step prepared WHERE prepared.participant_id=NEW.participant_id
        AND prepared.privacy_domain_id=NEW.privacy_domain_id AND prepared.rotation_id=NEW.rotation_id AND prepared.recovery_id=step.recovery_id
        AND prepared.from_revision=3 AND prepared.to_state='DISTRIBUTED' AND prepared.state='COMMITTED'
        AND prepared.result->>'signerId'=rotation.new_signer_id AND substr(prepared.result->>'trustDigest',8)=NEW.request->>'challengeHex')
      OR
      (NEW.request->>'challengeIssuedAtNs')::numeric>floor(extract(epoch FROM clock_timestamp())*1000000)*1000
      OR (NEW.request->>'challengeExpiresAtNs')::numeric<=(NEW.request->>'challengeIssuedAtNs')::numeric
      OR (NEW.request->>'challengeExpiresAtNs')::numeric>(NEW.request->>'challengeIssuedAtNs')::numeric+300000000000
      OR (NEW.request->>'challengeExpiresAtNs')::numeric>floor(extract(epoch FROM (step.authority_binding#>>'{lease,validUntil}')::timestamptz)*1000000)*1000))
   THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-REQUEST'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['state','started_at','observed_at','observation','observation_digest','first_observation','first_observation_digest','ambiguity_kind'])
   IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','started_at','observed_at','observation','observation_digest','first_observation','first_observation_digest','ambiguity_kind'])
  OR (OLD.started_at IS NOT NULL AND NEW.started_at IS DISTINCT FROM OLD.started_at)
  OR (OLD.first_observation IS NOT NULL AND (NEW.first_observation,NEW.first_observation_digest) IS DISTINCT FROM (OLD.first_observation,OLD.first_observation_digest))
  OR (OLD.observation IS NOT NULL AND (NEW.observation,NEW.observation_digest,NEW.observed_at) IS DISTINCT FROM (OLD.observation,OLD.observation_digest,OLD.observed_at))
  OR (OLD.ambiguity_kind IS NOT NULL AND NEW.ambiguity_kind IS DISTINCT FROM OLD.ambiguity_kind)
  OR OLD.state='OBSERVED' THEN RAISE EXCEPTION 'DATA-6020-ENVELOPE-ROTATION-ATTEMPT'; END IF;
 IF NOT ((OLD.state='READY' AND NEW.state='STARTED') OR
   (OLD.state='STARTED' AND NEW.state IN ('STARTED','OBSERVED','WRITE_AMBIGUITY')) OR
   (OLD.state='WRITE_AMBIGUITY' AND NEW.state IN ('WRITE_AMBIGUITY','OBSERVED'))) THEN
  RAISE EXCEPTION 'DATA-6022-ENVELOPE-ROTATION-ATTEMPT'; END IF;
 IF OLD.state='READY' AND NEW.state='STARTED' AND (step.state<>'STARTED' OR NEW.started_at IS NULL
   OR NEW.started_at>clock_timestamp() OR NOT coalesce(openpc.identity_envelope_rotation_step_current(step),false)
   OR EXISTS(SELECT 1 FROM control.identity_envelope_rotation_attempt sibling WHERE sibling.operation_id=NEW.operation_id AND sibling.state='WRITE_AMBIGUITY')
   OR (NEW.request->>'method'='PROVE' AND (NEW.request->>'challengeExpiresAtNs')::numeric<=floor(extract(epoch FROM clock_timestamp())*1000000)*1000)) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-DISPATCH'; END IF;
 IF NEW.first_observation IS NOT NULL AND (NEW.first_observation_digest IS DISTINCT FROM sha256(convert_to(openpc.signing_canonical_json(NEW.first_observation),'UTF8'))
   OR NEW.first_observation->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text
   OR NEW.first_observation->>'operationId' IS DISTINCT FROM NEW.operation_id::text
   OR NEW.first_observation->>'requestDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.request_digest,'hex')
   OR NEW.first_observation->>'method' IS DISTINCT FROM NEW.request->>'method') THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-OBSERVATION'; END IF;
 IF NEW.state='OBSERVED' AND (NEW.observation IS DISTINCT FROM NEW.first_observation
   OR NEW.observation_digest IS DISTINCT FROM NEW.first_observation_digest OR NEW.observed_at>clock_timestamp()) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-LOOKUP'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS identity_envelope_rotation_attempt_guard ON control.identity_envelope_rotation_attempt;
CREATE TRIGGER identity_envelope_rotation_attempt_guard BEFORE INSERT OR UPDATE OR DELETE ON control.identity_envelope_rotation_attempt
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_identity_envelope_rotation_attempt();

-- A signed completion without the same committed business state and outbox
-- is rejected at transaction end. A worker observation alone is not completion.
CREATE OR REPLACE FUNCTION openpc.check_identity_envelope_rotation_step_effect()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,control AS $$
BEGIN
 IF NEW.state NOT IN ('COMMITTED','FAILED') THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.signing_key_rotation r WHERE r.participant_id=NEW.participant_id
   AND r.privacy_domain_id=NEW.privacy_domain_id AND r.rotation_id=NEW.rotation_id
   AND r.recovery_case_id=NEW.recovery_id AND r.revision=NEW.from_revision+1 AND r.state=NEW.result->>'state')
  OR NOT EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=NEW.participant_id
    AND event.privacy_domain_id=NEW.privacy_domain_id AND event.aggregate_type='signing-key-rotation'
    AND event.aggregate_id=NEW.rotation_id AND event.event_id=NEW.operation_id
    AND event.event_type='openpc.identity.envelope-rotation.phase.v1'
    AND event.payload_cbor=NEW.evidence_cbor AND event.payload_digest=NEW.evidence_digest AND event.cose_sign1=NEW.cose_sign1)
  OR (NEW.state='COMMITTED' AND NEW.to_state='CUTOVER_FENCED' AND NOT EXISTS(SELECT 1 FROM control.identity_envelope_signing_selection selection
    JOIN control.business_signing_key_state life USING(participant_id,privacy_domain_id,signer_id)
    WHERE selection.participant_id=NEW.participant_id AND selection.privacy_domain_id=NEW.privacy_domain_id AND selection.signer_id=NEW.result->>'signerId'
      AND selection.admission_version::text=NEW.result->>'selectionAdmissionVersion' AND life.state='ACTIVE'))
  OR (NEW.state='COMMITTED' AND NEW.to_state='VERIFIED' AND NOT EXISTS(SELECT 1 FROM control.business_signing_key k
    JOIN control.identity_envelope_signing_grant g USING(participant_id,privacy_domain_id,signer_id)
    JOIN control.business_signing_key_state life USING(participant_id,privacy_domain_id,signer_id)
    WHERE k.participant_id=NEW.participant_id AND k.privacy_domain_id=NEW.privacy_domain_id AND k.signer_id=NEW.result->>'signerId'
      AND k.signing_purpose_code=371 AND g.signing_purpose_code=371 AND g.profile_digest=decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex')
      AND k.trust_digest=decode(substr(NEW.result->>'trustDigest',8),'hex') AND life.state='ADMITTED' AND life.change_digest=NEW.evidence_digest))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ROTATION-EFFECT'; END IF;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS identity_envelope_rotation_step_effect ON control.identity_envelope_rotation_step;
CREATE CONSTRAINT TRIGGER identity_envelope_rotation_step_effect AFTER INSERT OR UPDATE ON control.identity_envelope_rotation_step
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.check_identity_envelope_rotation_step_effect();

REVOKE INSERT,UPDATE,DELETE ON control.identity_envelope_rotation_step,control.identity_envelope_rotation_attempt FROM openpc_control_runtime,openpc_control_platform_runtime,openpc_control_worker;
GRANT INSERT ON control.identity_envelope_rotation_step,control.identity_envelope_rotation_attempt TO openpc_control_runtime,openpc_control_platform_runtime;
GRANT UPDATE(state,started_at,completed_at,result,evidence_cbor,evidence_digest,cose_sign1) ON control.identity_envelope_rotation_step TO openpc_control_runtime,openpc_control_platform_runtime;
GRANT UPDATE(state,started_at,observed_at,observation,observation_digest,first_observation,first_observation_digest,ambiguity_kind) ON control.identity_envelope_rotation_attempt TO openpc_control_runtime,openpc_control_platform_runtime;

CREATE OR REPLACE FUNCTION openpc.guard_identity_envelope_signing_selection()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE step control.identity_envelope_rotation_step; rotation control.signing_key_rotation;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-ENVELOPE-SIGNING-SELECTION'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.admission_version<>1 OR (NOT pg_has_role(current_user,'openpc_control_key_governor','MEMBER')
    AND NOT pg_has_role(current_user,'openpc_control_owner','MEMBER')) THEN
   RAISE EXCEPTION 'DATA-6021-ENVELOPE-SIGNING-INSTALLATION-AUTHORITY'; END IF;
 ELSE
  PERFORM openpc.assert_request_context(true);
  IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
   OR NOT openpc.matches_participant(NEW.participant_id) OR NOT openpc.matches_privacy(NEW.privacy_domain_id)
   OR NEW.admission_version<>OLD.admission_version+1 OR NEW.signer_id=OLD.signer_id
   OR (to_jsonb(NEW)-ARRAY['signer_id','admission_version']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['signer_id','admission_version'])
   THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SIGNING-CUTOVER'; END IF;
  SELECT * INTO STRICT step FROM control.identity_envelope_rotation_step s WHERE s.operation_id=openpc.current_operation_id()
   AND s.participant_id=NEW.participant_id AND s.privacy_domain_id=NEW.privacy_domain_id AND s.from_revision=5
   AND s.from_state='VERIFIED' AND s.to_state='CUTOVER_FENCED' AND s.state='COMMITTED';
  SELECT * INTO STRICT rotation FROM control.signing_key_rotation r WHERE r.participant_id=step.participant_id
   AND r.privacy_domain_id=step.privacy_domain_id AND r.rotation_id=step.rotation_id AND r.recovery_case_id=step.recovery_id
   AND r.state='CUTOVER_FENCED' AND r.revision=6 AND r.old_signer_id=OLD.signer_id AND r.new_signer_id=NEW.signer_id;
  IF NOT coalesce(openpc.identity_envelope_rotation_step_current(step),false)
    OR rotation.environment_id<>NEW.environment_id OR step.result->>'signerId' IS DISTINCT FROM NEW.signer_id
    OR step.result->>'selectionAdmissionVersion' IS DISTINCT FROM NEW.admission_version::text
    OR OLD.admission_version::text IS DISTINCT FROM step.authority_binding#>>'{lease,selectionAdmissionVersion}'
    OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_rotation_step verified WHERE verified.participant_id=step.participant_id
      AND verified.privacy_domain_id=step.privacy_domain_id AND verified.rotation_id=step.rotation_id AND verified.recovery_id=step.recovery_id
      AND verified.from_revision=4 AND verified.to_state='VERIFIED' AND verified.state='COMMITTED'
      AND verified.result->>'trustDigest'=step.result->>'trustDigest' AND verified.result->>'admissionState'='ADMITTED')
    OR EXISTS(SELECT 1 FROM control.identity_envelope_rotation_attempt proof WHERE proof.rotation_id=step.rotation_id
      AND proof.request->>'method'='PROVE' AND proof.slot IN('old','new')
      AND (proof.request->>'challengeExpiresAtNs')::numeric<=floor(extract(epoch from clock_timestamp())*1000000)*1000)
   THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SIGNING-CUTOVER-PROVENANCE'; END IF;
 END IF;
 IF NEW.profile_digest<>decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex') OR NOT EXISTS(
  SELECT 1 FROM control.business_signing_key k JOIN control.business_signing_key_state life USING(participant_id,privacy_domain_id,signer_id)
   JOIN control.credential credential ON credential.participant_id=k.participant_id AND credential.credential_id=k.workload_credential_id
   JOIN control.principal principal ON principal.participant_id=credential.participant_id AND principal.principal_id=credential.principal_id
   JOIN control.participant participant ON participant.participant_id=k.participant_id
   WHERE k.participant_id=NEW.participant_id AND k.privacy_domain_id=NEW.privacy_domain_id AND k.signer_id=NEW.signer_id
    AND k.environment_id=NEW.environment_id AND k.signing_purpose_code=371 AND life.state='ACTIVE'
    AND k.valid_from_ns<=floor(extract(epoch from clock_timestamp())*1000000)*1000 AND k.valid_until_ns>floor(extract(epoch from clock_timestamp())*1000000)*1000
    AND credential.state='ACTIVE' AND credential.kind IN('WORKLOAD_OIDC','WORKLOAD_MTLS') AND credential.credential_epoch=k.workload_credential_epoch
    AND credential.valid_from<=clock_timestamp() AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
    AND principal.kind='WORKLOAD' AND principal.state='ACTIVE' AND principal.authority_epoch=k.envelope_workload_principal_epoch
    AND participant.state='ACTIVE' AND participant.authority_epoch=k.envelope_workload_participant_epoch FOR SHARE OF life)
 THEN RAISE EXCEPTION 'DATA-6021-ENVELOPE-SIGNING-CURRENT-KEY'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS identity_envelope_signing_selection_immutable ON control.identity_envelope_signing_selection;
DROP TRIGGER IF EXISTS identity_envelope_signing_selection_guard ON control.identity_envelope_signing_selection;
CREATE TRIGGER identity_envelope_signing_selection_guard BEFORE INSERT OR UPDATE OR DELETE ON control.identity_envelope_signing_selection
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_identity_envelope_signing_selection();

CREATE OR REPLACE FUNCTION openpc.select_identity_envelope_recovery_trust()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,control SET row_security=on AS $$
DECLARE step control.identity_envelope_rotation_step; rotation control.signing_key_rotation;
 selected control.identity_envelope_signing_selection; next_key control.business_signing_key; changed integer;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT * INTO STRICT step FROM control.identity_envelope_rotation_step s WHERE s.operation_id=openpc.current_operation_id()
  AND openpc.matches_participant(s.participant_id) AND openpc.matches_privacy(s.privacy_domain_id)
  AND s.from_revision=5 AND s.from_state='VERIFIED' AND s.to_state='CUTOVER_FENCED' AND s.state='COMMITTED';
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' OR NOT coalesce(openpc.identity_envelope_rotation_step_current(step),false)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SIGNING-CUTOVER'; END IF;
 SELECT * INTO STRICT rotation FROM control.signing_key_rotation r WHERE r.participant_id=step.participant_id AND r.privacy_domain_id=step.privacy_domain_id
  AND r.rotation_id=step.rotation_id AND r.recovery_case_id=step.recovery_id AND r.state='CUTOVER_FENCED' AND r.revision=6;
 SELECT * INTO STRICT selected FROM control.identity_envelope_signing_selection s WHERE s.participant_id=step.participant_id AND s.privacy_domain_id=step.privacy_domain_id
  AND s.environment_id=rotation.environment_id AND s.profile_digest=decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex')
  AND s.signer_id=rotation.old_signer_id AND s.admission_version::text=step.authority_binding#>>'{lease,selectionAdmissionVersion}' FOR UPDATE;
 SELECT k.* INTO STRICT next_key FROM control.business_signing_key k JOIN control.identity_envelope_signing_grant g USING(participant_id,privacy_domain_id,signer_id)
  WHERE k.participant_id=step.participant_id AND k.privacy_domain_id=step.privacy_domain_id AND k.signer_id=rotation.new_signer_id AND k.signing_purpose_code=371
   AND g.signing_purpose_code=371 AND g.profile_digest=selected.profile_digest AND k.environment_id=selected.environment_id
   AND k.trust_digest=decode(substr(step.result->>'trustDigest',8),'hex');
 UPDATE control.business_signing_key_state SET state='ACTIVE',row_version=row_version+1,
  changed_at_ns=floor(extract(epoch from clock_timestamp())*1000000)*1000,change_reference='urn:openpc:resource:'||rotation.rotation_id::text,change_digest=step.evidence_digest
  WHERE participant_id=step.participant_id AND privacy_domain_id=step.privacy_domain_id AND signer_id=next_key.signer_id AND state='ADMITTED' AND row_version=1;
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>1 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SIGNING-CUTOVER-LIFECYCLE'; END IF;
 UPDATE control.identity_envelope_signing_selection SET signer_id=next_key.signer_id,admission_version=admission_version+1
  WHERE participant_id=selected.participant_id AND privacy_domain_id=selected.privacy_domain_id AND environment_id=selected.environment_id
   AND profile_digest=selected.profile_digest AND signer_id=selected.signer_id AND admission_version=selected.admission_version;
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>1 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SIGNING-CUTOVER-SELECTION'; END IF;
 RETURN jsonb_build_object('signerId',next_key.signer_id,'trustDigest','sha256:'||encode(next_key.trust_digest,'hex'),
  'selectionAdmissionVersion',(selected.admission_version+1)::text,'state','SELECTED');
END $$;
REVOKE ALL ON FUNCTION openpc.select_identity_envelope_recovery_trust() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.select_identity_envelope_recovery_trust() TO openpc_control_runtime,openpc_control_platform_runtime;


CREATE OR REPLACE FUNCTION openpc.guard_identity_envelope_representation()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.representation,NEW.participant_id,NEW.issuer_participant_id,NEW.issuer_privacy_domain_id,NEW.principal_id)
   IS DISTINCT FROM (OLD.representation,OLD.participant_id,OLD.issuer_participant_id,OLD.issuer_privacy_domain_id,OLD.principal_id) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-REPRESENTATION';
 END IF;
 IF NEW.representation IN ('LEGACY','RECOVERY_V1') THEN RETURN NEW; END IF;
 IF NEW.representation<>'TYPED_V1' OR NEW.platform_context_id IS NULL OR NEW.platform_authority_epoch IS NULL
   OR NEW.valid_until IS NULL
   OR (NEW.state='ACTIVE') IS DISTINCT FROM (octet_length(NEW.cose_sign1)>0)
   OR NEW.semantic_digest<>sha256(NEW.semantic_cbor) THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-PROPOSAL'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'DRAFT' OR NEW.row_version<>1 OR NEW.checker_principal_id IS NOT NULL THEN
   RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-INITIAL-STATE'; END IF;
 ELSE
  IF (to_jsonb(NEW)-'creator_participant_id'-'state'-'checker_principal_id'-'last_mutation_operation_id'-'row_version'-'updated_at'-'cose_sign1')
    IS DISTINCT FROM (to_jsonb(OLD)-'creator_participant_id'-'state'-'checker_principal_id'-'last_mutation_operation_id'-'row_version'-'updated_at'-'cose_sign1')
    OR NEW.row_version<>OLD.row_version+1 OR NEW.last_mutation_operation_id IS NULL
    OR NOT (
      (OLD.state='DRAFT' AND NEW.state='SUBMITTED' AND NEW.checker_principal_id IS NULL
       AND NEW.cose_sign1=OLD.cose_sign1)
      OR (OLD.state='SUBMITTED' AND NEW.state='APPROVED' AND NEW.checker_principal_id IS NOT NULL
       AND NEW.cose_sign1=OLD.cose_sign1)
      OR (OLD.state='APPROVED' AND NEW.state='ACTIVE' AND NEW.checker_principal_id=OLD.checker_principal_id
       AND EXISTS(SELECT 1 FROM control.identity_envelope_activation activation
        WHERE activation.participant_id=NEW.participant_id
         AND activation.privacy_domain_id=NEW.issuer_privacy_domain_id
         AND activation.envelope_id=NEW.authority_envelope_id
         AND activation.operation_id=openpc.current_operation_id()
         AND activation.state='OBSERVED' AND activation.row_version=3
         AND activation.cose_sign1=NEW.cose_sign1))
    ) THEN
   RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SEALED-ACTIVATION-REQUIRED'; END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS authority_envelope_representation ON control.authority_envelope;
CREATE TRIGGER authority_envelope_representation BEFORE INSERT OR UPDATE ON control.authority_envelope
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_identity_envelope_representation();

CREATE OR REPLACE FUNCTION openpc.guard_identity_envelope_proposal()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE proposal jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-HISTORY'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'DRAFT' OR NEW.row_version<>1 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-INITIAL-STATE'; END IF;
 ELSE
  IF (to_jsonb(NEW)-'state'-'submission_operation_id'-'submission_intent_digest'-'submission_approval_id'-'submission_maker'-'submission_checker'-'submission_checker_authority'-'row_version')
    IS DISTINCT FROM (to_jsonb(OLD)-'state'-'submission_operation_id'-'submission_intent_digest'-'submission_approval_id'-'submission_maker'-'submission_checker'-'submission_checker_authority'-'row_version')
    OR NEW.row_version<>OLD.row_version+1
    OR NOT ((OLD.state='DRAFT' AND NEW.state='SUBMITTED') OR (OLD.state='SUBMITTED' AND NEW.state='APPROVED')) THEN
   RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-HISTORY'; END IF;
  IF OLD.state='SUBMITTED' AND (NEW.submission_operation_id,NEW.submission_intent_digest,NEW.submission_approval_id,NEW.submission_maker)
    IS DISTINCT FROM (OLD.submission_operation_id,OLD.submission_intent_digest,OLD.submission_approval_id,OLD.submission_maker) THEN
   RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SUBMISSION-IMMUTABLE'; END IF;
 END IF;
 proposal:=openpc.business_cbor(NEW.proposal_cbor);
 IF jsonb_typeof(proposal) IS DISTINCT FROM 'object'
   OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(proposal) key) IS DISTINCT FROM ARRAY['0','1','10','2','3','4','5','6','7','8','9']
   OR proposal->'0' IS DISTINCT FROM jsonb_build_object('bytes','6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5')
   OR proposal->'1' IS DISTINCT FROM jsonb_build_object('bytes',replace(NEW.envelope_id::text,'-',''))
   OR proposal->>'2' IS DISTINCT FROM '1'
   OR proposal->'3' IS DISTINCT FROM jsonb_build_object('bytes',replace(NEW.target_participant_id::text,'-',''))
   OR proposal#>'{10,2,1}' IS DISTINCT FROM jsonb_build_object('bytes',replace(NEW.participant_id::text,'-',''))
   OR proposal#>'{10,2,3}' IS DISTINCT FROM jsonb_build_object('bytes',replace(NEW.maker_principal_id::text,'-',''))
   OR NEW.issuer_authority#>>'{binding,participantId}' IS DISTINCT FROM NEW.participant_id::text
   OR NEW.issuer_authority#>>'{binding,principalId}' IS DISTINCT FROM NEW.maker_principal_id::text
   OR NEW.issuer_authority#>>'{durable,grant,privacyDomainId}' IS DISTINCT FROM NEW.privacy_domain_id::text THEN
  RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-PROVENANCE'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS identity_envelope_proposal_history ON control.identity_envelope_proposal;
CREATE TRIGGER identity_envelope_proposal_history BEFORE INSERT OR UPDATE OR DELETE ON control.identity_envelope_proposal
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_identity_envelope_proposal();

CREATE OR REPLACE FUNCTION openpc.require_identity_envelope_proposal()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE original_mode text; original_participant uuid; original_privacy uuid;
 operation uuid; action text;
	 p control.identity_envelope_proposal%ROWTYPE; envelope control.authority_envelope%ROWTYPE;
	 valid_source boolean; activation_cose bytea;
BEGIN
 IF TG_TABLE_NAME='authority_envelope' THEN
  -- Recovery provenance is enforced by guard_platform_recovery_envelope and
  -- its immutable signed case bindings. It has no ordinary typed issuer or
  -- proposal sidecar; typed envelopes must retain the checks below.
  IF NEW.representation IN ('LEGACY','RECOVERY_V1') THEN RETURN NULL; END IF;
 END IF;
 -- Legacy initialization has no typed governance context. Typed rows still
 -- require every ordinary context field before any scoped lookup or switch.
 original_mode:=current_setting('openpc.context_mode');
 original_participant:=openpc.current_participant_id(); original_privacy:=openpc.current_privacy_domain_id();
 operation:=openpc.current_operation_id(); action:=openpc.current_action_intent_id();
 IF TG_TABLE_NAME='authority_envelope' THEN
  -- Resolve only the envelope's immutable original issuer; no tenant OR-policy.
  PERFORM openpc.set_request_context('PARTICIPANT',NEW.issuer_participant_id,NEW.issuer_privacy_domain_id,operation,action,true);
  SELECT * INTO p FROM control.identity_envelope_proposal WHERE participant_id=NEW.issuer_participant_id
    AND privacy_domain_id=NEW.issuer_privacy_domain_id AND envelope_id=NEW.authority_envelope_id;
 ELSE
  PERFORM openpc.set_request_context('PARTICIPANT',NEW.participant_id,NEW.privacy_domain_id,operation,action,true);
  SELECT * INTO p FROM control.identity_envelope_proposal WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND envelope_id=NEW.envelope_id;
 END IF;
 IF p.envelope_id IS NULL THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SIDECAR'; END IF;
 PERFORM openpc.set_request_context('PARTICIPANT',p.participant_id,p.privacy_domain_id,operation,action,true);
 SELECT EXISTS(SELECT 1 FROM control.mutation_candidate candidate
   JOIN control.mutation_evidence evidence ON evidence.participant_id=candidate.participant_id AND evidence.privacy_domain_id=candidate.privacy_domain_id
     AND evidence.operation_id=candidate.consumed_operation_id AND evidence.candidate_digest=candidate.candidate_digest
     AND evidence.principal_id=p.maker_principal_id AND evidence.approval_request_id=p.create_approval_id
   JOIN control.idempotency_record receipt ON receipt.participant_id=candidate.participant_id AND receipt.privacy_domain_id=candidate.privacy_domain_id
     AND receipt.operation_id=candidate.consumed_operation_id AND receipt.terminal_state='COMMITTED'
     AND receipt.result_payload->>'id'=p.envelope_id::text
     AND receipt.result_payload->>'semanticDigest'='sha256:'||encode(p.proposal_digest,'hex')
   WHERE candidate.participant_id=p.participant_id AND candidate.privacy_domain_id=p.privacy_domain_id
     AND candidate.mutation_candidate_id=p.create_candidate_id AND candidate.consumed_operation_id=p.create_operation_id
     AND candidate.state='CONSUMED' AND candidate.catalog_operation_id='ID-OP-ENVELOPE-CREATE'
     AND candidate.resource_id=p.envelope_id AND candidate.maker_principal_id=p.maker_principal_id
     AND candidate.candidate_document->>'schema'='pc.identity.authority-envelope-proposal'
     AND candidate.candidate_document->>'envelopeId'=p.envelope_id::text
     AND candidate.candidate_document->>'participantId'=p.target_participant_id::text
     AND candidate.maker_session_id::text=p.issuer_authority#>>'{binding,sessionId}'
     AND candidate.maker_session_epoch::text=p.issuer_authority#>>'{binding,sessionEpoch}'
     AND candidate.maker_participant_epoch::text=p.issuer_authority#>>'{binding,participantEpoch}'
     AND candidate.maker_principal_epoch::text=p.issuer_authority#>>'{binding,principalEpoch}'
     AND candidate.maker_assignment_id::text=p.issuer_authority#>>'{binding,assignmentId}'
     AND candidate.maker_assignment_row_version::text=p.issuer_authority#>>'{binding,assignmentVersion}'
     AND candidate.maker_authority_envelope_id::text=p.issuer_authority#>>'{binding,authorityEnvelopeId}'
     AND candidate.maker_authority_epoch::text=p.issuer_authority#>>'{binding,authorityEpoch}'
     AND candidate.maker_delegation_epoch::text=p.issuer_authority#>>'{binding,delegationEpoch}') INTO valid_source;
 IF NOT coalesce(valid_source,false) THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-CREATE-PROVENANCE'; END IF;
 IF p.state<>'DRAFT' THEN
  SELECT EXISTS(SELECT 1 FROM control.approval_request request
    JOIN control.idempotency_record receipt ON receipt.participant_id=request.participant_id AND receipt.privacy_domain_id=request.privacy_domain_id
      AND receipt.operation_id=p.submission_operation_id AND receipt.input_digest=p.submission_intent_digest
      AND receipt.action_intent_id='ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1' AND receipt.terminal_state='COMMITTED'
      AND receipt.principal_id=p.maker_principal_id AND receipt.result_payload->>'resourceRef'='urn:openpc:resource:'||request.approval_request_id::text
    JOIN control.mfa_challenge challenge ON challenge.participant_id=request.participant_id AND challenge.principal_id=p.maker_principal_id
      AND challenge.mfa_challenge_id=(p.submission_maker->>'stepUpChallengeId')::uuid
      AND challenge.session_id=(p.submission_maker#>>'{authority,sessionId}')::uuid
      AND challenge.action_intent_id='ACT-APPROVAL_REQUESTS_CREATE_RESOURCE-V1' AND challenge.resource_digest=p.submission_intent_digest
      AND challenge.resource_id=p.envelope_id::text
      AND challenge.used_operation_id=p.submission_operation_id AND challenge.used_at IS NOT NULL
      AND challenge.used_at>=challenge.consumed_at AND challenge.used_at<challenge.expires_at
      AND challenge.used_at<challenge.consumed_at+interval '5 minutes'
    JOIN control.mutation_evidence verification ON verification.participant_id=challenge.participant_id
      AND verification.privacy_domain_id=p.privacy_domain_id AND verification.principal_id=p.maker_principal_id
      AND verification.mfa_challenge_id=challenge.mfa_challenge_id AND verification.catalog_operation_id='ID-OP-WEBAUTHN-VERIFY'
      AND verification.evidence_digest=decode(substr(p.submission_maker->>'stepUpEvidenceDigest',8),'hex')
      AND verification.signer_credential_id=(p.submission_maker->>'signerCredentialId')::uuid
      AND challenge.signer_credential_id=verification.signer_credential_id
      AND challenge.signer_credential_epoch::text=p.submission_maker->>'signerCredentialEpoch'
    WHERE request.participant_id=p.participant_id AND request.privacy_domain_id=p.privacy_domain_id
      AND request.approval_request_id=p.submission_approval_id AND request.subject_type='AUTHORITY_ENVELOPE'
      AND request.subject_id=p.envelope_id AND request.subject_digest=p.proposal_digest AND request.subject_version=1
      AND request.action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' AND request.maker_principal_id=p.maker_principal_id
      AND p.submission_maker->'authority'=p.issuer_authority->'binding'
      AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=p.participant_id AND event.privacy_domain_id=p.privacy_domain_id
        AND event.aggregate_type='authority-envelope' AND event.aggregate_id=p.envelope_id
        AND event.event_type='openpc.identity.authority-envelope.submitted.v1' AND event.payload_digest=verification.evidence_digest
        AND event.payload_cbor=verification.evidence_cbor AND event.cose_sign1=verification.cose_sign1)
      AND ((p.state='SUBMITTED' AND request.state='OPEN') OR (p.state='APPROVED' AND request.state='APPROVED'))) INTO valid_source;
  IF NOT coalesce(valid_source,false) THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SUBMISSION-PROVENANCE'; END IF;
 END IF;
 IF p.state='APPROVED' THEN
  SELECT EXISTS(SELECT 1 FROM control.approval_decision_record decision
    JOIN control.mfa_challenge challenge ON challenge.participant_id=decision.participant_id AND challenge.mfa_challenge_id=decision.mfa_challenge_id
      AND challenge.principal_id=decision.approver_principal_id AND challenge.action_intent_id='ACT-POLICY_APPROVE_REQUEST-V1'
      AND challenge.session_id=decision.approver_session_id
      AND challenge.resource_digest=decision.decision_digest AND challenge.used_at IS NOT NULL
      AND challenge.resource_id=decision.approval_request_id::text
      AND challenge.signer_credential_id=decision.signer_credential_id
      AND challenge.signer_credential_epoch=decision.signer_credential_epoch
      AND challenge.used_at>=challenge.consumed_at AND challenge.used_at<challenge.expires_at
      AND challenge.used_at<challenge.consumed_at+interval '5 minutes'
    JOIN control.mutation_evidence verification ON verification.participant_id=decision.participant_id
      AND verification.privacy_domain_id=decision.privacy_domain_id AND verification.principal_id=decision.approver_principal_id
      AND verification.mfa_challenge_id=challenge.mfa_challenge_id AND verification.catalog_operation_id='ID-OP-WEBAUTHN-VERIFY'
      AND verification.bound_participant_epoch=decision.approver_participant_epoch
      AND verification.bound_principal_epoch=decision.approver_principal_epoch
      AND verification.signer_credential_id=decision.signer_credential_id
      AND verification.evidence_cbor=decision.evidence_cbor AND verification.cose_sign1=decision.cose_sign1
    WHERE decision.participant_id=p.participant_id AND decision.privacy_domain_id=p.privacy_domain_id
      AND decision.approval_request_id=p.submission_approval_id AND decision.decision='APPROVE'
      AND decision.candidate_digest=p.proposal_digest AND decision.aggregate_version=1
      AND decision.approver_principal_id<>p.maker_principal_id
      AND decision.approver_principal_id::text=p.submission_checker#>>'{authority,principalId}'
      AND decision.participant_id::text=p.submission_checker#>>'{authority,participantId}'
      AND decision.approver_participant_epoch::text=p.submission_checker#>>'{authority,participantEpoch}'
      AND decision.approver_principal_epoch::text=p.submission_checker#>>'{authority,principalEpoch}'
      AND decision.approver_session_id::text=p.submission_checker#>>'{authority,sessionId}'
      AND decision.approver_session_epoch::text=p.submission_checker#>>'{authority,sessionEpoch}'
      AND decision.approver_assignment_id::text=p.submission_checker#>>'{authority,assignmentId}'
      AND decision.approver_assignment_row_version::text=p.submission_checker#>>'{authority,assignmentVersion}'
      AND decision.approver_authority_envelope_id::text=p.submission_checker#>>'{authority,authorityEnvelopeId}'
      AND decision.approver_envelope_epoch::text=p.submission_checker#>>'{authority,authorityEpoch}'
      AND decision.approver_delegation_epoch::text=p.submission_checker#>>'{authority,delegationEpoch}'
      AND p.submission_checker_authority->'binding'=p.submission_checker->'authority'
      AND p.submission_checker_authority#>'{durable,grant}' @> jsonb_build_object(
        'principalId',decision.approver_principal_id::text,'participantEpoch',decision.approver_participant_epoch::text,
        'principalEpoch',decision.approver_principal_epoch::text,'assignmentId',decision.approver_assignment_id::text,
        'assignmentRowVersion',decision.approver_assignment_row_version::text,'authorityEnvelopeId',decision.approver_authority_envelope_id::text,
        'authorityEpoch',decision.approver_envelope_epoch::text,'delegationEpoch',decision.approver_delegation_epoch::text,
        'privacyDomainId',p.privacy_domain_id::text,'actionIntentId','ACT-PARTICIPANTS_UPDATE_RESOURCE-V1','resourceId',p.envelope_id::text)
      AND decision.mfa_challenge_id::text=p.submission_checker->>'stepUpChallengeId'
      AND decision.mfa_challenge_id::text<>p.submission_maker->>'stepUpChallengeId'
      AND decision.signer_credential_id::text=p.submission_checker->>'signerCredentialId'
      AND decision.signer_credential_epoch::text=p.submission_checker->>'signerCredentialEpoch'
      AND sha256(decision.evidence_cbor)=decode(substr(p.submission_checker->>'stepUpEvidenceDigest',8),'hex')
      AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=p.participant_id AND event.privacy_domain_id=p.privacy_domain_id
        AND event.aggregate_type='authority-envelope' AND event.aggregate_id=p.envelope_id
        AND event.event_type='openpc.identity.authority-envelope.approved.v1' AND event.payload_digest=sha256(decision.evidence_cbor)
        AND event.payload_cbor=decision.evidence_cbor AND event.cose_sign1=decision.cose_sign1)) INTO valid_source;
	  IF NOT coalesce(valid_source,false) THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-APPROVAL-PROVENANCE'; END IF;
	 END IF;
	 IF p.state='APPROVED' THEN
	  SELECT activation.cose_sign1 INTO activation_cose
	    FROM control.identity_envelope_activation activation
	   WHERE activation.participant_id=p.participant_id AND activation.privacy_domain_id=p.privacy_domain_id
	     AND activation.envelope_id=p.envelope_id AND activation.operation_id=operation
	     AND activation.state='COMMITTED' AND activation.row_version=4;
	 END IF;
	 PERFORM openpc.set_request_context('PARTICIPANT',p.target_participant_id,NULL,operation,action,false);
 SELECT * INTO envelope FROM control.authority_envelope WHERE participant_id=p.target_participant_id AND authority_envelope_id=p.envelope_id;
 IF envelope.representation IS DISTINCT FROM 'TYPED_V1' OR envelope.issuer_participant_id IS DISTINCT FROM p.participant_id
   OR envelope.issuer_privacy_domain_id IS DISTINCT FROM p.privacy_domain_id
	 OR envelope.maker_principal_id IS DISTINCT FROM p.maker_principal_id OR envelope.semantic_cbor IS DISTINCT FROM p.proposal_cbor
	 OR envelope.semantic_digest IS DISTINCT FROM p.proposal_digest
	 OR NOT (
	   (envelope.state::text=p.state AND envelope.row_version=p.row_version)
	   OR (p.state='APPROVED' AND envelope.state='ACTIVE' AND envelope.row_version=p.row_version+1
	     AND octet_length(envelope.cose_sign1)>0
	     AND activation_cose=envelope.cose_sign1)
	 )
	 OR (p.state='APPROVED' AND envelope.checker_principal_id::text IS DISTINCT FROM p.submission_checker#>>'{authority,principalId}')
   THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-TARGET-BINDING'; END IF;
 PERFORM openpc.set_request_context(original_mode,original_participant,original_privacy,operation,action,original_privacy IS NOT NULL);
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS identity_envelope_proposal_provenance ON control.identity_envelope_proposal;
CREATE CONSTRAINT TRIGGER identity_envelope_proposal_provenance AFTER INSERT OR UPDATE ON control.identity_envelope_proposal
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_identity_envelope_proposal();
DROP TRIGGER IF EXISTS identity_envelope_target_provenance ON control.authority_envelope;
CREATE CONSTRAINT TRIGGER identity_envelope_target_provenance AFTER INSERT OR UPDATE ON control.authority_envelope
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_identity_envelope_proposal();



-- Request-cache retention is separate from business authority. A reservation
-- cannot extend an unconsumed candidate or approval into its first dispatch.
-- Historical observation never calls this current-use predicate.
CREATE OR REPLACE FUNCTION openpc.identity_envelope_activation_intent_current(
 p_participant uuid,p_privacy uuid,p_candidate uuid,p_approval uuid)
RETURNS boolean LANGUAGE sql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM control.mutation_candidate c
  JOIN control.approval_request a ON a.participant_id=c.participant_id AND a.privacy_domain_id=c.privacy_domain_id
   AND a.subject_type='CONFIGURATION_CANDIDATE' AND a.subject_id=c.mutation_candidate_id
   AND a.subject_digest=c.candidate_digest AND a.subject_version=c.expected_revision
   AND a.action_intent_id=c.action_intent_id AND a.maker_principal_id=c.maker_principal_id
  WHERE c.participant_id=p_participant AND c.privacy_domain_id=p_privacy
   AND c.mutation_candidate_id=p_candidate AND a.approval_request_id=p_approval
   AND c.action_intent_id='ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1' AND c.catalog_operation_id='ID-OP-ENVELOPE-ACTIVATE'
   AND c.operation_class='ACTIVATE' AND c.resource_type='participant' AND c.expected_revision=3
   AND c.candidate_document=jsonb_build_object('envelopeId',c.resource_id::text)
   AND c.state='APPROVED' AND c.consumed_operation_id IS NULL AND c.expires_at>clock_timestamp()
   AND a.state='APPROVED' AND a.expires_at>clock_timestamp()
   AND NOT EXISTS(SELECT 1 FROM control.mutation_candidate successor
    WHERE successor.participant_id=c.participant_id AND successor.privacy_domain_id=c.privacy_domain_id
     AND successor.predecessor_candidate_id=c.mutation_candidate_id))
$$;
CREATE OR REPLACE FUNCTION openpc.identity_envelope_authority_wire(p_value jsonb)
RETURNS jsonb LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('1',openpc.business_uuid((p_value->>'participantId')::uuid),'2',to_jsonb((p_value->>'participantEpoch')::numeric),'3',openpc.business_uuid((p_value->>'principalId')::uuid),'4',to_jsonb((p_value->>'principalEpoch')::numeric),'5',openpc.business_uuid((p_value->>'sessionId')::uuid),'6',to_jsonb((p_value->>'sessionEpoch')::numeric),'7',openpc.business_uuid((p_value->>'assignmentId')::uuid),'8',to_jsonb((p_value->>'assignmentVersion')::numeric),'9',openpc.business_uuid((p_value->>'authorityEnvelopeId')::uuid),'10',to_jsonb((p_value->>'authorityEpoch')::numeric),'11',to_jsonb((p_value->>'delegationEpoch')::numeric),'12',to_jsonb(p_value->>'roleId'),'13',to_jsonb((p_value->>'roleVersion')::numeric),'14',openpc.business_bytes(decode(substr(p_value->>'roleDigest',8),'hex')),'15',openpc.business_bytes(decode(substr(p_value->>'authorityDigest',8),'hex')))
$$;
CREATE OR REPLACE FUNCTION openpc.identity_envelope_actor_wire(p_value jsonb)
RETURNS jsonb LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('1',openpc.identity_envelope_authority_wire(p_value->'authority'),
  '2',openpc.business_uuid((p_value->>'stepUpChallengeId')::uuid),
  '3',openpc.business_bytes(decode(substr(p_value->>'stepUpEvidenceDigest',8),'hex')),
  '4',openpc.business_uuid((p_value->>'signerCredentialId')::uuid),
  '5',(p_value->>'signerCredentialEpoch')::numeric)
$$;

CREATE OR REPLACE FUNCTION openpc.identity_envelope_activation_authority_current(
 p_participant uuid,p_privacy uuid,p_captured jsonb,p_action text,p_resource uuid,p_live_session boolean)
RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE b jsonb:=p_captured->'binding'; d jsonb:=p_captured->'durable';
 a control.assignment%ROWTYPE; e control.authority_envelope%ROWTYPE; r control.authority_role%ROWTYPE;
 pr control.principal%ROWTYPE; privacy control.privacy_domain%ROWTYPE; role_document jsonb; expected jsonb;
BEGIN
 IF b->>'participantId' IS DISTINCT FROM p_participant::text
  OR d#>>'{grant,privacyDomainId}' IS DISTINCT FROM p_privacy::text
  OR d#>>'{grant,actionIntentId}' IS DISTINCT FROM p_action
  OR d#>>'{grant,resourceId}' IS DISTINCT FROM p_resource::text THEN RETURN false; END IF;
 SELECT * INTO a FROM control.assignment WHERE participant_id=p_participant
  AND assignment_id=(b->>'assignmentId')::uuid;
 SELECT * INTO e FROM control.authority_envelope WHERE participant_id=p_participant
  AND authority_envelope_id=(b->>'authorityEnvelopeId')::uuid;
 SELECT * INTO r FROM control.authority_role WHERE participant_id=p_participant AND role_id=b->>'roleId';
 SELECT * INTO pr FROM control.principal WHERE participant_id=p_participant
  AND principal_id=(b->>'principalId')::uuid;
 SELECT * INTO privacy FROM control.privacy_domain WHERE participant_id=p_participant AND privacy_domain_id=p_privacy;
 IF a.assignment_id IS NULL OR e.authority_envelope_id IS NULL OR r.authority_role_id IS NULL
  OR pr.principal_id IS NULL OR privacy.privacy_domain_id IS NULL
  OR a.principal_id IS DISTINCT FROM pr.principal_id OR a.authority_envelope_id IS DISTINCT FROM e.authority_envelope_id
  OR a.role_id IS DISTINCT FROM r.role_id OR a.row_version::text IS DISTINCT FROM b->>'assignmentVersion'
  OR a.delegation_epoch::text IS DISTINCT FROM b->>'delegationEpoch' OR a.state<>'ACTIVE'
  OR NOT (a.valid_during @> clock_timestamp()) OR NOT a.maker_checker_required
  OR NOT (p_action=ANY(a.action_intent_ids)) OR NOT (p_privacy::text=ANY(a.privacy_domain_ids))
  OR NOT openpc.administration_resource_permits(a.resource_ids,p_resource::text,p_action,p_participant,pr.principal_id,(b->>'sessionId')::uuid,e.authority_envelope_id)
  OR NOT openpc.assignment_group_permits(a.participant_id,a.authority_group_id,a.principal_id,a.valid_during)
  OR e.state<>'ACTIVE' OR e.valid_from>clock_timestamp() OR (e.valid_until IS NOT NULL AND e.valid_until<=clock_timestamp())
  OR NOT ((e.representation<>'RECOVERY_V1' or openpc.platform_recovery_envelope_current(e.authority_envelope_id)) and (e.platform_context_id is null or exists(
    select 1 from control.platform_context current_root
    where current_root.platform_context_id=e.platform_context_id
      and current_root.state='ACTIVE'
      and current_root.authority_epoch=e.platform_authority_epoch
      )))
  OR e.authority_epoch::text IS DISTINCT FROM b->>'authorityEpoch' OR NOT e.maker_checker_required
  OR NOT (p_action=ANY(e.action_intent_ids)) OR NOT (p_privacy::text=ANY(e.privacy_domain_ids))
  OR NOT openpc.administration_resource_permits(e.resource_ids,p_resource::text,p_action,p_participant,pr.principal_id,(b->>'sessionId')::uuid,e.authority_envelope_id)
  OR NOT EXISTS(SELECT 1 FROM control.action_intent action WHERE action.action_intent_id=p_action
    AND action.risk_class=ANY(a.risk_classes) AND action.risk_class=ANY(e.risk_classes))
  OR NOT (e.principal_id=pr.principal_id OR (e.representation='TYPED_V1' AND e.principal_id IS NULL))
  OR r.state<>'ACTIVE' OR r.row_version::text IS DISTINCT FROM b->>'roleVersion' OR NOT (p_action=ANY(r.action_intent_ids))
  OR pr.state<>'ACTIVE' OR pr.kind<>'PLATFORM_OPERATOR' OR pr.authority_epoch::text IS DISTINCT FROM b->>'principalEpoch'
  OR privacy.state<>'ACTIVE'
  OR NOT EXISTS(SELECT 1 FROM control.participant p WHERE p.participant_id=p_participant
    AND p.state='ACTIVE' AND p.authority_epoch::text=b->>'participantEpoch')
 THEN RETURN false; END IF;
 expected:=jsonb_build_object('principalId',b->'principalId','participantEpoch',b->'participantEpoch',
  'principalEpoch',b->'principalEpoch','assignmentId',b->'assignmentId','assignmentRowVersion',b->'assignmentVersion',
  'authorityEnvelopeId',b->'authorityEnvelopeId','authorityEpoch',b->'authorityEpoch','delegationEpoch',b->'delegationEpoch',
  'privacyDomainId',p_privacy::text,'actionIntentId',p_action,'resourceId',p_resource::text);
 IF (d->'grant')-'catalogOperationId' IS DISTINCT FROM expected THEN RETURN false; END IF;
 expected:=jsonb_build_object('path',jsonb_build_object('delegationIds','[]'::jsonb,
   'principalIds',jsonb_build_array(pr.principal_id::text),'roleId',r.authority_role_id::text),
  'principals',jsonb_build_array(jsonb_build_array(pr.principal_id::text,pr.authority_epoch::text)),
  'privacy',privacy.row_version::text,'role',r.row_version::text,'delegations',NULL);
 IF d->'dependencies' IS DISTINCT FROM expected THEN RETURN false; END IF;
 role_document:=jsonb_build_object('roleId',r.role_id,'version',r.row_version::text,'actions',to_jsonb(r.action_intent_ids),
  'origin',r.origin,'createdByPrincipalId',r.created_by_principal_id::text,'creatorParticipantId',r.creator_participant_id::text,
  'bootstrapMandateId',r.bootstrap_mandate_id::text,'bootstrapPlatformParticipantId',r.bootstrap_platform_participant_id::text);
 IF b->>'roleDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
  jsonb_build_object('domain','pc.identity.envelope-role-binding.v1','participantId',p_participant::text,'role',role_document)),'UTF8')),'hex')
  OR b->>'authorityDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
  jsonb_build_object('domain','pc.identity.envelope-authority-binding.v1','binding',b-'authorityDigest',
   'authority',(d->'grant')||jsonb_build_object('sessionId',b->'sessionId','sessionEpoch',b->'sessionEpoch'),'durable',d)),'UTF8')),'hex')
 THEN RETURN false; END IF;
 IF p_live_session AND NOT EXISTS(SELECT 1 FROM control.session s WHERE s.participant_id=p_participant
  AND s.session_id=(b->>'sessionId')::uuid AND s.principal_id=pr.principal_id AND s.context_mode='PLATFORM' AND s.privacy_domain_id IS NULL
  AND s.state='ACTIVE' AND s.session_epoch::text=b->>'sessionEpoch' AND s.participant_epoch::text=b->>'participantEpoch'
  AND s.authority_epoch::text=b->>'principalEpoch' AND s.delegation_epoch::text=b->>'delegationEpoch'
  AND s.idle_expires_at>clock_timestamp() AND s.absolute_expires_at>clock_timestamp())
 THEN RETURN false; END IF;
 RETURN true;
END $$;

CREATE OR REPLACE FUNCTION openpc.guard_identity_envelope_activation()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE p control.identity_envelope_proposal%ROWTYPE; c control.mutation_candidate%ROWTYPE;
 a control.approval_request%ROWTYPE; d control.approval_decision_record%ROWTYPE;
 i control.idempotency_record%ROWTYPE; k control.business_signing_key%ROWTYPE;
 payload jsonb; proposal jsonb; maker jsonb; checker jsonb; expected jsonb;
 submission_digest bytea; outer_cose jsonb; header jsonb; source_envelope uuid; now_ns numeric;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-HISTORY'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR NEW.operation_id IS DISTINCT FROM openpc.current_operation_id()
  OR openpc.current_action_intent_id()<>'ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-CONTEXT'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-'state'-'observation'-'cose_sign1'-'dispatched_at'-'observed_at'-'committed_at'-'row_version')
   IS DISTINCT FROM (to_jsonb(OLD)-'state'-'observation'-'cose_sign1'-'dispatched_at'-'observed_at'-'committed_at'-'row_version')
   OR NEW.row_version<>OLD.row_version+1
   OR NOT ((OLD.state='PREPARED' AND NEW.state='DISPATCHED')
    OR (OLD.state='DISPATCHED' AND NEW.state='OBSERVED')
    OR (OLD.state='OBSERVED' AND NEW.state='COMMITTED'))
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-PHASE'; END IF;
  IF OLD.state='DISPATCHED' AND NEW.dispatched_at IS DISTINCT FROM OLD.dispatched_at
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-DISPATCH'; END IF;
 ELSE
  IF NEW.state<>'PREPARED' OR NEW.row_version<>1
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-INITIAL'; END IF;
 END IF;
 payload:=openpc.business_cbor(NEW.payload_cbor);
 SELECT * INTO STRICT p FROM control.identity_envelope_proposal WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND envelope_id=NEW.envelope_id;
 proposal:=openpc.business_cbor(p.proposal_cbor);
 IF p.state<>'APPROVED' OR p.row_version<>3 OR p.target_participant_id<>NEW.participant_id
  OR p.proposal_digest<>NEW.proposal_digest OR proposal->>'7'<>'1'
  OR payload->'0' IS DISTINCT FROM openpc.business_bytes(decode('6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5','hex'))
  OR payload->'1' IS DISTINCT FROM openpc.business_bytes(p.proposal_cbor)
  OR payload->'2' IS DISTINCT FROM openpc.business_bytes(p.proposal_digest)
  OR payload->>'6' IS DISTINCT FROM NEW.reserved_at_ns::text
  OR NEW.reserved_at_ns>floor(extract(epoch FROM clock_timestamp())*1000000)*1000
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-PROPOSAL'; END IF;
 SELECT * INTO STRICT i FROM control.idempotency_record WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND principal_id=NEW.principal_id
  AND action_intent_id='ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1' AND catalog_operation_id='ID-OP-ENVELOPE-ACTIVATE'
  AND idempotency_key=NEW.idempotency_key AND idempotency_record_id=NEW.idempotency_record_id
  AND operation_id=NEW.operation_id AND input_digest=NEW.candidate_digest AND expected_aggregate_version=3
  AND terminal_state IS NULL;
 SELECT * INTO STRICT c FROM control.mutation_candidate WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND mutation_candidate_id=NEW.candidate_id
  AND resource_id=NEW.envelope_id AND expected_revision=3 AND (NEW.state='OBSERVED' OR state='APPROVED')
  AND maker_principal_id=NEW.principal_id AND candidate_digest=NEW.candidate_digest
  AND action_intent_id='ACT-PARTICIPANT_ACTIVATE_CONTEXT-V1' AND catalog_operation_id='ID-OP-ENVELOPE-ACTIVATE'
  AND candidate_document=jsonb_build_object('envelopeId',NEW.envelope_id::text);
 SELECT * INTO STRICT a FROM control.approval_request WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND approval_request_id=NEW.approval_request_id
  AND (NEW.state='OBSERVED' OR state='APPROVED') AND subject_type='CONFIGURATION_CANDIDATE' AND subject_id=c.mutation_candidate_id
  AND subject_digest=c.candidate_digest AND subject_version=3 AND maker_principal_id=NEW.principal_id
  AND action_intent_id=c.action_intent_id;
 SELECT * INTO STRICT d FROM control.approval_decision_record WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND approval_request_id=a.approval_request_id
  AND decision='APPROVE' AND candidate_digest=c.candidate_digest AND aggregate_version=3
  AND approver_principal_id<>NEW.principal_id;
 SELECT decision.decision_digest INTO STRICT submission_digest FROM control.approval_decision_record decision
  JOIN control.approval_request approved ON approved.participant_id=decision.participant_id
   AND approved.privacy_domain_id=decision.privacy_domain_id AND approved.approval_request_id=decision.approval_request_id
   AND approved.subject_type='AUTHORITY_ENVELOPE' AND approved.subject_id=p.envelope_id
   AND approved.subject_digest=p.proposal_digest AND approved.subject_version=1 AND approved.state='APPROVED'
  WHERE decision.participant_id=p.participant_id AND decision.privacy_domain_id=p.privacy_domain_id
   AND decision.approval_request_id=p.submission_approval_id AND decision.decision='APPROVE'
   AND decision.candidate_digest=p.proposal_digest AND decision.aggregate_version=1
   AND decision.approver_principal_id::text=p.submission_checker#>>'{authority,principalId}';
 SELECT jsonb_build_object('authority',NEW.maker_authority->'binding','stepUpChallengeId',challenge.mfa_challenge_id::text,
   'stepUpEvidenceDigest','sha256:'||encode(verification.evidence_digest,'hex'),
   'signerCredentialId',verification.signer_credential_id::text,'signerCredentialEpoch',challenge.signer_credential_epoch::text)
 INTO STRICT maker FROM control.mfa_challenge challenge JOIN control.mutation_evidence verification
  ON verification.participant_id=challenge.participant_id AND verification.privacy_domain_id=NEW.privacy_domain_id
   AND verification.principal_id=challenge.principal_id AND verification.mfa_challenge_id=challenge.mfa_challenge_id
   AND verification.catalog_operation_id='ID-OP-WEBAUTHN-VERIFY'
   AND verification.webauthn_assertion_binding_digest=i.webauthn_assertion_binding_digest
   AND verification.evidence_digest=sha256(verification.evidence_cbor)
   AND verification.signer_credential_id=challenge.signer_credential_id
 WHERE challenge.participant_id=NEW.participant_id AND challenge.principal_id=NEW.principal_id
  AND challenge.mfa_challenge_id=NEW.maker_challenge_id AND challenge.resource_id=NEW.envelope_id::text
  AND challenge.resource_digest=NEW.candidate_digest AND challenge.action_intent_id=c.action_intent_id
  AND challenge.session_id=c.maker_session_id AND challenge.used_operation_id=NEW.operation_id
  AND challenge.used_at IS NOT NULL AND challenge.used_at>=challenge.consumed_at
  AND challenge.used_at<challenge.expires_at AND challenge.used_at<challenge.consumed_at+interval '5 minutes';
 checker:=jsonb_build_object('authority',NEW.checker_authority->'binding','stepUpChallengeId',d.mfa_challenge_id::text,
  'stepUpEvidenceDigest','sha256:'||encode(sha256(d.evidence_cbor),'hex'),'signerCredentialId',d.signer_credential_id::text,
  'signerCredentialEpoch',d.signer_credential_epoch::text);
 IF NEW.maker_authority#>>'{binding,principalId}' IS DISTINCT FROM c.maker_principal_id::text
  OR NEW.maker_authority#>>'{binding,sessionId}' IS DISTINCT FROM c.maker_session_id::text
  OR NEW.maker_authority#>>'{binding,sessionEpoch}' IS DISTINCT FROM c.maker_session_epoch::text
  OR NEW.maker_authority#>>'{binding,participantEpoch}' IS DISTINCT FROM c.maker_participant_epoch::text
  OR NEW.maker_authority#>>'{binding,principalEpoch}' IS DISTINCT FROM c.maker_principal_epoch::text
  OR NEW.maker_authority#>>'{binding,authorityEpoch}' IS DISTINCT FROM c.maker_authority_epoch::text
  OR NEW.maker_authority#>>'{binding,delegationEpoch}' IS DISTINCT FROM c.maker_delegation_epoch::text
  OR NEW.maker_authority#>>'{binding,assignmentId}' IS DISTINCT FROM c.maker_assignment_id::text
  OR NEW.maker_authority#>>'{binding,assignmentVersion}' IS DISTINCT FROM c.maker_assignment_row_version::text
  OR NEW.maker_authority#>>'{binding,authorityEnvelopeId}' IS DISTINCT FROM c.maker_authority_envelope_id::text
  OR NEW.checker_authority#>>'{binding,principalId}' IS DISTINCT FROM d.approver_principal_id::text
  OR NEW.checker_authority#>>'{binding,sessionId}' IS DISTINCT FROM d.approver_session_id::text
  OR NEW.checker_authority#>>'{binding,sessionEpoch}' IS DISTINCT FROM d.approver_session_epoch::text
  OR NEW.checker_authority#>>'{binding,participantEpoch}' IS DISTINCT FROM d.approver_participant_epoch::text
  OR NEW.checker_authority#>>'{binding,principalEpoch}' IS DISTINCT FROM d.approver_principal_epoch::text
  OR NEW.checker_authority#>>'{binding,authorityEpoch}' IS DISTINCT FROM d.approver_envelope_epoch::text
  OR NEW.checker_authority#>>'{binding,delegationEpoch}' IS DISTINCT FROM d.approver_delegation_epoch::text
  OR NEW.checker_authority#>>'{binding,assignmentId}' IS DISTINCT FROM d.approver_assignment_id::text
  OR NEW.checker_authority#>>'{binding,assignmentVersion}' IS DISTINCT FROM d.approver_assignment_row_version::text
  OR NEW.checker_authority#>>'{binding,authorityEnvelopeId}' IS DISTINCT FROM d.approver_authority_envelope_id::text
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-ACTOR'; END IF;
 expected:=jsonb_build_object('1',openpc.business_uuid(p.submission_operation_id),'2',openpc.business_uuid(p.envelope_id),
  '3',openpc.business_bytes(p.proposal_digest),'4',openpc.business_uuid(p.submission_approval_id),
  '5',openpc.business_bytes(submission_digest),'6',2,'7',3,
  '8',openpc.identity_envelope_actor_wire(p.submission_maker),'9',openpc.identity_envelope_actor_wire(p.submission_checker));
 IF payload->'3' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-SUBMISSION'; END IF;
 expected:=jsonb_build_object('domain','pc.identity.authority-envelope-activation-idempotency.v1',
  'participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,'envelopeId',NEW.envelope_id::text,
  'operationId',NEW.operation_id::text,'actionIntentId',c.action_intent_id,'catalogOperationId',c.catalog_operation_id,
  'candidateDigest','sha256:'||encode(c.candidate_digest,'hex'),'expectedApprovedVersion','3',
  'recordId',i.idempotency_record_id::text,'key',i.idempotency_key,'principalId',i.principal_id::text,
  'assertionBindingDigest','sha256:'||encode(i.webauthn_assertion_binding_digest,'hex'));
 expected:=jsonb_build_object('1',openpc.business_uuid(NEW.operation_id),'2',openpc.business_uuid(c.mutation_candidate_id),
  '3',openpc.business_bytes(c.candidate_digest),'4',openpc.business_uuid(a.approval_request_id),
  '5',openpc.business_bytes(d.decision_digest),'6',3,'7',4,
  '8',openpc.business_bytes(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8'))),
  '9',1,'10',1,
  '11',openpc.identity_envelope_actor_wire(maker),'12',openpc.identity_envelope_actor_wire(checker));
 IF payload->'4' IS DISTINCT FROM expected
  OR (SELECT count(DISTINCT value) FROM (VALUES (p.submission_maker->>'stepUpChallengeId'),
   (p.submission_checker->>'stepUpChallengeId'),(maker->>'stepUpChallengeId'),(checker->>'stepUpChallengeId')) proof(value))<>4
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-INTENT'; END IF;
 -- Observation resolves the immutable original key, even after selection or
 -- lifecycle changes. Current selection is a separate pre-dispatch fence.
 SELECT key.* INTO STRICT k FROM control.business_signing_key key
  WHERE key.participant_id=NEW.participant_id AND key.privacy_domain_id=NEW.privacy_domain_id
   AND key.environment_id=NEW.request->>'environmentId' AND key.signer_id=NEW.request->>'expectedFingerprint'
   AND key.signing_purpose_code=371;
 expected:=jsonb_build_object('1',k.environment_id,'2',openpc.business_uuid(k.participant_id),'3',openpc.business_uuid(k.privacy_domain_id),
  '4','pc.identity.authority-envelope.v1','5',1,'6',openpc.business_bytes(decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex')),
  '7',openpc.business_bytes(decode(substr(k.signer_id,8),'hex')),'8',k.secret_version,
  '9',openpc.business_uuid(k.workload_credential_id),'10',k.workload_credential_epoch,'11',openpc.business_bytes(k.trust_digest));
 IF payload->'5' IS DISTINCT FROM expected OR payload IS DISTINCT FROM jsonb_build_object('0',payload->'0','1',payload->'1',
  '2',payload->'2','3',payload->'3','4',payload->'4','5',expected,'6',NEW.reserved_at_ns)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-SIGNER'; END IF;
 expected:=jsonb_build_object('participantId',k.participant_id::text,'privacyDomainId',k.privacy_domain_id::text,
  'environmentId',k.environment_id,'workloadCredentialId',k.workload_credential_id::text,
  'workloadCredentialEpoch',k.workload_credential_epoch::text,'secretClass','SECRET-SIGNING-KEY','reference',k.secret_reference,
  'version',k.secret_version,'purpose','pc.cose.identity-authority-envelope.v1','purposeCode',371,'schemaId',24034,
  'schemaVersion',1,'schemaDefinitionDigest','sha256:6cf5c91789d9488014d3ec9445d5852c4aa686534305c6516d67210176ea3cc5',
  'profileId','pc.identity.authority-envelope.v1','profileVersion',1,'profileDigest','sha256:54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74',
  'trustContextDigest','sha256:'||encode(k.trust_digest,'hex'),'method','SIGN_AUTHORITY_ENVELOPE',
  'callerWorkloadCredentialId',NEW.request->'callerWorkloadCredentialId','attemptId',NEW.attempt_id::text,
  'operationId',NEW.operation_id::text,'expectedFingerprint',k.signer_id,'payloadHex',encode(NEW.payload_cbor,'hex'));
 IF NEW.request IS DISTINCT FROM expected OR NEW.request_digest<>sha256(convert_to('pc.identity.authority-envelope-provider-request.v1','UTF8')
  ||decode('00','hex')||convert_to(openpc.signing_canonical_json(expected),'UTF8'))
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-REQUEST'; END IF;
 IF NEW.state IN ('PREPARED','DISPATCHED') THEN
  now_ns:=floor(extract(epoch FROM clock_timestamp())*1000000)*1000;
  IF (NEW.state='PREPARED' AND i.expires_at<=clock_timestamp())
   OR NOT openpc.identity_envelope_activation_intent_current(NEW.participant_id,NEW.privacy_domain_id,
    NEW.candidate_id,NEW.approval_request_id)
   OR (proposal#>>'{8,3}')::numeric>now_ns OR (proposal#>>'{8,4}')::numeric<=now_ns
   OR (proposal#>>'{9,3}')::numeric>now_ns OR (proposal#>>'{9,4}')::numeric<=now_ns
   OR NOT EXISTS(SELECT 1 FROM control.participant target WHERE target.participant_id=NEW.participant_id
     AND target.state='ACTIVE' AND target.authority_epoch=(proposal->>'4')::numeric
     AND target.authority_epoch=(proposal->>'5')::numeric)
   OR NOT openpc.identity_envelope_activation_authority_current(NEW.participant_id,NEW.privacy_domain_id,
    NEW.maker_authority,c.action_intent_id,NEW.envelope_id,NEW.state='PREPARED')
   OR NOT openpc.identity_envelope_activation_authority_current(NEW.participant_id,NEW.privacy_domain_id,
    NEW.checker_authority,c.action_intent_id,NEW.envelope_id,NEW.state='PREPARED')
   OR NOT openpc.identity_envelope_activation_authority_current(NEW.participant_id,NEW.privacy_domain_id,
    p.issuer_authority,'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1',NEW.envelope_id,false)
   OR NOT openpc.identity_envelope_activation_authority_current(NEW.participant_id,NEW.privacy_domain_id,
    p.submission_checker_authority,'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1',NEW.envelope_id,false)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-CURRENT-AUTHORITY'; END IF;
  FOREACH source_envelope IN ARRAY ARRAY[
   (p.issuer_authority#>>'{binding,authorityEnvelopeId}')::uuid,
   (p.submission_checker_authority#>>'{binding,authorityEnvelopeId}')::uuid,
   (NEW.maker_authority#>>'{binding,authorityEnvelopeId}')::uuid,
   (NEW.checker_authority#>>'{binding,authorityEnvelopeId}')::uuid] LOOP
   IF NOT EXISTS(SELECT 1 FROM control.authority_envelope source
     JOIN control.platform_context platform ON platform.platform_context_id=source.platform_context_id
      AND platform.authority_epoch=source.platform_authority_epoch AND platform.state='ACTIVE'
     JOIN (select platform_context_id,platform_authority_epoch,
  owner_participant_id,installation_privacy_domain_id,admission_digest from control.platform_envelope_scope
  union all select platform_context_id,platform_authority_epoch,owner_participant_id,
    installation_privacy_domain_id,admission_digest from control.platform_envelope_scope_successor) root ON root.platform_context_id=platform.platform_context_id
      AND root.platform_authority_epoch=platform.authority_epoch AND root.owner_participant_id=NEW.participant_id
     WHERE source.participant_id=NEW.participant_id AND source.authority_envelope_id=source_envelope
      AND source.state='ACTIVE' AND platform.owner_participant_id=NEW.participant_id
      AND openpc.business_uuid(platform.platform_context_id)=proposal#>'{10,3}'
      AND ((to_jsonb(platform.authority_epoch)=proposal#>'{10,4}'
         AND openpc.business_bytes(root.admission_digest)=proposal#>'{10,5}')
        OR EXISTS(SELECT 1 FROM control.platform_scope_replacement pending
          JOIN control.mutation_candidate create_intent ON create_intent.participant_id=pending.participant_id
            AND create_intent.mutation_candidate_id=p.create_candidate_id AND create_intent.state='CONSUMED'
          CROSS JOIN LATERAL jsonb_array_elements(pending.candidate->'administrators') admin
          WHERE pending.platform_context_id=platform.platform_context_id AND pending.participant_id=NEW.participant_id
            AND pending.privacy_domain_id=NEW.privacy_domain_id AND pending.state='WITHDRAWING' AND pending.row_version=1
            AND pending.predecessor_epoch=platform.authority_epoch AND pending.expected_root_revision=platform.row_version
            AND to_jsonb(pending.predecessor_epoch+1)=proposal#>'{10,4}'
            AND openpc.business_bytes(pending.successor_digest)=proposal#>'{10,5}'
            AND create_intent.candidate_document->>'platformScopeReplacementId'=pending.replacement_id::text
            AND admin->>'envelopeId'=NEW.envelope_id::text
            AND create_intent.candidate_document->'usable'=admin->'usable'
            AND create_intent.candidate_document->'grantable'=admin->'grantable'
            AND openpc.platform_scope_document_value(proposal->'8')=admin->'usable'
            AND openpc.platform_scope_document_value(proposal->'9')=admin->'grantable')))

   THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-ROOT'; END IF;
  END LOOP;
  IF k.valid_from_ns>now_ns OR k.valid_until_ns<=now_ns
   OR NOT EXISTS(SELECT 1 FROM control.identity_envelope_signing_selection selection
     JOIN control.identity_envelope_signing_grant grant_row ON grant_row.participant_id=selection.participant_id
      AND grant_row.privacy_domain_id=selection.privacy_domain_id AND grant_row.signer_id=selection.signer_id
      AND grant_row.profile_digest=selection.profile_digest AND grant_row.signing_purpose_code=371
     WHERE selection.participant_id=k.participant_id AND selection.privacy_domain_id=k.privacy_domain_id
      AND selection.environment_id=k.environment_id AND selection.signer_id=k.signer_id AND selection.admission_version>0
      AND selection.profile_digest=decode('54d85c86019a4475f8207f375fa571565e9e6e0adb5b0bd55abc03e4beb81f74','hex'))
   OR NOT EXISTS(SELECT 1 FROM control.business_signing_key_state lifecycle
     JOIN control.credential credential ON credential.participant_id=lifecycle.participant_id
      AND credential.credential_id=k.workload_credential_id AND credential.kind='WORKLOAD_MTLS'
      AND credential.credential_epoch=k.workload_credential_epoch AND credential.state='ACTIVE'
      AND credential.valid_from<=clock_timestamp() AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
     JOIN control.principal principal ON principal.participant_id=credential.participant_id
      AND principal.principal_id=credential.principal_id AND principal.kind='WORKLOAD' AND principal.state='ACTIVE'
      AND principal.authority_epoch=k.envelope_workload_principal_epoch
     JOIN control.participant participant ON participant.participant_id=principal.participant_id
      AND participant.state='ACTIVE' AND participant.authority_epoch=k.envelope_workload_participant_epoch
     WHERE lifecycle.participant_id=k.participant_id AND lifecycle.privacy_domain_id=k.privacy_domain_id
      AND lifecycle.signer_id=k.signer_id AND lifecycle.state='ACTIVE')
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-CURRENT-KEY'; END IF;
 END IF;
 IF NEW.state='DISPATCHED' AND (NEW.dispatched_at<NEW.created_at OR NEW.dispatched_at>clock_timestamp())
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-DISPATCH'; END IF;
 IF NEW.state IN ('OBSERVED','COMMITTED') THEN
  expected:=(NEW.request-ARRAY['method','callerWorkloadCredentialId','attemptId','operationId','expectedFingerprint','payloadHex'])
   ||jsonb_build_object('algorithm','ES256','publicKeySpkiHex',encode(k.public_key_spki_der,'hex'),
    'fingerprint',k.signer_id,'validFromNs',k.valid_from_ns::text,'validUntilNs',k.valid_until_ns::text,'state','ACTIVE');
  IF NEW.observed_at<NEW.dispatched_at OR NEW.observed_at>clock_timestamp()
   OR NEW.observation->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text
   OR NEW.observation->>'operationId' IS DISTINCT FROM NEW.operation_id::text
   OR NEW.observation->>'requestDigest' IS DISTINCT FROM 'sha256:'||encode(NEW.request_digest,'hex')
   OR NEW.observation->>'method' IS DISTINCT FROM 'SIGN_AUTHORITY_ENVELOPE'
   OR NEW.observation->>'coseHex' IS DISTINCT FROM encode(NEW.cose_sign1,'hex')
   OR NEW.observation->'descriptor' IS DISTINCT FROM expected
   OR NEW.observation IS DISTINCT FROM jsonb_build_object('schemaVersion',1,'method','SIGN_AUTHORITY_ENVELOPE',
    'attemptId',NEW.attempt_id::text,'operationId',NEW.operation_id::text,
    'requestDigest','sha256:'||encode(NEW.request_digest,'hex'),'recordedAtNs',NEW.observation->'recordedAtNs',
    'descriptor',expected,'coseHex',encode(NEW.cose_sign1,'hex'))
   OR (NEW.observation->>'recordedAtNs')::numeric<NEW.reserved_at_ns
   OR (NEW.observation->>'recordedAtNs')::numeric>=k.valid_until_ns
   OR (NEW.observation->>'recordedAtNs')::numeric>floor(extract(epoch FROM NEW.observed_at)*1000000)*1000
   OR get_byte(NEW.cose_sign1,0)<>210
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-OBSERVATION'; END IF;
  outer_cose:=openpc.business_cbor_item(NEW.cose_sign1,1,0);
  IF (outer_cose->>'next')::integer<>octet_length(NEW.cose_sign1)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-COSE'; END IF;
  outer_cose:=outer_cose->'value';
  IF jsonb_typeof(outer_cose)<>'array' OR jsonb_array_length(outer_cose)<>4 OR outer_cose->1<>'{}'::jsonb
   OR outer_cose->2 IS DISTINCT FROM openpc.business_bytes(NEW.payload_cbor) OR length(outer_cose->3->>'bytes') IS DISTINCT FROM 128
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-COSE'; END IF;
  header:=openpc.business_cbor(decode(outer_cose->0->>'bytes','hex'));
  IF header IS DISTINCT FROM jsonb_build_object('1',-7,'2',jsonb_build_array(100,101,102,103),
   '3','application/pc+cbor','4',openpc.business_bytes(convert_to(k.signer_id,'UTF8')),'100',24034,'101',1,'102',371,'103',2)
  THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-COSE-CONTEXT'; END IF;
 END IF;
 IF NEW.state='COMMITTED' AND NOT EXISTS(
  SELECT 1 FROM control.authority_envelope envelope
   WHERE envelope.participant_id=NEW.participant_id
    AND envelope.authority_envelope_id=NEW.envelope_id
    AND envelope.state='ACTIVE' AND envelope.row_version=4
    AND envelope.last_mutation_operation_id=NEW.operation_id
    AND envelope.cose_sign1=NEW.cose_sign1)
 THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-SEALED-ACTIVATION-REQUIRED'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS identity_envelope_activation_guard ON control.identity_envelope_activation;
CREATE TRIGGER identity_envelope_activation_guard BEFORE INSERT OR UPDATE OR DELETE ON control.identity_envelope_activation
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_identity_envelope_activation();

CREATE OR REPLACE FUNCTION openpc.preserve_identity_envelope_activation_intent()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM control.identity_envelope_activation a WHERE a.participant_id=OLD.participant_id
   AND a.privacy_domain_id=OLD.privacy_domain_id AND a.idempotency_record_id=OLD.idempotency_record_id) THEN
  IF TG_OP='DELETE' OR NOT (
    (to_jsonb(NEW)-'result_digest'-'result_payload'-'result_aggregate_version'-'terminal_state')
      IS NOT DISTINCT FROM
    (to_jsonb(OLD)-'result_digest'-'result_payload'-'result_aggregate_version'-'terminal_state')
    AND OLD.terminal_state IS NULL AND NEW.terminal_state='COMMITTED'
    AND NEW.result_digest IS NOT NULL AND NEW.result_payload IS NOT NULL
    AND NEW.result_aggregate_version=4
    AND EXISTS(SELECT 1 FROM control.identity_envelope_activation a
      WHERE a.idempotency_record_id=OLD.idempotency_record_id
       AND a.operation_id=OLD.operation_id AND a.state='COMMITTED' AND a.row_version=4)
  ) THEN RAISE EXCEPTION 'PC-AUTH-0005-ENVELOPE-ACTIVATION-ORIGINAL-INTENT'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS identity_envelope_activation_idempotency ON control.idempotency_record;
CREATE TRIGGER identity_envelope_activation_idempotency BEFORE UPDATE OR DELETE ON control.idempotency_record
 FOR EACH ROW EXECUTE FUNCTION openpc.preserve_identity_envelope_activation_intent();


CREATE OR REPLACE FUNCTION openpc.guard_mfa_challenge_resource()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF (NEW.participant_id,NEW.session_id,NEW.principal_id,NEW.action_intent_id,NEW.resource_id,
     NEW.resource_digest,NEW.challenge_digest,NEW.rp_id_hash,NEW.created_at)
 IS DISTINCT FROM
    (OLD.participant_id,OLD.session_id,OLD.principal_id,OLD.action_intent_id,OLD.resource_id,
     OLD.resource_digest,OLD.challenge_digest,OLD.rp_id_hash,OLD.created_at) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-STEP-UP-BINDING-IMMUTABLE';
 END IF;
 IF OLD.consumed_at IS NOT NULL AND
   (NEW.consumed_at,NEW.signer_credential_id,NEW.signer_credential_epoch)
   IS DISTINCT FROM (OLD.consumed_at,OLD.signer_credential_id,OLD.signer_credential_epoch) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-STEP-UP-VERIFICATION-IMMUTABLE';
 END IF;
 IF OLD.used_at IS NOT NULL AND (NEW.used_at,NEW.used_operation_id) IS DISTINCT FROM (OLD.used_at,OLD.used_operation_id) THEN
  RAISE EXCEPTION 'PC-AUTH-0005-STEP-UP-CONSUMPTION-IMMUTABLE';
 END IF;
 IF OLD.consumed_at IS NULL AND NEW.consumed_at IS NOT NULL AND NOT EXISTS (
   SELECT 1 FROM control.credential credential WHERE credential.participant_id=NEW.participant_id
    AND credential.principal_id=NEW.principal_id AND credential.credential_id=NEW.signer_credential_id
    AND credential.credential_epoch=NEW.signer_credential_epoch AND credential.kind='WEBAUTHN'
    AND credential.state='ACTIVE' AND credential.valid_from<=clock_timestamp()
    AND (credential.valid_until IS NULL OR credential.valid_until>clock_timestamp())
 ) THEN RAISE EXCEPTION 'PC-AUTH-0005-STEP-UP-VERIFICATION-SIGNER'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS mfa_challenge_resource_binding ON control.mfa_challenge;
CREATE TRIGGER mfa_challenge_resource_binding BEFORE UPDATE ON control.mfa_challenge
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_mfa_challenge_resource();


CREATE OR REPLACE FUNCTION openpc.guard_wallet_binding_transition()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0002-WALLET-BINDING-RETAINED'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'ACTIVE' OR NEW.binding_epoch<>1 OR NEW.row_version<>1 THEN
   RAISE EXCEPTION 'PC-AUTH-0002-WALLET-BINDING-INITIAL-STATE';
  END IF;
 ELSE
  IF OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED' OR NEW.binding_epoch<>OLD.binding_epoch+1
   OR NEW.row_version<>OLD.row_version+1 OR NEW.last_operation_id=OLD.last_operation_id
   OR (to_jsonb(NEW)-ARRAY['state','binding_epoch','row_version','last_operation_id','updated_at'])
      IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','binding_epoch','row_version','last_operation_id','updated_at']) THEN
   RAISE EXCEPTION 'PC-AUTH-0002-WALLET-BINDING-TRANSITION';
  END IF;
 END IF;
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR NEW.last_operation_id<>current_setting('openpc.operation_id')::uuid
  OR current_setting('openpc.action_intent_id')<>'ACT-PARTICIPANTS_UPDATE_RESOURCE-V1' THEN
  RAISE EXCEPTION 'PC-AUTH-0002-WALLET-BINDING-CONTEXT';
 END IF;
 IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM control.principal subject JOIN control.participant participant USING(participant_id)
  JOIN control.privacy_domain privacy ON privacy.participant_id=subject.participant_id AND privacy.privacy_domain_id=NEW.privacy_domain_id
  WHERE subject.participant_id=NEW.participant_id AND subject.principal_id=NEW.subject_id
    AND subject.kind IN ('USER','WALLET','WORKLOAD') AND subject.state='ACTIVE'
    AND participant.state='ACTIVE' AND participant.archived_at IS NULL AND privacy.state='ACTIVE') THEN
  RAISE EXCEPTION 'PC-AUTH-0002-WALLET-BINDING-SUBJECT';
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS wallet_binding_transition ON control.wallet_binding;
CREATE TRIGGER wallet_binding_transition BEFORE INSERT OR UPDATE OR DELETE ON control.wallet_binding
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_wallet_binding_transition();

CREATE OR REPLACE FUNCTION openpc.require_wallet_binding_mutation()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
DECLARE mutation text:=CASE WHEN TG_OP='INSERT' THEN 'CREATE' ELSE 'REVOKE' END;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.mutation_evidence evidence
  JOIN control.idempotency_record receipt ON receipt.participant_id=evidence.participant_id
   AND receipt.privacy_domain_id=evidence.privacy_domain_id AND receipt.operation_id=evidence.operation_id
   AND receipt.catalog_operation_id=evidence.catalog_operation_id AND receipt.input_digest=evidence.candidate_digest
  JOIN control.mutation_candidate candidate ON candidate.participant_id=evidence.participant_id
   AND candidate.privacy_domain_id=evidence.privacy_domain_id AND candidate.consumed_operation_id=evidence.operation_id
   AND candidate.catalog_operation_id=evidence.catalog_operation_id AND candidate.candidate_digest=evidence.candidate_digest
  WHERE evidence.participant_id=NEW.participant_id AND evidence.privacy_domain_id=NEW.privacy_domain_id
   AND evidence.operation_id=NEW.last_operation_id AND evidence.aggregate_type='wallet-binding'
   AND evidence.aggregate_id=NEW.wallet_binding_id AND evidence.catalog_operation_id='ID-OP-WALLET-BINDING-'||mutation
   AND evidence.action_intent_id='ACT-PARTICIPANTS_UPDATE_RESOURCE-V1'
   AND candidate.resource_id=NEW.wallet_binding_id AND candidate.state='CONSUMED'
   AND candidate.expected_revision=NEW.row_version-1
   AND candidate.candidate_document->>'walletBindingId'=NEW.wallet_binding_id::text
   AND (CASE WHEN mutation='CREATE' THEN
    candidate.candidate_document->>'participantId'=NEW.participant_id::text
    AND candidate.candidate_document->>'subjectId'=NEW.subject_id::text
    AND candidate.candidate_document->>'chainId'=NEW.chain_id::text
    AND candidate.candidate_document->>'walletAddress'=NEW.wallet_address
    ELSE candidate.candidate_document->>'state'='REVOKED' END)
   AND receipt.terminal_state='COMMITTED'
   AND receipt.result_payload->>'walletBindingId'=NEW.wallet_binding_id::text
   AND receipt.result_payload->>'participantId'=NEW.participant_id::text
   AND receipt.result_payload->>'privacyDomainId'=NEW.privacy_domain_id::text
   AND receipt.result_payload->>'subjectId'=NEW.subject_id::text
   AND receipt.result_payload->>'chainId'=NEW.chain_id::text
   AND receipt.result_payload->>'walletAddress'=NEW.wallet_address
   AND receipt.result_payload->>'operationId'=NEW.last_operation_id::text
   AND receipt.result_payload->>'state'=NEW.state
   AND receipt.result_payload->>'bindingEpoch'=NEW.binding_epoch::text
   AND receipt.result_payload->>'revision'=NEW.row_version::text
   AND receipt.result_payload->>'permissionEffect'='NONE_WITHOUT_EFFECTIVE_AUTHORITY') THEN
  RAISE EXCEPTION 'PC-AUTH-0002-WALLET-BINDING-PROVENANCE';
 END IF;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS wallet_binding_mutation_provenance ON control.wallet_binding;
CREATE CONSTRAINT TRIGGER wallet_binding_mutation_provenance AFTER INSERT OR UPDATE ON control.wallet_binding
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_wallet_binding_mutation();


CREATE OR REPLACE FUNCTION openpc.guard_human_membership()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM control.principal principal
   WHERE principal.participant_id=NEW.participant_id AND principal.principal_id=NEW.membership_id
     AND principal.kind IN ('USER','PLATFORM_OPERATOR')) THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-MEMBERSHIP-KIND';
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS membership_human_identity ON control.participant_membership;
CREATE TRIGGER membership_human_identity BEFORE INSERT ON control.participant_membership
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_human_membership();
CREATE OR REPLACE FUNCTION openpc.guard_member_principal_kind()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
BEGIN
 IF NEW.kind<>OLD.kind AND EXISTS (SELECT 1 FROM control.participant_membership membership
   WHERE membership.participant_id=OLD.participant_id AND membership.membership_id=OLD.principal_id) THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-MEMBERSHIP-KIND';
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS member_principal_kind ON control.principal;
CREATE TRIGGER member_principal_kind BEFORE UPDATE OF kind ON control.principal
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_member_principal_kind();
CREATE OR REPLACE FUNCTION openpc.guard_removed_membership()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
BEGIN
 IF OLD.state='OFFBOARDED' AND NEW.state<>OLD.state AND EXISTS (
   SELECT 1 FROM control.participant_membership membership
    WHERE membership.participant_id=OLD.participant_id AND membership.membership_id=OLD.principal_id) THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-MEMBERSHIP-TERMINAL';
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS removed_membership_terminal ON control.principal;
CREATE TRIGGER removed_membership_terminal BEFORE UPDATE OF state ON control.principal
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_removed_membership();
DROP TRIGGER IF EXISTS identity_subject_immutable ON control.identity_subject;
CREATE TRIGGER identity_subject_immutable BEFORE UPDATE OR DELETE ON control.identity_subject
 FOR EACH ROW EXECUTE FUNCTION openpc.reject_mutation();
DROP TRIGGER IF EXISTS membership_binding_immutable ON control.participant_membership;
CREATE TRIGGER membership_binding_immutable BEFORE UPDATE OR DELETE ON control.participant_membership
 FOR EACH ROW EXECUTE FUNCTION openpc.reject_mutation();


CREATE OR REPLACE FUNCTION openpc.guard_identity_oidc_reservation()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,control AS $$
BEGIN
 IF TG_OP='DELETE' OR current_user<>'openpc_identity_binding_owner' THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-IDENTITY-RESERVATION';
 END IF;
 IF TG_OP='UPDATE' AND (OLD.state<>'UNVERIFIED_LEGACY' OR
   (NEW.issuer,NEW.subject,NEW.audience,NEW.created_at) IS DISTINCT FROM (OLD.issuer,OLD.subject,OLD.audience,OLD.created_at) OR
   NOT ((NEW.state='BOUND' AND NEW.identity_subject_id=OLD.identity_subject_id) OR
        (NEW.state='AMBIGUOUS_LEGACY' AND NEW.identity_subject_id IS NULL))) THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-IDENTITY-RESERVATION';
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS identity_oidc_reservation_immutable ON control.identity_oidc_binding;
CREATE TRIGGER identity_oidc_reservation_immutable BEFORE UPDATE OR DELETE ON control.identity_oidc_binding
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_identity_oidc_reservation();

CREATE OR REPLACE FUNCTION openpc.observe_oidc_identity_claim()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,control AS $$
DECLARE local_subject uuid; existing control.identity_oidc_binding%ROWTYPE; qualified boolean;
BEGIN
 IF TG_OP='UPDATE' AND OLD.kind='OIDC_SUBJECT' AND
   (OLD.kind,OLD.participant_id,OLD.principal_id,OLD.issuer,OLD.subject,OLD.audience) IS DISTINCT FROM
   (NEW.kind,NEW.participant_id,NEW.principal_id,NEW.issuer,NEW.subject,NEW.audience) THEN
  RAISE EXCEPTION 'PC-IDENTITY-1002-OIDC-CLAIM-IMMUTABLE';
 END IF;
 -- Invalid legacy accounts remain unusable for proof resolution; ordinary scoped login retains its checks.
 IF NEW.kind<>'OIDC_SUBJECT' OR NEW.issuer IS NULL OR NEW.subject IS NULL OR NEW.audience IS NULL
   OR length(NEW.issuer)=0 OR length(NEW.subject) NOT BETWEEN 1 AND 255 OR length(NEW.audience)=0 THEN RETURN NEW; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(jsonb_build_array(NEW.issuer,NEW.subject,NEW.audience)::text,713));
 SELECT membership.identity_subject_id INTO local_subject FROM control.participant_membership membership
  WHERE membership.participant_id=NEW.participant_id AND membership.membership_id=NEW.principal_id;
 qualified:=local_subject IS NOT NULL AND NEW.state='ACTIVE' AND NEW.credential_epoch>0
   AND NEW.valid_from<=clock_timestamp() AND (NEW.valid_until IS NULL OR NEW.valid_until>clock_timestamp());
 SELECT * INTO existing FROM control.identity_oidc_binding
  WHERE issuer=NEW.issuer AND subject=NEW.subject AND audience=NEW.audience FOR UPDATE;
 IF NOT FOUND THEN
  INSERT INTO control.identity_oidc_binding(issuer,subject,audience,identity_subject_id,state)
   VALUES(NEW.issuer,NEW.subject,NEW.audience,CASE WHEN qualified THEN local_subject ELSE NULL END,
    CASE WHEN qualified THEN 'UNVERIFIED_LEGACY' ELSE 'AMBIGUOUS_LEGACY' END);
 ELSIF existing.state='BOUND' THEN
  -- Local revocation cannot revoke a global identity. A different local subject cannot claim it.
  IF existing.identity_subject_id IS DISTINCT FROM local_subject THEN
   RAISE EXCEPTION 'PC-IDENTITY-1002-OIDC-IDENTITY-CONFLICT';
  END IF;
 ELSIF existing.state='UNVERIFIED_LEGACY' AND (NOT qualified OR existing.identity_subject_id IS DISTINCT FROM local_subject) THEN
  UPDATE control.identity_oidc_binding SET state='AMBIGUOUS_LEGACY',identity_subject_id=NULL
   WHERE issuer=NEW.issuer AND subject=NEW.subject AND audience=NEW.audience;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS credential_oidc_identity_reservation ON control.credential;
CREATE TRIGGER credential_oidc_identity_reservation BEFORE INSERT OR UPDATE OF kind,participant_id,principal_id,issuer,subject,audience,state,credential_epoch,valid_from,valid_until ON control.credential
 FOR EACH ROW EXECUTE FUNCTION openpc.observe_oidc_identity_claim();

-- Internal proof consumer only. Possession of these arguments is not proof; the Identity
-- invitation owner verifies signed OIDC, token/version, custody and durable issuance authority first.
CREATE OR REPLACE FUNCTION openpc.resolve_proved_oidc_identity(issuer_value text,subject_value text,audience_value text)
RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,control AS $$
DECLARE existing control.identity_oidc_binding%ROWTYPE; resolved uuid;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-PARTICIPANT_CREATE_MEMBER-V1' OR issuer_value IS NULL OR subject_value IS NULL OR audience_value IS NULL
   OR length(issuer_value)=0 OR length(subject_value) NOT BETWEEN 1 AND 255 OR length(audience_value)=0 THEN
  RAISE EXCEPTION 'PC-AUTH-0002';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(jsonb_build_array(issuer_value,subject_value,audience_value)::text,713));
 SELECT * INTO existing FROM control.identity_oidc_binding
  WHERE issuer=issuer_value AND subject=subject_value AND audience=audience_value FOR UPDATE;
 IF NOT FOUND THEN
  resolved:=uuidv7();
  INSERT INTO control.identity_subject(identity_subject_id) VALUES(resolved);
  INSERT INTO control.identity_oidc_binding(issuer,subject,audience,identity_subject_id,state)
   VALUES(issuer_value,subject_value,audience_value,resolved,'BOUND');
  RETURN resolved;
 END IF;
 IF existing.state='AMBIGUOUS_LEGACY' THEN RAISE EXCEPTION 'PC-AUTH-0002'; END IF;
 IF existing.state='UNVERIFIED_LEGACY' THEN
  IF EXISTS (SELECT 1 FROM control.credential credential
    LEFT JOIN control.participant_membership membership ON membership.participant_id=credential.participant_id AND membership.membership_id=credential.principal_id
    WHERE credential.kind='OIDC_SUBJECT' AND credential.issuer=issuer_value AND credential.subject=subject_value AND credential.audience=audience_value
      AND (membership.identity_subject_id IS DISTINCT FROM existing.identity_subject_id OR credential.state<>'ACTIVE' OR credential.credential_epoch<=0
        OR credential.valid_from>clock_timestamp() OR credential.valid_until<=clock_timestamp())) THEN
   RAISE EXCEPTION 'PC-AUTH-0002';
  END IF;
  UPDATE control.identity_oidc_binding SET state='BOUND' WHERE issuer=issuer_value AND subject=subject_value AND audience=audience_value;
 END IF;
 RETURN existing.identity_subject_id;
END $$;



CREATE OR REPLACE FUNCTION openpc.signing_transition_effects(p_action text,p_prior text,p_target text)
RETURNS jsonb LANGUAGE sql IMMUTABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT effects::jsonb FROM (VALUES ('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','APPROVED','PREPARED','{"kind":"ADVANCE","providerSteps":[["new","PREPARE"]],"prepare":true,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','PREPARED','{"kind":"ADVANCE","providerSteps":[["new","PREPARE"]],"prepare":true,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":"APPROVED"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','APPROVED','APPROVED','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','APPROVED','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','PREPARED','DISTRIBUTED','{"kind":"ADVANCE","providerSteps":[["new","DISTRIBUTE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','DISTRIBUTED','{"kind":"ADVANCE","providerSteps":[["new","DISTRIBUTE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":"PREPARED"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','PREPARED','PREPARED','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','PREPARED','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','DISTRIBUTED','VERIFIED','{"kind":"ADVANCE","providerSteps":[["old","PROVE"],["new","PROVE"]],"prepare":false,"admitTrust":true,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','VERIFIED','{"kind":"ADVANCE","providerSteps":[["old","PROVE"],["new","PROVE"]],"prepare":false,"admitTrust":true,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":"DISTRIBUTED"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','DISTRIBUTED','DISTRIBUTED','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','DISTRIBUTED','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','VERIFIED','CUTOVER_FENCED','{"kind":"ADVANCE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":true,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','CUTOVER_FENCED','{"kind":"ADVANCE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":true,"revoke":false,"eventType":null,"resumeFrom":"VERIFIED"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','VERIFIED','VERIFIED','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','VERIFIED','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','CUTOVER_FENCED','OBSERVING','{"kind":"ADVANCE","providerSteps":[["effective","PROVE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','OBSERVING','{"kind":"ADVANCE","providerSteps":[["effective","PROVE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":"CUTOVER_FENCED"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','CUTOVER_FENCED','CUTOVER_FENCED','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','CUTOVER_FENCED','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','OBSERVING','OLD_REVOKED','{"kind":"ADVANCE","providerSteps":[["old","REVOKE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":true,"eventType":"io.openpc.ops.secret.revoked.v1","resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','OLD_REVOKED','{"kind":"ADVANCE","providerSteps":[["old","REVOKE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":true,"eventType":"io.openpc.ops.secret.revoked.v1","resumeFrom":"OBSERVING"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','OBSERVING','OBSERVING','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','OBSERVING','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','OLD_REVOKED','OLD_RETIRED','{"kind":"ADVANCE","providerSteps":[["old","RETIRE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','OLD_RETIRED','{"kind":"ADVANCE","providerSteps":[["old","RETIRE"]],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":"OLD_REVOKED"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','OLD_REVOKED','OLD_REVOKED','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','OLD_REVOKED','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','OLD_RETIRED','COMPLETE','{"kind":"ADVANCE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":"io.openpc.ops.secret.rotated.v1","resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','COMPLETE','{"kind":"ADVANCE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":"io.openpc.ops.secret.rotated.v1","resumeFrom":"OLD_RETIRED"}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','OLD_RETIRED','OLD_RETIRED','{"kind":"RENEWAL","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','OLD_RETIRED','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','APPROVED','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','PREPARED','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','DISTRIBUTED','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','VERIFIED','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','CUTOVER_FENCED','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','OBSERVING','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','OLD_REVOKED','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','OLD_RETIRED','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_ADVANCE_RESOURCE-V1','RECOVERING','FAILED','{"kind":"FAILURE","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','RECOVERING','RECOVERING','{"kind":"RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}'),
('ACT-SIGNING_KEY_ROTATIONS_RECOVER_RESOURCE-V1','FAILED','RECOVERING','{"kind":"FORWARD_RECOVERY","providerSteps":[],"prepare":false,"admitTrust":false,"cutover":false,"revoke":false,"eventType":null,"resumeFrom":null}')) matrix(action,prior,target,effects)
 WHERE action=p_action AND prior=p_prior AND target=p_target
$$;

